INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `slug`, `description`, `release_year`, `poster_path`, `rating`, `created_at`) VALUES
(1, NULL, 'Inception', 'inception', 'A thief who steals corporate secrets through the use of dream-sharing technology.', 2010, 'inception.jpg', 8.8, '2026-08-07 08:40:18'),
(2, NULL, 'The Dark Knight', 'the-dark-knight', 'When the menace known as the Joker wreaks havoc on Gotham.', 2008, 'dark_knight.jpg', 9.0, '2026-08-07 08:40:18'),
(3, NULL, 'Interstellar', 'interstellar', 'A team of explorers travel through a wormhole in space.', 2014, 'interstellar.jpg', 8.6, '2026-08-07 08:40:18'),
(4, NULL, 'The Hangover', 'the-hangover', 'Three buddies wake up from a bachelor party in Las Vegas.', 2009, 'hangover.jpg', 7.7, '2026-08-07 08:40:18'),
(5, NULL, 'About Time', 'about-time', 'A young man discovers he can travel in time.', 2013, 'about_time.jpg', 7.8, '2026-08-07 08:40:18'),
(6, NULL, 'The Conjuring', 'the-conjuring', 'Paranormal investigators work to help a family terrorized by a dark presence.', 2013, 'conjuring.jpg', 7.5, '2026-08-07 08:40:18'),
(7, NULL, 'The Matrix', 'the-matrix', 'A computer hacker learns from mysterious rebels about the true nature of his reality.', 1999, 'matrix.jpg', 8.7, '2026-08-07 08:40:18'),
(8, NULL, 'Up', 'up', 'Balloon-lifting house takes an old man on an adventure.', 2009, 'up.jpg', 8.3, '2026-08-07 08:40:18'),
(9, NULL, 'The Notebook', 'the-notebook', 'A poor young man falls in love with a rich young woman.', 2004, 'notebook.jpg', 7.8, '2026-08-07 08:40:18'),
(10, NULL, 'Shutter Island', 'shutter-island', 'A U.S. Marshal investigates the disappearance of a patient.', 2010, 'shutter_island.jpg', 8.2, '2026-08-07 08:40:18'),
(11, 969681, 'Người Nhện: Khởi Đầu Mới', 'tmdb-969681-ngi-nhn-khi-du-mi', 'Không còn Tony Stark, MJ hay Ned kề cận, Peter buộc phải đơn thân độc mã đối diện với phe đối đầu bí ẩn. Tuy nhiên, khi áp lực ngày càng gia tăng, nó kích hoạt một sự biến đổi thể chất bất ngờ, đe dọa chính sự tồn tại của anh. Đồng thời, một chuỗi tội phạm bí ẩn mới xuất hiện, kéo theo một trong những mối đe dọa mạnh mẽ nhất mà Spider-Man từng đối mặt.', 2026, '/wqGZVSCUSXE92WH2zyol2REaqT4.jpg', 7.9, '2026-08-12 03:55:00'),
(12, 1368337, 'The Odyssey', 'tmdb-1368337-the-odyssey', 'Câu chuyện theo chân Odysseus trong hành trình kéo dài 10 năm trở về nhà sau cuộc chiến thành Troy, nơi ông phải đối mặt với các vị thần, quái vật và vô vàn thử thách, đồng thời nỗ lực đoàn tụ với vợ và giành lại vương quốc của mình.', 2026, '/7876PK6gosE13Uq1B6nRxf7AJLT.jpg', 8.0, '2026-08-12 03:55:00'),
(13, 634649, 'Người Nhện: Không Còn Nhà', 'tmdb-634649-ngi-nhn-kh-ong-c-on-nh-a', 'Peter Parker đã bị lộ mặt và không còn có thể tách biệt cuộc sống bình thường của mình với những yêu cầu cao của việc trở thành một Siêu anh hùng. Khi anh ta yêu cầu sự giúp đỡ từ Doctor Strange, mọi thứ càng trở nên nguy hiểm hơn, buộc anh ta phải khám phá ra ý nghĩa thực sự của việc trở thành Người Nhện.', 2021, '/y4SQ2dJ1y2LBUnxTH7hCe8sr29c.jpg', 7.9, '2026-08-12 03:55:00'),
(14, 1284041, 'Ngôi nhà cuối cùng', 'tmdb-1284041-ng-oi-nha-cu-oi-cung', 'Một gia đình mắc kẹt một cách bí ẩn trong ngôi nhà phải đoàn kết để sinh tồn khi nhu yếu phẩm cạn kiệt và một thế lực đáng sợ không để họ thoát ra.', 2026, '/6JU7E8Vv2M11egkctWVOScxWR75.jpg', 6.8, '2026-08-12 03:55:00'),
(15, 1081003, 'Supergirl', 'tmdb-1081003-supergirl', 'Khi một kẻ thù tàn nhẫn và không ngờ tới ra tay quá gần với những gì cô trân quý, Kara Zor-El, còn được biết đến với cái tên Supergirl, miễn cưỡng hợp tác với một người đồng hành không ai ngờ tới, bước vào hành trình liên thiên hà đầy sử thi để tìm kiếm sự trả thù và công lý.', 2026, '/duXkWKOLS7hHAddyjBwk35YY6U.jpg', 6.7, '2026-08-12 03:55:00'),
(16, 1084244, 'Câu Chuyện Đồ Chơi 5', 'tmdb-1084244-c-au-chuyn-d-chi-5', 'Khi Bonnie được tặng chiếc máy tính bảng Lilypad và dần mê mẩn món đồ chơi mới, Buzz, Woody, Jessie cùng cả nhóm bỗng đứng trước nguy cơ bị lãng quên. Để giành lại giờ chơi, họ phải đối đầu với “đối thủ” hiện đại nhất từ trước đến nay: một màn hình nhỏ nhưng có sức hút quá lớn.', 2026, '/8ZE3s8PN5yRpTidymRWpI0jvs7j.jpg', 7.4, '2026-08-12 03:55:00'),
(17, 1375646, 'Bầy Xác Sống', 'tmdb-1375646-by-x-ac-sng', 'Giáo sư Se Jeong tham dự một hội nghị công nghệ sinh học, nhưng lại chứng kiến ​​nó biến thành thảm họa khi một loại virus đột biến nhanh chóng được giải phóng. Khi dịch bệnh lan rộng và những người nhiễm bệnh bắt đầu biến đổi, chính quyền đã phong tỏa toàn bộ cơ sở.', 2026, '/lzI70txBtLH5kCUixYMJQffKkL9.jpg', 8.1, '2026-08-12 03:55:00'),
(18, 1212763, 'Ma Cây: Lửa Địa Ngục', 'tmdb-1212763-ma-c-ay-la-da-ngc', '', 2026, '/yAtHcEJdoIjV2BJUvZz89A88pAB.jpg', 7.9, '2026-08-12 03:55:00'),
(19, 1284465, 'Cái Chết của Robin Hood', 'tmdb-1284465-c-ai-cht-ca-robin-hood', 'Vật lộn với quá khứ sau một đời đầy tội lỗi và đổ máu, Robin Hood bị trọng thương sau trận chiến mà anh tưởng là cuối cùng. Rơi vào tay một người phụ nữ bí ẩn, anh được trao cho một cơ hội chuộc lỗi và tìm kiếm sự cứu rỗi.', 2026, '/92Tsfx7SFafOqWsotvrlJbHyehd.jpg', 6.4, '2026-08-12 03:55:00'),
(20, 1339713, 'Ám Ảnh', 'tmdb-1339713-am-nh', 'Sau khi bẻ gãy \"Liễu Ước Nguyện\" thần bí để có được người mình thầm yêu, gã si tình rốt cuộc cũng cầu được ước thấy, để rồi kinh hãi nhận ra cái giá tăm tối phía sau lời ước đó.', 2026, '/15qLAM3QM8DoPL9Fps4JOTdqWqt.jpg', 8.2, '2026-08-12 03:55:00'),
(21, 1275779, 'Thời Khắc Công Bố', 'tmdb-1275779-thi-khc-c-ong-b', 'Nếu một ngày bạn nhận ra rằng chúng ta chưa bao giờ đơn độc, nếu có ai đó đứng trước mặt bạn và chứng minh điều đó là sự thật, liệu việc đó khiến bạn sợ hãi? Mùa Hè 2026, sự thật nằm trong tay của bảy tỷ con người. Chúng ta đang tiến rất gần đến… Thời Khắc Công Bố.', 2026, '/nI4uPl4E3No8674XnyY8zJpceBS.jpg', 7.4, '2026-08-12 03:55:00'),
(22, 1315772, 'Minions & Quái Vật', 'tmdb-1315772-minions-qu-ai-vt', 'Đây là câu chuyện có thật, đầy náo nhiệt, lố bịch và vô cùng điên rồ về cách các Minion chinh phục Hollywood, trở thành ngôi sao điện ảnh, rồi đánh mất tất cả, vô tình giải phóng những quái vật ra thế giới và cuối cùng buộc phải sát cánh bên nhau để cứu lấy Trái Đất khỏi chính mớ hỗn loạn mà họ đã gây ra.', 2026, '/z8OWDTR7pQuZi7jkEuR7yMXRrQt.jpg', 6.9, '2026-08-12 03:55:00'),
(23, 1108427, 'Hành Trình Của Moana', 'tmdb-1108427-h-anh-tr-inh-ca-moana', 'Nghe theo tiếng gọi của Đại Dương, Moana dũng cảm rời đảo Motunui, lần đầu vượt qua rạn san hô để khám phá thế giới rộng lớn. Cùng á thần Maui, cô bắt đầu hành trình phiêu lưu đầy kỳ diệu với sứ mệnh mang lại sự thịnh vượng cho quê hương.', 2026, '/lwqKqiBsGVBtQBZF9ZTunthBCyI.jpg', 6.0, '2026-08-12 03:55:00'),
(24, 315635, 'Người Nhện: Trở Về Nhà', 'tmdb-315635-ngi-nhn-tr-v-nh-a', 'Tạm biệt hai franchise về thời sinh viên, Spider-Man: Homecoming sẽ lần đầu tiên đưa các khán giả đến với cuộc sống trung học của Peter Paker – siêu anh hùng Người Nhện. Liệu một cậu bé chưa trưởng thành sẽ làm thế nào để cân bằng cuộc sống bình thường và trách nhiệm của một anh hùng giải cứu thế giới. Đây cũng là lần đầu tiên, series Người Nhện có sự tham gia sản xuất của Marvel Studio và sự xuất hiện của Iron Man – Robert Downey Jr.', 2017, '/tNm6pNf9Xe1gPKu4xqPEWj0issu.jpg', 7.3, '2026-08-12 03:55:00'),
(25, 1599191, '仙逆剧场版 弑仙之战', 'tmdb-1599191-movie', '', NULL, '/m1dXI1997D7lj6Sh0Z2DI26o2nI.jpg', 0.0, '2026-08-12 03:55:00'),
(26, 1481343, 'The Devil\'s Mouth', 'tmdb-1481343-the-devil-s-mouth', '', 2026, '/lH8k9uCWYn2b2gsYleqYBDPbWa8.jpg', 6.5, '2026-08-12 03:55:00'),
(27, 1083381, 'Backrooms: Thực Thể Quỷ Quyệt', 'tmdb-1083381-backrooms-thc-th-qu-quyt', 'Backrooms theo chân Clark, một chủ cửa hàng nội thất, vô tình phát hiện cánh cửa bí ẩn dưới tầng hầm. Bước qua đó, anh bị cuốn vào một chiều không gian vô tận với những căn phòng màu vàng méo mó, liên tục lặp lại. Khi Clark ngày càng lún sâu và ám ảnh, nhà trị liệu tâm lý của anh là Mary quyết định bước vào không gian đó để tìm và giải cứu anh.', 2026, '/7uabN7xF4209cDUdBuMvkVcpkN2.jpg', 7.1, '2026-08-12 03:55:00'),
(28, 1307118, 'Soulm8te', 'tmdb-1307118-soulm8te', '', 2026, '/bNErActDctl6cdUGw9pnjSCmyhQ.jpg', 6.5, '2026-08-12 03:55:00'),
(29, 557, 'Người Nhện', 'tmdb-557-ngi-nhn', 'Peter Parker là một sinh viên trẻ và nhút nhát, đã sống với dì May và chú Ben kể từ khi cha mẹ anh ta mất khi anh ta còn rất nhỏ. Peter yêu người hàng xóm xinh đẹp của mình, nhưng sự thiếu lôi cuốn của anh ta không khiến anh ta trở nên nổi tiếng ở trường trung học. Một ngày nọ, anh ta bị cắn bởi một con nhện đã bị biến đổi gen, phát hiện ra ngày hôm sau anh ta sở hữu sức mạnh khác thường: anh ta có sức mạnh và sự nhanh nhẹn của một con nhện. Cuộc phiêu lưu của Người Nhện, dựa trên truyện tranh nổi tiếng Stan Lee và Steve Ditko, đã càn quét phòng vé Mỹ và phá vỡ kỷ lục phá vỡ kỷ lục vào cuối tuần đầu tiên của anh: 114 triệu đô la, lần đầu tiên trong lịch sử, anh tìm cách phá vỡ Rào cản 100 triệu đô la vào một ngày cuối tuần bình thường.', 2002, '/w55KSeyhH3nXjzx7AhbNq0DO3zt.jpg', 7.3, '2026-08-12 03:55:00'),
(30, 1698863, 'The Odyssey', 'tmdb-1698863-the-odyssey', '', 2026, '/xBHCRB7zLIW41w8QskfwJhm32YF.jpg', 6.2, '2026-08-12 03:55:00'),
(31, 454639, 'He-Man và Những Chiến Binh Vũ Trụ', 'tmdb-454639-he-man-va-nhng-chi-en-binh-vu-tru', 'Thương hiệu huyền thoại trở lại màn ảnh rộng. Sau 15 năm thất lạc, Thanh Gươm Quyền Năng đưa Hoàng tử Adam (Nicholas Galitzine) trở về hành tinh Eternia và phát hiện quê hương đã rơi vào sự cai trị tàn bạo của Skeletor (Jared Leto). Để cứu gia đình và thế giới của mình, Adam phải sát cánh cùng những đồng minh thân cận như Teela (Camila Mendes) và Duncan/Man-At-Arms (Idris Elba), đồng thời chấp nhận định mệnh thật sự của mình: trở thành He-Man - người đàn ông mạnh nhất vũ trụ.', 2026, '/3zJKDkvyTz3g6VpCS6RtaufYV0j.jpg', 7.2, '2026-08-12 13:54:29'),
(32, 1273221, 'Phim Kinh Dị', 'tmdb-1273221-phim-kinh-d', 'Hai mươi sáu năm sau khi thoát khỏi tên sát nhân Ghostface nguyên bản, nhóm Core Four - gồm Cindy, Brenda, Shorty và Ray lại rơi vào tình thế nguy hiểm. Lúc này, Cindy đã trở thành một người mẹ luôn sống trong lo âu và mang theo súng bên mình, cô buộc phải ra tay giải cứu thế hệ trẻ, đứng đầu là Sara và Tuesday. Khi tên sát nhân đeo mặt nạ tái xuất, cả những gương mặt cũ được yêu thích lẫn các nhân vật mới đều cùng nhau châm biếm những mô-típ phim kinh dị hiện đại, các bản tái khởi động, câu chuyện về nguồn gốc nhân vật và các phần phim ngoại truyện', 2026, '/4i90SNCZb3CFXVs5xlEjm5RuonP.jpg', 6.5, '2026-08-12 13:54:29'),
(33, 980431, 'Huyền Thoại Aang: Tiết Khí Sư Cuối Cùng', 'tmdb-980431-huyn-thoi-aang-tit-kh-i-s-cui-c-ung', 'Bộ phim tập trung vào giai đoạn hậu chiến tranh, khi thế giới đang trong quá trình tái thiết và đối mặt với những mối đe dọa mới tinh vi hơn từ các tàn dư chính trị. Aang phải gánh vác trọng trách duy trì sự cân bằng giữa bốn quốc gia, đồng thời đối diện với những áp lực của một Thế Thần trưởng thành. Phim hứa hẹn sẽ khai thác sâu hơn về sức mạnh của Aang ở thời kỳ đỉnh cao và mối quan hệ bền chặt của nhóm bạn sau nhiều năm gắn bó.', 2026, '/gf7EeEQe22Zu1u55wRT8EAnav93.jpg', 9.3, '2026-08-12 13:54:29'),
(34, 1564614, 'Leviticus: Bóng Quỷ', 'tmdb-1564614-leviticus-b-ong-qu', '2 chàng trai tuổi teen phải tìm cách trốn thoát khỏi một thực thể bạo tàn có thể mang hình hài của người mà họ khao khát nhất — chính là nhau.', 2026, '/r30blmL8bB7WFzdAcXu7gJMUYk8.jpg', 6.7, '2026-08-12 13:54:29'),
(35, 687163, 'Thoát Khỏi Tận Thế', 'tmdb-687163-tho-at-khi-tn-th', 'Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.', 2026, '/7NzV9SN5ocWzMrdQw9fFDgLYVJC.jpg', 8.7, '2026-08-12 13:54:29'),
(36, 1311031, 'Thanh Gươm Diệt Quỷ: Vô Hạn Thành', 'tmdb-1311031-thanh-gm-dit-qu-v-o-hn-th-anh', 'Khi các thành viên của Sát Quỷ Đoàn và Trụ Cột tham gia vào chương trình đặc huấn để chuẩn bị cho trận chiến sắp với lũ quỷ, Kibutsuji Muzan xuất hiện tại Dinh thự Ubuyashiki. Khi thủ lĩnh của Sát Quỷ Đoàn gặp nguy hiểm, Tanjiro và các Trụ Cột trở về trụ sở Thế nhưng, Muzan bất ngờ kéo toàn bộ Sát Quỷ Đoàn đến hang ổ cuối cùng của lũ quỷ là Vô Hạn Thành, mở màn cho trận đánh cuối cùng của cả hai phe.', 2025, '/nV99ACeAa8fFFso0tQZ3HktEf5X.jpg', 8.7, '2026-08-12 13:54:29'),
(37, 1594914, 'Lucky Strike', 'tmdb-1594914-lucky-strike', '', 2026, '/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', 7.6, '2026-08-12 13:54:29'),
(38, 1630409, 'คนเดือดทวงแค้น', 'tmdb-1630409-movie', '', 2026, '/2h4ikWt6TddvIAhMdS3WGVXhaRf.jpg', 7.8, '2026-08-12 13:54:29'),
(39, 1727780, 'Borderline', 'tmdb-1727780-borderline', '', 2026, '/sAA2mjpYJFAKydtzG4P4aHC4mZk.jpg', 5.9, '2026-08-12 13:54:29'),
(40, 429617, 'Người Nhện: Xa Nhà', 'tmdb-429617-ngi-nhn-xa-nh-a', 'Bạn biết vì sao Avengers: Endgame không có after-credit không? Bởi vì ngay sau câu chuyện đó chính là sự ra mắt của Spider-Man: Far From Home đấy. Trở lại sau sự ra đi của người chú Tony – Iron Man, có vẻ như cậu bé Peter đã không còn đủ động lực, niềm tin để tiếp tục theo đuổi giấc mơ làm siêu anh hùng. Nhưng đời đâu phải lúc nào cũng như ý ta mong muốn! Nhất là khi ở ngoài kia, vẫn còn vô vàn kẻ xấu khác cần tiêu diệt. Trong chuyến du lịch đến châu Âu, Peter Parker và những người bạn của mình rơi vào rắc rối mới. Không những vậy, cậu còn được diện kiến Nick Fury. Liệu thử thách mới của Spider-Man sẽ khó khăn đến mức độ nào? Dù \"gan to\" cúp điện thoại của Nick Fury Peter vẫn phải hợp tác cùng ông để tiếp tục hành trình bảo vệ thế giới của chú Tony. Bên cạnh Nick Fury, Spider-Man: Far From Home còn có sự xuất hiện của một gương mặt mới là Mysterio. Liệu đây sẽ là nhân vật phản diện hay chính diện?', 2019, '/pkUEHB1CYfPj5K8Td484TT9mBF1.jpg', 7.4, '2026-08-12 13:54:29'),
(41, 1314481, 'Yêu Nữ Thích Hàng Hiệu 2', 'tmdb-1314481-y-eu-n-th-ich-h-ang-hiu-2', 'Hai mươi năm sau màn hóa thân kinh điển vào các vai diễn Miranda, Andy, Emily và Nigel — Meryl Streep, Anne Hathaway, Emily Blunt và Stanley Tucci sẽ chính thức trở lại với những con phố thời thượng của New York và văn phòng sang trọng của Tạp chí Runway trong \"The Devil Wears Prada 2\" (Yêu Nữ Thích Hàng Hiệu 2). Đây là phần phim tiếp theo cực kỳ được mong đợi từ 20th Century Studios, kế thừa sức hút từ hiện tượng điện ảnh năm 2006 từng định hình phong cách cho cả một thế hệ. Bộ phim được đạo diễn bởi David Frankel, kịch bản bởi Aline Brosh McKenna, sản xuất bởi Wendy Finerman, điều hành sản xuất bởi Michael Bederman, Karen Rosenfelt và Aline Brosh McKenna.', 2026, '/hhCEHR0OKeVJUiQLtiI6GBbUeAe.jpg', 7.1, '2026-08-12 13:54:29'),
(42, 82976, 'Les Novices', 'tmdb-82976-les-novices', '', 1970, '/4Ppq2oJPnEqSeyliPG9QbCHUL0q.jpg', 4.8, '2026-08-12 13:54:29'),
(43, 1110034, 'Quái Vật Biển', 'tmdb-1110034-qu-ai-vt-bin', 'Bối cảnh đặt vào thời Chiến tranh Lạnh, một tàu ngầm tên lửa Nga biến mất bí ẩn trên Biển Greenland. Đại úy Viktor Voronin (Alexander Petrov) — người em của chỉ huy tàu mất tích — dẫn đầu chiến dịch cứu hộ. Trong khi đó, một căn cứ địa chất ở Bắc Cực vô tình đánh thức con Kraken—một quái vật biển sâu khổng lồ với khả năng ngụy trang siêu việt và trí thông minh đáng sợ. Khi nhóm cứu hộ tiếp cận khu vực tàu ngầm mất tích, họ cũng phải đối mặt với sinh vật huyền thoại đang nổi lên từ đáy đại dương', 2026, '/uUCVGVWnBgIf6NV3AqHpJcCBC8T.jpg', 6.3, '2026-08-12 13:54:29'),
(44, 1510795, 'Ác Quỷ Ma Sơ', 'tmdb-1510795-ac-qu-ma-s', 'Phim gồm 3 câu chuyện với những thảm án lần lượt tại 3 thời điểm khác nhau. Năm 1775, trong thời kỳ thuộc địa Tây Ban Nha ở Philippines, các nữ tu cố gắng sống sót qua đêm sau khi một thế lực tà ác vô danh được giải phóng trong tu viện của họ. Trong khi đó, vào năm 2025, một nhóm bạn tham dự dạ tiệc hóa trang Halloween thì bị một kẻ giết người hàng loạt tấn công. Đến tương lai, vào năm 2050, Philippines rơi vào hỗn độn trong bối cảnh hậu tận thế bị loài Aswang cai trị.', 2026, '/jnawP0Oe76yJRMVap2t8DPSjIpW.jpg', 4.0, '2026-08-12 13:54:29'),
(45, 936075, 'Michael', 'tmdb-936075-michael', 'Michael là bức chân dung điện ảnh khắc họa cuộc đời và di sản của một trong những nghệ sĩ có sức ảnh hưởng lớn nhất mà thế giới từng biết đến. Bộ phim kể về cuộc đời của Michael Jackson ngoài âm nhạc, theo dấu hành trình từ khi tài năng phi thường của ông được phát hiện trong vai trò giọng ca chính của nhóm Jackson Five, cho đến khi ông trở thành một nghệ sĩ có tầm nhìn xa, với khát vọng sáng tạo không ngừng để vươn tới danh hiệu “ngôi sao giải trí vĩ đại nhất thế giới”. Cho thấy cuộc sống phía sau hào quang sân khấu lẫn những màn trình diễn mang tính biểu tượng nhất trong giai đoạn đầu sự nghiệp solo, bộ phim mang đến cho khán giả một góc nhìn chân thực hơn bao giờ hết về Michael Jackson. Đây chính là nơi câu chuyện của ông bắt đầu.', 2026, '/sXP7VzpnHQIThf5v6b64XaczEK2.jpg', 8.7, '2026-08-12 13:54:29'),
(46, 1930, 'Người Nhện Siêu Đẳng', 'tmdb-1930-ngi-nhn-si-eu-dng', 'Amazing Spider-Man hay Siêu Nhện Tái Xuất có khá nhiều khác biệt so với các phần trước tập trung ở sự khác biệt ở tính cách của các nhân vật, Peter không còn là cậu bé nhút nhát mà khá nghịch ngợm, bên cạnh đó đạo diễn Marc Webb cũng mạnh dạn đưa ra thêm nhiều thay đổi về cốt truyện để Amazing Spider-Man thực sự mới lạ so với các phiên bản cũ.  Cha mẹ Peter biến mất bí ấn và để cậu cho cô chú nuôi nấng. Sự tò mò về thân phận của bản thân lẫn những điều chưa biết về cha mẹ luôn thôi thúc cậu.  Peter tìm thấy tập tài liệu mà cha để lại. Từ đây, những manh mối dẫn cậu tới tập đoàn Oscorp và người cộng sự của ông. Một tai nạn tại Oscorp khiến Peter có những siêu năng lực của loài nhện, Người nhện xuất hiện bí ẩn trong lòng New York.', 2012, '/5ObdzkfZBV3b9fcF5IISMPPknxv.jpg', 6.7, '2026-08-12 13:54:29'),
(47, 1698856, 'He-Man Và Những Chiến Binh Vũ Trụ', 'tmdb-1698856-he-man-va-nhng-chi-en-binh-vu-tru', 'Thương hiệu huyền thoại trở lại màn ảnh rộng. Sau 15 năm thất lạc, Thanh Gươm Quyền Năng đưa Hoàng tử Adam (Nicholas Galitzine) trở về hành tinh Eternia và phát hiện quê hương đã rơi vào sự cai trị tàn bạo của Skeletor (Jared Leto). Để cứu gia đình và thế giới của mình, Adam phải sát cánh cùng những đồng minh thân cận như Teela (Camila Mendes) và Duncan/Man-At-Arms (Idris Elba), đồng thời chấp nhận định mệnh thật sự của mình: trở thành He-Man - người đàn ông mạnh nhất vũ trụ.', 2026, '/a77OcLmarwiBJakOPPC36m58t4L.jpg', 4.8, '2026-08-12 13:54:29'),
(48, 1404304, 'The Isolate Thief', 'tmdb-1404304-the-isolate-thief', '', 2026, '/gmmCh2BvTKp0YGT2FYG0eOQJELi.jpg', 7.4, '2026-08-12 13:54:29'),
(49, 1523145, 'Твоё сердце будет разбито', 'tmdb-1523145-movie', '', 2026, '/iGpMm603GUKH2SiXB2S5m4sZ17t.jpg', 7.1, '2026-08-12 13:54:29'),
(50, 299536, 'Avengers 3: Cuộc Chiến Vô Cực', 'tmdb-299536-avengers-3-cuc-chin-v-o-cc', 'Sau chuyến hành trình độc nhất vô nhị không ngừng mở rộng và phát triển vụ trũ điện ảnh Marvel, bộ phim Avengers: Cuộc Chiến Vô Cực sẽ mang đến màn ảnh trận chiến cuối cùng khốc liệt nhất mọi thời đại. Biệt đội Avengers và các đồng minh siêu anh hùng của họ phải chấp nhận hy sinh tất cả để có thể chống lại kẻ thù hùng mạnh Thanos trước tham vọng hủy diệt toàn bộ vũ trụ của hắn.', 2018, '/8gHc1cthgTOkmMiOREodCVZgJ7P.jpg', 8.2, '2026-08-12 13:54:29'),
(51, 1127384, 'Vùng Biển Chết Chóc', 'tmdb-1127384-v-ung-bin-cht-ch-oc', '', 2026, '/kjcuS7xaRyqRjVaVcH4t0qHshuX.jpg', 7.2, '2026-08-12 13:54:31'),
(52, 102382, 'Người Nhện Siêu Đẳng 2', 'tmdb-102382-ngi-nhn-si-eu-dng-2', '“Mỗi ngày tôi thức dậy và biết rằng, tôi càng cố cứu thêm nhiều người, có nghĩa tôi đang tạo ra nhiều kẻ thù hơn. Và đó chỉ là vấn đề thời gian, khi tôi phải đối mặt với những kẻ thù mạnh hơn mà tôi không thể đánh bại” – Câu nói của Người nhện báo trước cho sự xuất hiện của một loạt những kẻ thù nguy hiểm mà cậu sẽ phải đối đầu trong phần phim tiếp theo. Ngoài Electro (Jamie Foxx) đã xuất hiện trong đoạn teaser trước đây, người hùng giấu mặt Peter Parker sẽ phải chiến đấu chống lại Rhino (Paul Giamatti) và Green Goblin (Dane DeHaan).', 2014, '/dKOOKXgzCO7zh9meehGLxdWvpQY.jpg', 6.6, '2026-08-12 13:54:31'),
(53, 931285, 'Cuộc Chiến Sinh Tử II', 'tmdb-931285-cuc-chin-sinh-t-ii', 'Những chiến binh được yêu thích nhất — nay có thêm sự góp mặt của Johnny Cage — buộc phải đối đầu lẫn nhau trong trận chiến tối thượng đẫm máu và không khoan nhượng. Mục tiêu: đánh bại sự thống trị tàn bạo của Shao Kahn, kẻ đang đe dọa sự tồn vong của Địa Giới và tất cả những ai đứng lên bảo vệ nó.', 2026, '/f9tWGssOpViDbh6dV6gtLFiCc7i.jpg', 7.9, '2026-08-12 13:54:31'),
(54, 1668364, 'Deseo: Khao Khát', 'tmdb-1668364-deseo-khao-kh-at', 'Khi luật sư đã kết hôn nọ bắt đầu ngoại tình với huấn luyện viên bơi của con gái, mối tình nồng cháy dần biến thành một trò chơi rối ren mà rồi ai cũng mất kiểm soát.', 2026, '/5lJPvf7cJ2r2EiNrnvBVYpusKFM.jpg', 6.8, '2026-08-12 13:54:31'),
(55, 1228710, 'Star Wars: Mandalorian và Grogu', 'tmdb-1228710-star-wars-mandalorian-v-a-grogu', 'Đế Chế tàn bạo đã sụp đổ, nhưng những lãnh chúa chiến tranh của phe Đế Chế vẫn còn rải rác khắp thiên hà. Khi Nền Cộng hòa Mới nỗ lực bảo vệ những gì Quân Nổi Loạn đã chiến đấu để giành lấy, họ đã nhờ đến sự trợ giúp của thợ săn tiền thưởng Mandalorian - huyền thoại Din Djarin và cậu bé học việc Grogu.', 2026, '/554NefDjiPZ4ssHyWl3LiqlQZBT.jpg', 7.5, '2026-08-12 13:54:31'),
(56, 1525963, '채무자의 아내', 'tmdb-1525963-movie', '', 2024, '/ouXTrnJBimHIhWIUlHARDJH47no.jpg', 0.0, '2026-08-12 13:54:31'),
(57, 1084242, 'Phi Vụ Động Trời 2', 'tmdb-1084242-phi-v-dng-tri-2', 'Trong bộ phim \"Zootopia 2 - Phi Vụ Động Trời 2\" từ Walt Disney Animation Studios, hai thám tử Judy Hopps (lồng tiếng bởi Ginnifer Goodwin) và Nick Wilde (lồng tiếng bởi Jason Bateman) bước vào hành trình truy tìm một sinh vật bò sát bí ẩn vừa xuất hiện tại Zootopia và khiến cả vương quốc động vật bị đảo lộn. Để phá được vụ án, Judy và Nick buộc phải hoạt động bí mật tại những khu vực mới lạ của thành phố – nơi mối quan hệ đồng nghiệp của họ bị thử thách hơn bao giờ hết.', 2025, '/5wXpOF9WPUKliIzNBdAqwAStLHU.jpg', 7.7, '2026-08-12 13:54:31'),
(58, 1226863, 'Phim Super Mario Thiên Hà', 'tmdb-1226863-phim-super-mario-thi-en-h-a', 'Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là \"mẹ\" của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực siêu thực và hình ảnh rực rỡ.', 2026, '/h1FlxHYiVcZVkIE5XW599ZkV6Sr.jpg', 8.2, '2026-08-12 13:54:31'),
(59, 559, 'Người Nhện 3', 'tmdb-559-ngi-nhn-3', 'Spider Man 3 là phần tiếp theo của series phim Spider Man. Lần này, tưởng như Peter Parker đã tìm được bình yên trong cuộc sống bên cạnh người anh yêu. Nhưng cậu bạn cũ Harry Osborn khám phá ra bí mật về bộ giáp Green Goblin do người cha quá cố để lại.  Cũng đúng lúc này, bỗng có một thứ vật chất biến bộ đồ của Spider-Man thành màu đen và khiến tính khí của Peter Parker đột ngột thay đổi, trở nên cao ngạo hơn bao giờ hết. Rồi thứ vật chất đen bí ẩn kia còn biến Eddie Brock trở thành Venom (Người Nhện Đen) – có những khả năng y hệt như Spider Man. Giờ đây Spider Man phải tìm cách thoát khỏi thứ vật chất gớm ghiếc kia và chuẩn bị cho một cuộc chiến lớn với ba kẻ thù đầy nguy hiểm kia… Tình yêu, tình bạn và những giằng xé nội tâm sẽ giúp được gì khi Người Nhện không còn khoác trên mình bộ đồ màu đỏ quen thuộc?', 2007, '/qCxjZQHcfa6aaypmHrgIdbi85sW.jpg', 6.5, '2026-08-12 13:54:31'),
(60, 1439930, 'The Punisher: Phát Súng Cuối Cùng', 'tmdb-1439930-the-punisher-ph-at-s-ung-cui-c-ung', '', 2026, '/qQclTgLMDvGBuUBFGHRipxkEwWR.jpg', 8.3, '2026-08-12 13:54:31'),
(61, 83533, 'Avatar: Lửa và Tro Tàn', 'tmdb-83533-avatar-la-v-a-tro-t-an', 'Sau cuộc chiến tàn khốc với RDA và nỗi mất mát to lớn khi đứa con trai cả hy sinh, Jake Sully và Neytiri phải đối mặt với một mối đe dọa mới trên Pandora: tộc Tro Tàn — một nhóm Na\'vi hung bạo và khát khao quyền lực, do thủ lĩnh tàn nhẫn Varang dẫn dắt. Gia đình Jake buộc phải chiến đấu để sinh tồn và bảo vệ tương lai của Pandora, trong một cuộc xung đột đẩy họ đến giới hạn cuối cùng cả về thể xác lẫn tinh thần.', 2025, '/w6DBmG260sCHBQdGzkBIVn9gAQZ.jpg', 7.6, '2026-08-12 13:54:31'),
(62, 82023, 'Khách Sạn Đam Mê', 'tmdb-82023-kh-ach-sn-dam-m-e', 'Phim là câu chuyện về một cô hầu phòng sống ở Berlin, người phải chịu đựng những cơn trầm uất tình dục. Cuộc sống của cô thay đổi khi một lần vô tình, cô đi lạc vào phòng khách sạn nơi một họa sỹ mù đang ngụ lại.', 2011, '/myzQj8Rk178DrWsiZjVKjz7Kj9P.jpg', 6.2, '2026-08-12 13:54:31'),
(63, 98894, 'Jessica', 'tmdb-98894-jessica', '', 1962, '/emXHuiMFjPuYKBE9FeIkmQNNmy.jpg', 4.3, '2026-08-12 13:54:31'),
(64, 24428, 'Avengers 1:Biệt Đội Siêu Anh Hùng', 'tmdb-24428-avengers-1-bit-di-si-eu-anh-h-ung', 'The Avengers là bộ phim giả tưởng kể về một nhóm siêu anh hùng với những khả năng đặc biệt, họ bao gồm: Người Sắt, Thor, Đội trưởng Mỹ, và Người Khổng Lồ Xanh Hulk cùng tham gia với tổ chức bảo vệ thế giới SHIELD. Mục đích của SHIELD là nhằm bảo vệ Trái Đất khỏi âm mưu hủy hoại của những thế lực xấu từ ngoài địa cầu mà kẻ cầm đầu là Loki.', 2012, '/rX46P5ZwcHOvrkhtYDYhnNf46Bo.jpg', 8.1, '2026-08-12 13:54:31'),
(65, 1101383, 'Ngày Tàn Của Phố Oak', 'tmdb-1101383-ng-ay-t-an-ca-ph-oak', 'Sau khi một thảm họa thiên nhiên xé toạc Phố Oak khỏi khu ngoại ô và đưa con phố đến một nơi xa lạ, gia đình Platt nhanh chóng nhận ra rằng chỉ bằng cách luôn đứng bên nhau, họ mới có thể vượt qua vận mệnh nghiệt ngã này.', 2026, '/fprITg7E3v7Hj9wGKmCXCBVLSHq.jpg', 7.7, '2026-08-12 13:54:31'),
(66, 1419406, 'Bổ Phong Truy Ảnh', 'tmdb-1419406-b-phong-truy-nh', 'Wong Tak-Chung, một cựu chuyên gia giám sát được biết đến với khả năng phân tích dữ liệu và truy vết bậc thầy, bị cảnh sát Ma Cao mời trở lại hợp tác điều tra sau khi xuất hiện hàng loạt vụ cướp quy mô lớn do một tổ chức tội phạm công nghệ cao thực hiện.', 2025, '/5LGUvRBXoXHsMZsZrCGBOVmwOVd.jpg', 8.1, '2026-08-12 13:54:31'),
(67, 1656061, 'Immortal Combat', 'tmdb-1656061-immortal-combat', '', 2026, '/mhRAgvQ04DTE4zQN3OSyc9Lonj3.jpg', 4.7, '2026-08-12 13:54:31'),
(68, 1569947, 'The Priest: Thanksgiving Massacre', 'tmdb-1569947-the-priest-thanksgiving-massacre', '', 2025, '/AiRySv62247N91mfCCAryACGNuv.jpg', 3.5, '2026-08-12 13:54:31'),
(69, 1263532, 'Corrida dos Bichos', 'tmdb-1263532-corrida-dos-bichos', '', 2026, '/2bzIygGnua4tlLo7qTyMSUsME3d.jpg', 6.3, '2026-08-12 13:54:31'),
(70, 1280738, 'Cơn Thịnh Nộ', 'tmdb-1280738-cn-thnh-n', 'Cơn Thịnh Nộ', 2026, '/pomewNtFVHcox6UIOaNLQLHTaae.jpg', 7.4, '2026-08-12 13:54:31'),
(71, 822119, 'Captain America: Thế Giới Mới', 'tmdb-822119-captain-america-th-gii-mi', 'Sau khi gặp Tổng thống Hoa Kỳ mới đắc cử Thaddeus Ross, Sam Wilson thấy mình bị cuốn vào một sự cố . Anh phải khám phá lý do đằng sau một âm mưu cực kì xấu xa trước khi kẻ chủ mưu thật sự khiến cả thế giới phải hoảng sợ', 2025, '/fWTZk4Y7HTyTTGNJnXNaX3XTE0v.jpg', 6.0, '2026-08-12 13:54:32'),
(72, 950028, 'The Invite', 'tmdb-950028-the-invite', '', 2026, '/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 7.5, '2026-08-12 13:54:32'),
(73, 569094, 'Người Nhện: Du Hành Vũ Trụ Nhện', 'tmdb-569094-ngi-nhn-du-h-anh-v-u-tr-nhn', 'Miles Morales tái xuất trong phần tiếp theo của bom tấn hoạt hình từng đoạt giải Oscar - Spider-Man: Across the Spider-Verse. Sau khi gặp lại Gwen Stacy, chàng Spider-Man thân thiện đến từ Brooklyn phải du hành qua đa vũ trụ và gặp một nhóm Người Nhện chịu trách nhiệm bảo vệ các thế giới song song. Nhưng khi nhóm siêu anh hùng xung đột về cách xử lý một mối đe dọa mới, Miles buộc phải đọ sức với các Người Nhện khác và phải xác định lại ý nghĩa của việc trở thành một người hùng để có thể cứu những người cậu yêu thương nhất.', 2023, '/paM6UdMgXuXyAK0jhGfV07o3lRW.jpg', 8.3, '2026-08-12 13:54:32'),
(74, 47612, 'Au Bonheur des Dames', 'tmdb-47612-au-bonheur-des-dames', '', 1930, '/sVFvFFEMRJ1eUzD6nbYLSqwHi0d.jpg', 6.3, '2026-08-12 13:54:32'),
(75, 157336, 'Hố Đen Tử Thần', 'tmdb-157336-h-den-t-thn', 'Interstellar nói về chuyến hành trình đi tìm một hành tinh mới cho loài người trú ngụ khi mà Trái Đất dần dần không còn là nơi an toàn và sự sống thì đang chết dần với những dịch bệnh trên các loại cây lương thực, đe dọa đến sự tồn tại của loài người một cách mạnh mẽ. Chúng ta sẽ đi theo hành trình của phi hành đoàn gồm Copper, Amelia cùng các thành viên khác trong việc giải cứu các phi hành gia khác đã lên đường khám phá các hành tinh mới để tìm ra hành tinh mới cho loài người trú ngụ', 2014, '/if4TI9LbqNIrzkoOgWjX5PZYDYe.jpg', 8.5, '2026-08-12 13:54:32'),
(76, 1432631, 'இதயம் முரளி', 'tmdb-1432631-movie', '', 2026, '/8gfs5OsGINENFAl0h1XZPNup9lI.jpg', 7.6, '2026-08-12 13:54:32'),
(77, 299534, 'Avengers 4: Hồi Kết', 'tmdb-299534-avengers-4-hi-kt', 'Sau sự kiện hủy diệt tàn khốc, vũ trụ chìm trong cảnh hoang tàn. Với sự trợ giúp của những đồng minh còn sống sót, biệt đội siêu anh hùng Avengers tập hợp một lần nữa để đảo ngược hành động của Thanos và khôi phục lại trật tự của vũ trụ.', 2019, '/8go3YE9sBMQaCXEx23j6BAfeuxd.jpg', 8.2, '2026-08-12 13:54:32'),
(78, 324857, 'Người Nhện: Vũ Trụ Mới', 'tmdb-324857-ngi-nhn-v-u-tr-mi', 'Sau khi bị một con nhện nhiễm xạ cắn, Miles Morales, chàng thiếu niên từ Brooklyn đã nhận được một khóa học nhanh về cách giăng tơ từ những người ở chiều không gian khác.', 2018, '/kahw25SAqedXIruUGIuSUiq7t98.jpg', 8.4, '2026-08-12 13:54:32'),
(79, 1728704, 'Siping', 'tmdb-1728704-siping', '', 2026, '/wNzRyplxryB8s6jb8Be5dYAKZb5.jpg', 4.6, '2026-08-12 13:54:32'),
(80, 949838, '72 GIỜ', 'tmdb-949838-72-gi', 'Để cứu sự nghiệp, vị giám đốc quảng cáo 40 tuổi nọ tham gia cùng một nhóm người tuổi 20 trong bữa tiệc độc thân náo nhiệt tại Miami sau khi họ vô tình thêm nhầm anh vào nhóm chat.', 2026, '/9Bu1PW2R1XayqRqnl0aDOgMcrdS.jpg', 6.9, '2026-08-12 13:54:32'),
(81, 1327819, 'Hoppers: Cú Nhảy Kỳ Diệu', 'tmdb-1327819-hoppers-c-u-nhy-k-y-diu', 'Các nhà khoa học đã khám phá ra cách \"nhảy\" ý thức con người vào những con vật robot sống động như thật, cho phép con người giao tiếp với động vật dưới hình dạng động vật! Nhờ công nghệ mới này, Mabel sẽ khám phá những bí ẩn trong thế giới động vật vượt xa mọi điều cô từng tưởng tượng.', 2026, '/1A7WxXAYddDCrO9dTCEdSzQKU9d.jpg', 8.2, '2026-08-12 13:54:32'),
(82, 1290821, 'Kẻ Ẩn Dật', 'tmdb-1290821-k-n-dt', 'Michael Mason, một cựu sát thủ chính phủ đang sống ẩn dật trên một hòn đảo hẻo lánh tại Scotland, tình cờ cứu mạng một cô bé tên Jessie sau một cơn bão dữ dội. Hành động nghĩa hiệp này vô tình khiến tung tích của anh bị lộ, buộc Mason phải đối đầu với những bóng ma từ quá khứ và các đặc vụ MI6 đang truy đuổi gắt gao. Để bảo vệ đứa trẻ, anh phải từ bỏ cuộc sống yên bình, vận dụng mọi kỹ năng sinh tồn và chiến đấu để thoát khỏi vòng vây của những kẻ thù nguy hiểm.', 2026, '/mucESEbFFqk3ilVpNxEF53IHIVT.jpg', 7.8, '2026-08-12 13:54:32'),
(83, 755898, 'Cuộc Chiến Giữa Các Thế Giới', 'tmdb-755898-cuc-chin-gia-c-ac-th-gii', 'Will Radford — chuyên gia phân tích an ninh mạng hàng đầu của Bộ An ninh Nội địa — chuyên theo dõi các mối đe dọa đến an ninh quốc gia thông qua một chương trình giám sát diện rộng. Nhưng một cuộc tấn công bất ngờ từ một thực thể bí ẩn đã khiến anh bắt đầu nghi ngờ: phải chăng chính phủ đang che giấu điều gì đó… không chỉ với anh mà với toàn thế giới?', 2025, '/3e6GQvCA9hguxqfqA75BDvG7Vvp.jpg', 4.1, '2026-08-12 13:54:32'),
(84, 1285366, '愛のぬくもり', 'tmdb-1285366-movie', '', 2024, '/3r0O6BW9USoZ9mteCVyNKMQriRL.jpg', 6.2, '2026-08-12 13:54:32'),
(85, 278, 'Nhà Tù Shawshank', 'tmdb-278-nh-a-t-u-shawshank', 'Nhà tù Shawshank kể về Andrew, một nhân viên nhà băng, bị kết án chung thân sau khi giết vợ và nhân tình của cô. Anh một mực cho rằng mình bị oan. Andy bị đưa tới nhà tù Shawshank. Tại đây, thế giới ngầm của các phạm nhân, sự hà khắc của hệ thống quản giáo xung đột và giành nhau quyền thống trị. Chỉ có các phạm nhân trung lập là bị kẹt ở giữa và có thể bỏ mạng. Làm quen với tay ‘quản lý chợ đen’ Redding, Andy dần thích nghi với cuộc sống tại Shawshank. Song, kế hoạch lớn hơn việc tồn tại ở nhà tù này đang được anh suy tính. Qua con mắt và lời kể của Redding, cuộc vượt ngục vĩ đại này được kể tuần tự cùng một kết thúc bất ngờ', 1994, '/zLyG4nquaaZKCA3CJdQCEzTwN1R.jpg', 8.7, '2026-08-12 13:54:32'),
(86, 155, 'Kỵ Sĩ Bóng Đêm', 'tmdb-155-k-s-i-b-ong-d-em', 'Người Dơi bước vào giai đoạn cam go nhất trong cuộc chiến chống lại cái ác khi tên tội phạm bậc thầy The Joker xuất hiện. Các tay trùm thuê The Joker giết Người Dơi để trả thù cho chỗ tài sản phi pháp bị anh lật tẩy. Tiếp tay cho The Joker là toàn bộ tội phạm ở thành phố Gotham, những kẻ đang bị bộ ba Người Dơi - Trung úy Gordon - Luật sư Harvey Dent thu hẹp đất sống. Hàng loạt vụ tấn công xảy ra khiến Người Dơi lúng túng. Các quan chức bị sát hại, người dân không dám ra đường buổi tối vì sợ bị giết, mọi lối ra vào thành phố Gotham bị phong tỏa. Tất cả đều do một tay The Joker sắp đặt.', 2008, '/7EfSqviKvXwbiGhUjHyUBGVdoiW.jpg', 8.5, '2026-08-12 13:54:32'),
(87, 1304313, 'Một bộ phim của Lee Cronin: Xác ướp', 'tmdb-1304313-mt-b-phim-ca-lee-cronin-x-ac-p', 'Con gái nhỏ của một nhà báo biến mất không dấu vết giữa sa mạc. Tám năm sau, gia đình tan vỡ của họ bàng hoàng khi cô bé bất ngờ được đưa trở về — nhưng cuộc đoàn tụ tưởng chừng hạnh phúc nhanh chóng biến thành một cơn ác mộng sống.', 2026, '/fIbu9GsLv7j8uWA8OiAEtpNEDsZ.jpg', 7.9, '2026-08-12 13:54:32'),
(88, 1007757, 'Cuộc phiêu lưu biến hóa', 'tmdb-1007757-cuc-phi-eu-lu-bin-h-oa', 'Một sinh vật nhỏ bé trong rừng và một chú chim oai vệ bất ngờ hoán đổi thân xác, buộc chúng phải hợp sức để sống sót trong chuyến phiêu lưu náo loạn nhất đời mình.', 2026, '/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', 8.9, '2026-08-12 13:54:32'),
(89, 1003596, 'Avengers: Doomsday', 'tmdb-1003596-avengers-doomsday', 'Avengers: Doomsday theo chân những người hùng được yêu mến đến từ ba vũ trụ khác nhau, khi họ bị cuốn vào một hành trình va chạm sinh tử và phải đối mặt với một mối đe dọa mang tính sống còn chưa từng có trong lịch sử.', 2026, '/c5WRbkRthoNZ3lLhuQqKScmPyi4.jpg', 0.0, '2026-08-12 13:54:32'),
(90, 5721, 'Vixen!', 'tmdb-5721-vixen', '', 1968, '/9KMZWDA3xTrlgrScqdMisINQmsh.jpg', 5.5, '2026-08-12 13:54:32'),
(91, 27205, 'Kẻ Cắp Giấc Mơ', 'tmdb-27205-k-cp-gic-m', 'Cobb đánh cắp thông tin từ các mục tiêu của mình bằng cách đi vào giấc mơ của họ. Saito đề nghị xóa sạch tiền án của Cobb như một khoản thanh toán cho việc thực hiện hành vi đầu tiên đối với con trai của đối thủ cạnh tranh ốm yếu của mình.', 2010, '/eBtqGWtR5KUiNl6OXHLR3ri6nVm.jpg', 8.4, '2026-08-12 13:54:33'),
(92, 271110, 'Captain America: Nội Chiến Siêu Anh Hùng', 'tmdb-271110-captain-america-ni-chin-si-eu-anh-h-ung', 'Captain America: Civil War (Nội Chiến Siêu Anh Hùng) xoay quanh việc Steve Rogers (Captain America) dẫn đầu một nhóm siêu anh hùng với các thành viên của Avengers với mục tiêu tiếp tục nỗ lực để bảo vệ nhân loại. Nhưng sau nhiều vụ việc xảy ra do biệt đội Avengers làm thiệt hại tài sản, chính phủ đã thiết lập cơ quan quản lý và giám sát nhóm. Điều này gây ra sự chia rẽ trong nội bộ nhóm Avengers, tạo nên hai phe đối đầu nhau. Một bên được lãnh đạo bởi Steve Rogers (Captain America) với mong muốn duy trì nhóm để thực hiện mục tiêu bảo vệ nhân loại mà không có sự can thiệp của chính phủ. Phe còn lại là của Tony Stark (Iron Man) luôn hỗ trợ giám sát và có trách nhiệm giải trình mọi việc làm với chính phủ.', 2016, '/hDTVGIG8jsa1ZwO3wV0ccvDN4ZH.jpg', 7.5, '2026-08-12 13:54:33'),
(93, 1487861, 'Elize: Sombras de uma Mulher', 'tmdb-1487861-elize-sombras-de-uma-mulher', '', 2026, '/612ZyfilK8CVEEFphgPb3GOw0NF.jpg', 7.4, '2026-08-12 13:54:33'),
(94, 533535, 'Deadpool và Wolverine', 'tmdb-533535-deadpool-v-a-wolverine', 'Wade Wilson, chán nản, đang cố gắng sống cuộc đời bình thường sau những ngày làm lính đánh thuê không mấy lương thiện, Deadpool. Nhưng khi quê hương của anh đứng trước nguy cơ diệt vong, Wade buộc phải khoác lại bộ đồ một lần nữa, cùng với một Wolverine còn miễn cưỡng hơn.', 2024, '/lfY2CfmxyN9OvxmFuap6aejViJn.jpg', 7.6, '2026-08-12 13:54:33'),
(95, 1234821, 'Thế Giới Khủng Long: Tái Sinh', 'tmdb-1234821-th-gii-khng-long-t-ai-sinh', 'Thế Giới Khủng Long: Tái Sinh lấy bối cảnh 5 năm sau phần phim Thế Giới Khủng Long: Lãnh Địa, môi trường Trái đất đã chứng tỏ phần lớn là không phù hợp với khủng long. Nhiều loài thằn lằn tiền sử được tái sinh đã chết. Những con chưa chết đã rút lui đến một vùng nhiệt đới hẻo lánh gần phòng thí nghiệm. Địa điểm đó chính là nơi bộ ba Scarlett Johansson, Mahershala Ali và Jonathan Bailey dấn thân vào một nhiệm vụ cực kỳ hiểm nguy.', 2025, '/2IVVciw7dPhUlNmYIaz0s1d56SZ.jpg', 6.3, '2026-08-12 13:54:33'),
(96, 1497463, 'Todo lo que nunca fuimos', 'tmdb-1497463-todo-lo-que-nunca-fuimos', '', 2026, '/zqxIT48mWFsC4NSjGEHAcp1pjEo.jpg', 7.9, '2026-08-12 13:54:33'),
(97, 1368166, 'Cô Hầu Gái', 'tmdb-1368166-c-o-hu-g-ai', 'Từ đạo diễn Paul Feig, một thế giới hỗn loạn sẽ mở ra, nơi sự hoàn hảo chỉ là ảo giác và mọi thứ dường như đều đang che đậy một bí mật đằng sau. Để chạy trốn khỏi quá khứ, Millie (Sydney Sweeney) trở thành bảo mẫu cho gia đình Nina (Amanda Seyfried) và Andrew (Brandon Sklener), một cặp đôi giàu có. Nhưng ngay khi cô chuyển vào sống chung và bắt đầu công việc \"trong mơ\", sự thật dần được hé lộ - đằng sau vẻ ngoài xa hoa lộng lẫy là mối nguy lớn hơn bất cứ thứ gì Millie có thể tưởng tượng. Một trò chơi đầy cám dỗ của bí mật và quyền lực sắp bắt đầu.', 2025, '/vpHLCt2bwYmmkGH4soqJNIFLOUQ.jpg', 7.3, '2026-08-12 13:54:33'),
(98, 1430698, 'The Bay', 'tmdb-1430698-the-bay', '', 2026, '/8QQUI4J2zLv6f96TOjbz9dcg8bc.jpg', 6.0, '2026-08-12 13:54:33'),
(99, 652, 'Người Hùng Thành Troy', 'tmdb-652-ngi-h-ung-th-anh-troy', 'Trong suốt các thời đại, đàn ông đã gây chiến. Một số cho quyền lực, một số cho vinh quang hoặc danh dự, và một số cho tình yêu. Ở Hy Lạp cổ đại, niềm đam mê của hai người tình huyền thoại nhất trong lịch sử là Paris, Hoàng tử thành Troia (Orlando Bloom) và Helen (Diane Kruger), Nữ hoàng Sparta, đã mở ra một cuộc chiến tranh tàn phá nền văn minh. Vụ bắt cóc Helen bởi Paris, tách cô khỏi chồng mình, Vua Menelaus (Bren-dan Gleeson), là một sự xúc phạm mà Family Pride cho rằng đối mặt với Menelaus là một mối quan hệ với anh trai của cô là Agamemnon (Brian Cox), vị vua quyền lực của cô Mycenae, người sớm tái hợp tất cả các bộ lạc lớn của Hy Lạp để phục hồi Helen khỏi Trojans và bảo vệ danh dự của anh trai cô. Sự thật là cuộc chiến vì danh dự của Agamemnon bị hủy hoại bởi lòng tham không thể kiểm soát của anh ta khi anh ta cần phải chinh phục thành Troia để giành quyền kiểm soát Biển Aegean.', 2004, '/1kizpLuieVGFePU1qWL9bseIu4E.jpg', 7.2, '2026-08-12 13:54:33'),
(100, 122, 'Chúa Tể Của Những Chiếc Nhẫn: Sự Trở Lại Của Nhà Vua', 'tmdb-122-ch-ua-t-ca-nhng-chic-nhn-s-tr-li-ca-nh-a-vua', 'Sauron huy động toàn lực cho trận chiến khốc liệt cuối cùng, tấn công vào Gondor – vùng đất huyết mạch của loài người. Gondor dưới sự lãnh đạo của vị vua nhu nhược trở nên quá mong manh và nguy ngập. Đó chính là lúc những người anh hùng phát huy hết khả năng của mình. Cùng với sự hỗ trợ của các chiến binh Rohan, lực lượng những hồn ma bị nguyền rủa trong khe núi, Aragorn đã thống lĩnh những người Gondor chống lại Sauron, anh đã thực hiện sứ mệnh mà số phận giao phó cho mình, Aragorn sinh ra để trở thành Vua của Gondor, anh đã chứng minh điều đó. Cùng lúc đó, Frodo và Sam tiếp tục dấn sâu vào vùng đất ma quỷ đầy hiểm nguy để thực thi sứ mạng của mình, sứ mạng tiêu hủy Chiếc Nhẫn Quyền Lực. Có thể nói Sự Trở Lại Của Nhà Vua Phim là phần có nội dung hấp dẫn cùng những màn chiến đấu cực hay, cực kỳ hoành tráng.', 2003, '/3Y6eymGHCfQkDKU6rev2WiqXMci.jpg', 8.5, '2026-08-12 13:54:33'),
(101, 617126, 'Bộ Tứ Siêu Đẳng: Bước Đi Đầu Tiên', 'tmdb-617126-b-t-si-eu-dng-bc-di-du-ti-en', 'Sau một chuyến bay thám hiểm vũ trụ, bốn phi hành gia bất ngờ sở hữu năng lực siêu nhiên và trở thành gia đình siêu anh hùng đầu tiên của Marvel. The Fantastic Four: First Steps là bộ phim mở đầu Kỷ nguyên anh hùng thứ sáu (Phase Six), đặt nền móng cho siêu bom tấn Avengers: Doomsday trong năm sau.', 2025, '/n0bqzWiKGJsmnvOlkTiYykhhM4E.jpg', 6.9, '2026-08-12 13:54:33'),
(102, 599335, 'Ô Kê, Chị Đại', 'tmdb-599335-o-k-e-ch-di', 'Phim xoay quanh chuyến du lịch vô cùng “nhớ đời” của cặp vợ chồng Mi-Young (Uhm Jung-Hwa) và Seok-Hwan (Park Sung-Woong). Cả hai đều là điệp viên kỳ cựu nhưng đã giải nghệ để làm những người lao động bình dân - vợ mở một quầy bánh quẩy, chồng thì sửa máy tính dạo. Một ngày nọ, Seok-Hwan trúng giải là một chuyến đi chơi miễn phí đến Hawaii. Tuy nhiên, thật xui xẻo khi chuyến bay ra nước ngoài đầu tiên của hai vợ chồng đã bị khủng bố khống chế.\r Lúc bấy giờ, bản năng anh hùng của Mi-Young - Seok-Hwan bỗng trỗi dậy, họ bắt đầu tìm cách giải cứu các hành khách đang bị khủng bố bắt làm con tin. Tuy nhiên, trong sự hỗn loạn của trận không tặc, Mi-Young gặp lại Cheol-Seung (Lee Sang-Yoon) - một đồng nghiệp trong quá khứ, cũng là mối đe dọa lớn nhất về thân phận đặc biệt của cô. Lo sợ bóng ma của ngày cũ sẽ quay về gây ảnh hưởng đến gia đình nhỏ, một mặt Mi-Young phải giải cứu chuyến bay khỏi sự tấn công của bọn khủng bố, một mặt phải nghĩ cách giải quyết dứt điểm quá khứ của chính mình.', 2020, '/qrq98DRLyyrzRf4mkdwZ5CmOzeT.jpg', 7.1, '2026-08-12 13:54:33'),
(103, 1477712, 'Gã Bán Kem', 'tmdb-1477712-g-a-b-an-kem', 'Một thị trấn vào mùa hè yên bình đột nhiên trở nên hỗn loạn khi một ông bán kem phục vụ trẻ em những món ngọt nhưng lại đựng hậu quả kinh hoàng.', 2026, '/c987gxFjXqYOxZEZKcTkS1ONTWH.jpg', 5.2, '2026-08-12 13:54:33'),
(104, 238, 'Bố Già', 'tmdb-238-b-gi-a', 'Một câu chuyện kéo dài từ năm 1945 đến năm 1955, một biên niên sử về gia đình tội phạm Corleone người Mỹ gốc Ý. Khi tộc trưởng gia đình tội phạm có tổ chức, Vito Corleone bị ám sát bởi băng nhóm đối thủ, con trai út của ông, Michael đã phải nhúng tay vào tội ác và chống lại đối thủ với việc phát động một chiến dịch trả thù đẫm máu.', 1972, '/84MHN3JvOV4ORHgELrQM6SBlhdB.jpg', 8.7, '2026-08-12 13:54:33'),
(105, 441168, 'From Straight A\'s to XXX', 'tmdb-441168-from-straight-a-s-to-xxx', '', 2017, '/58BDtcDZG0ehZClEMwKampH4oX1.jpg', 5.9, '2026-08-12 13:54:33'),
(106, 872585, 'Oppenheimer', 'tmdb-872585-oppenheimer', 'Với nhân vật trung tâm là J. Robert Oppenheimer, nhà vật lý lý thuyết người đứng đầu phòng thí nghiệm Los Alamos, thời kỳ Thế chiến II. Ông đóng vai trò quan trọng trong Dự án Manhattan, tiên phong trong nhiệm vụ phát triển vũ khí hạt nhân, và được coi là một trong những “cha đẻ của bom nguyên tử”.', 2023, '/ixLH2iM9at8BbuLr5wQWnCfwhJO.jpg', 8.0, '2026-08-12 13:54:33'),
(107, 1382832, 'Cơn Đói Khát Tử Thần', 'tmdb-1382832-cn-d-oi-kh-at-t-thn', 'Một nhóm du khách lạc vào vùng đầm lầy Louisiana buộc phải chiến đấu để sinh tồn khi bị một con hà mã hung hãn đang sổng chuồng truy sát.', 2026, '/4uNhvGxBDiO0mU5UhxuXBsJwKF3.jpg', 7.2, '2026-08-12 13:54:33'),
(108, 986056, 'Thunderbolts*', 'tmdb-986056-thunderbolts', 'Sau khi thấy mình bị mắc kẹt trong một cái bẫy chết người, bảy người bị bỏ rơi vỡ mộng phải bắt tay vào một nhiệm vụ nguy hiểm sẽ buộc họ phải đối mặt với những góc đen tối nhất trong quá khứ của họ.', 2025, '/8SHwKExQ9dkR8xEmtT3y2vrHZEY.jpg', 7.3, '2026-08-12 13:54:33'),
(109, 1612018, 'Jackass: Chơi Lớn Lần Cuối', 'tmdb-1612018-jackass-chi-ln-ln-cui', '', 2026, '/tfgccePxnswMqhmtxafliLlcCVR.jpg', 7.5, '2026-08-12 13:54:33'),
(110, 99861, 'Avengers 2: Đế Chế Ultron', 'tmdb-99861-avengers-2-d-ch-ultron', 'Avengers: Age of Ultron tiếp nối các sự kiện xảy ra trong Captain America: The Winter Soldier ra mắt hè 2014. Kẻ thù của Biệt đội siêu anh hùng lần này là Ultron – một robot với trí tuệ nhân tạo, những năng lực siêu nhiên mạnh hơn bất kỳ ai trong The Avenger và có dã tâm chia rẽ nội bộ biệt đội nhằm thôn tính Trái Đất. Hắn được tạo ra từ phòng thí nghiệm của Tony Stark với mụ đích ban đầu là một hệ thống đặc biệt với mục đích gìn giữ hòa bình thế giới nhưng do Người Sắt sơ suất đã để mọi thứ vượt ra khỏi tầm kiểm soát, đẩy số phận của loài người lâm vào tình cảnh ngàn cân treo sợi tóc. Một lần nữa, những siêu anh hùng quả cảm - Iron Man, Captain America, Thor, The Incredible Hulk, Black Widow và Hawkeye - tiếp tục hợp tác để ngăn chặn kẻ thù. Trong hành trình bảo vệ hòa bình, nhóm kết nạp thêm hai thành viên: Wanda Maxioff và Pietro Maxioff – cặp song sinh bí hiểm và sở hữu một nguồn sức mạnh lớn lao, cũng như gặp lại một người bạn cũ trong hình dạng hoàn toàn mới có tên The Vision.', 2015, '/8j5ARDxYgeyuPjkwQIkcmMU8x7I.jpg', 7.3, '2026-08-12 13:54:33'),
(111, 233604, 'おんな地獄唄　尺八弁天', 'tmdb-233604-movie', '', 1970, '/uHSaaVUqvSJ6y81cP70LVbZfhlL.jpg', 4.9, '2026-08-12 13:54:35'),
(112, 671, 'Harry Potter và Hòn Đá Phù Thủy', 'tmdb-671-harry-potter-v-a-h-on-d-a-ph-u-thy', 'Harry Potter và Hòn Đá Phù Thủy là bộ phim đầu tiên trong series phim “Harry Potter” được xây dựng dựa trên tiểu thuyết của nhà văn J.K.Rowling. Nhân vật chính của phim, Harry Potter - một cậu bé 11 tuổi sau khi mồ côi cha mẹ đã bị gửi đến nhà dì dượng của mình, gia đình Dursley. Tuy nhiên, cậu bé bị ngược đãi và không hề biết về thân phận thực sự của mình.  Vào sinh nhật thứ 11 của Harry, một người lai khổng lồ là Rubeus Hagrid đã đến tìm cậu bé để đưa cậu về trường Pháp Thuật Hogwarts. Lúc này, Harry mới biết được mình là phù thủy và một phần câu chuyện về cha mẹ mình, những người đã bị Voldemort giết hại. Cùng với trí thông minh và lòng dũng cảm, cậu bé đã cùng những người bạn của mình khám phá những điều bí mật nguy hiểm về thế giới của phép thuật...', 2001, '/xDdgZkQ5Q3Jtnc2IhgAGQlPPCij.jpg', 7.9, '2026-08-12 13:54:35'),
(113, 391312, '喪服の女　崩れる', 'tmdb-391312-movie', '', 2001, '/4cfd33evWkw8TPq95WkHeU82m8O.jpg', 4.5, '2026-08-12 13:54:35'),
(114, 526024, 'Memorias de lo que no fue', 'tmdb-526024-memorias-de-lo-que-no-fue', '', 2017, '/bXZkCHFDq7HsaHili2hEn2POITw.jpg', 4.8, '2026-08-12 13:54:35'),
(115, 840464, 'Thảm Họa Thiên Thạch 2: Đại Di Cư', 'tmdb-840464-thm-ha-thi-en-thch-2-di-di-c', 'Sau ngày tận thế, gia đình Garrity rời boong-ke an toàn ở Greenland, mạo hiểm tất cả để bước vào một hành trình đầy hiểm nguy, băng qua vùng đất hoang tàn của châu Âu nhằm tìm kiếm một mái nhà mới.', 2026, '/o3mnfe0nJuD5oBBbGebN3xGYzaK.jpg', 6.4, '2026-08-12 13:54:35'),
(116, 1307247, '오케이 마담 2', 'tmdb-1307247-2', '', 2026, '/xDbrWXB9yb5aEdt4peVy8OWNP2Y.jpg', 0.0, '2026-08-12 13:54:35'),
(117, 1726, 'Người Sắt', 'tmdb-1726-ngi-st', 'Tony Stark vừa là chủ tập đoàn công nghệ, vừa là một tay chơi kỳ dị. Trong chuyến thị sát Afghanistan, ông bị nhóm khủng bố bắt cóc. Chúng đòi Tony chế tạo thứ vũ khí hủy diệt để tấn công nước Mỹ.  Nhận ra sự thật phũ phàng rằng, những vũ khí do mình chế tạo đang quay ngược lại tấn công chính mình, Tony bắt tay chế tạo bộ giáp công nghệ cao. Tẩu thoát khỏi nơi giam cầm, Tony trở thành đại diện công lý dưới biệt danh Người sắt. Trong khi đó, người đồng sự trong tập đoàn Stark âm mưu lật đổ Tony.  Bộ phim mở ra câu chuyện trong tương lai về nhóm siêu anh hùng Avenger khi tổ chức bí mật SHIELD bắt đầu lộ diện.', 2008, '/qwZiKSoWFevkPSjt21zi3Mgcity.jpg', 7.7, '2026-08-12 13:54:35'),
(118, 1413976, 'Công Dân Tự Xử', 'tmdb-1413976-c-ong-d-an-t-x', 'Sanders, một cựu quân nhân Mỹ và hiện là doanh nhân giàu có sinh sống tại châu Âu, dần mất niềm tin vào hệ thống pháp luật khi chứng kiến nhiều tội phạm nguy hiểm, kẻ hiếp dâm và quan chức tham nhũng liên tục thoát khỏi sự trừng phạt. Quyết định không tiếp tục đứng nhìn, anh che giấu thân phận và trở thành một \"công dân báo thù\", tự mình truy lùng và xử lý những kẻ mà pháp luật không thể hoặc không muốn trừng trị.', 2026, '/6LmJD3Wohe0g4U62wgi7RyJqfE4.jpg', 6.3, '2026-08-12 13:54:35'),
(119, 1325734, 'Cú Sốc', 'tmdb-1325734-c-u-sc', 'Một cặp đôi đang hạnh phúc chuẩn bị kết hôn bất ngờ bị thử thách khi một biến cố ngoài dự kiến khiến cả tuần lễ cưới của họ rơi vào hỗn loạn.', 2026, '/2r4p7IXUnbw8JkrsJK2vbhVIE2J.jpg', 6.9, '2026-08-12 13:54:35'),
(120, 1740877, 'Storm on Sesame Street', 'tmdb-1740877-storm-on-sesame-street', '', 2026, '/w4GrHRGgRQOYG95f2oVLYzGJ4Md.jpg', 7.0, '2026-08-12 13:54:35'),
(121, 1184918, 'Robot Hoang Dã', 'tmdb-1184918-robot-hoang-d-a', 'Sau một vụ đắm tàu, robot thông minh tên Roz bị mắc kẹt trên một hòn đảo hoang. Để sống sót trong môi trường khắc nghiệt, Roz gắn kết với các loài động vật trên đảo và chăm sóc một chú ngỗng con mồ côi.', 2024, '/fj1ywGV5k8D0qjXyVeEgNyksChq.jpg', 8.3, '2026-08-12 13:54:35'),
(122, 1469342, 'Địa Ngục Riêng Em', 'tmdb-1469342-da-ngc-ri-eng-em', 'Khi màn sương kỳ dị bao trùm lấy cả thành phố và giải phóng thứ thế lực chết chóc, một cô gái trẻ bất ổn lên đường tìm kiếm người cha mất tích. Trên hành trình ấy, số phận cô giao cắt với một lính Mỹ đang tuyệt vọng dấn thân vào cuộc truy tìm con gái mình - từ chính Địa ngục.', 2026, '/kiFacg75KVjy0AM3S4QmbPas8zL.jpg', 5.2, '2026-08-12 13:54:35'),
(123, 1318621, 'Descendants: Wicked Wonderland', 'tmdb-1318621-descendants-wicked-wonderland', '', 2026, '/xdhLAADGSse8KCrsDLBuM5b68Cg.jpg', 7.5, '2026-08-12 13:54:35'),
(124, 803796, 'Thợ săn quỷ Kpop', 'tmdb-803796-th-san-qu-kpop', 'Khi các siêu sao Kpop Rumi, Mira và Zoey không bận trình diễn tại các sân vận động cháy vé, họ sử dụng sức mạnh bí mật để bảo vệ người hâm mộ khỏi những mối đe dọa siêu nhiên.', 2025, '/y8OyohPhdTtusY0nXd2XdX4NN8W.jpg', 8.0, '2026-08-12 13:54:35'),
(125, 1122573, 'Trong Vùng Xám', 'tmdb-1122573-trong-v-ung-x-am', 'Khi một tên bạo chúa tàn nhẫn cướp đi khối tài sản trị giá 1 tỷ đô la, một đội đặc nhiệm tinh nhuệ hoạt động bí mật trong bóng tối toàn cầu được giao nhiệm vụ đoạt lại số tiền đó trong một phi vụ mà với bất kỳ ai khác cũng gần như là nhiệm vụ tự sát. Thành thạo thao túng quyền lực và tầm ảnh hưởng không kém gì sử dụng vũ khí tự động và thuốc nổ hạng nặng, họ bước vào một vụ cướp tưởng chừng bất khả thi rồi nhanh chóng bị cuốn vào một cuộc chiến toàn diện của chiến lược, lừa dối và sinh tồn.', 2026, '/fuC8BZLyE4L4JbEAMUCXZUBbi9W.jpg', 7.5, '2026-08-12 13:54:35');
INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `slug`, `description`, `release_year`, `poster_path`, `rating`, `created_at`) VALUES
(126, 120, 'Chúa Tể Của Những Chiếc Nhẫn: Hiệp Hội Nhẫn Thần', 'tmdb-120-ch-ua-t-ca-nhng-chic-nhn-hip-hi-nhn-thn', 'Chiếc nhẫn chúa mang sức mạnh bá chủ vô tình được số phận đưa vào tay chàng hobbit trẻ tuổi Frodo. Khi thày phù thủy Gandalf phát hiện ra chiếc nhẫn này đã từng thuộc về bạo chúa Sauron, Frodo phải nhận nhiệm vụ mang nhẫn tới khe núi Hủy diệt để tiêu hủy nó.  Không đơn độc trong hành trình gian khó, Frodo còn tiếp nhận những người đồng hành thuộc các tộc khác nhau: Legolas tộc Elf; Gimli tộc Dwarf; Aragon, Boromir và ba người bạn Hobbit trung thành...', 2001, '/wEELRpCiex6TkDkerrrU6Lp0A4s.jpg', 8.4, '2026-08-12 13:54:35'),
(127, 550, 'Sàn Đấu Sinh Tử', 'tmdb-550-s-an-du-sinh-t', 'Cuộc gặp gỡ định mệnh của một nhân viên giám định bảo hiểm và một gã lông bông bán xà phòng trên chuyến bay đã mở ra một cuộc phiêu lưu kỳ lạ. Với các \"câu lạc bộ chiến đấu\" ngầm hình thành ở mọi thị trấn, cuốn theo nhiều diễn biến phức tạp và một cái kết đầy kịch tính.', 1999, '/wBxkCbNI8eDRRfUEl8w0G2rfLyu.jpg', 8.4, '2026-08-12 13:54:35'),
(128, 1318447, 'Săn Mạng', 'tmdb-1318447-san-mng', 'Đang đau buồn, người phụ nữ nọ thử thách giới hạn trong chuyến phiêu lưu đơn độc giữa vùng hoang dã Úc, nhưng lại bị cuốn vào trò chơi méo mó của một kẻ sát nhân coi cô là con mồi.', 2026, '/jMSlZZScFPA6YqatxzrixoMlTDk.jpg', 6.9, '2026-08-12 13:54:35'),
(129, 693134, 'Hành Tinh Cát: Phần Hai', 'tmdb-693134-h-anh-tinh-c-at-phn-hai', 'Hãy theo chân hành trình của Paul Atreides khi anh ấy cùng với Chani và những người Fremen trên con đường trả thù những kẻ đã âm mưu phá hủy gia đình của anh. Đối diện với sự lựa chọn giữa tình yêu của đời mình và số phận của vũ trụ rộng lớn, Paul phải cố ngăn chặn một tương lai kinh khủng chỉ có anh mới nhìn thấy được.', 2024, '/8QdnKQyZDlN6rBSrfU1V5PctfUu.jpg', 8.1, '2026-08-12 13:54:35'),
(130, 1516698, 'The Last Sunrise', 'tmdb-1516698-the-last-sunrise', '', 2026, '/pego3yEZ5SuGvRjESKAguL4Wu7M.jpg', 0.0, '2026-08-12 13:54:35'),
(131, 453395, 'Phù Thủy Tối Thượng: Đa Vũ Trụ Hỗn Loạn', 'tmdb-453395-ph-u-thy-ti-thng-da-v-u-tr-hn-lon', 'Sự kiện xảy sau phần phim Người Nhện: Không còn nhà (2021) và mùa đầu tiên của Loki (2021), Bác sĩ Stephen Strange đã sử dụng một phét thuật bị cấm và mở ra cánh cổng dẫn tới đa vũ trụ, vô tình dẫn đưa một biến thể hắc ám của Stephen Strange khác đến vũ trụ mình - mối đe dọa lớn mà Dr. Strange có thể phải đối đầu hoặc hợp sức chống lại một cái ác khác, đồng hành cùng Strange còn có Wong và Wanda Maximoff cùng với nhân vật mới American Chavez.', 2022, '/ovMxUPSSuvBD7GcgdQxzbJfsR8q.jpg', 7.2, '2026-08-12 13:54:36'),
(132, 361743, 'Phi Công Siêu Đẳng: Maverick', 'tmdb-361743-phi-c-ong-si-eu-dng-maverick', 'Sau hơn 30 năm phụng sự với tư cách phi công hàng đầu của hải quân, Pete “Maverick” Mitchell giờ đang làm việc mình yêu thích: bứt phá giới hạn trong vai trò một phi công thử nghiệm dũng cảm. Tuy nhiên, Maverick phải đối đầu với bóng ma quá khứ khi anh trở lại TOPGUN để đào tạo một nhóm học viên ưu tú và đối mặt với Trung úy Bradshaw, con trai của phi công yểm trợ cũ \"Goose\". Sự cạnh tranh gay gắt bùng nổ khi các phi công chuẩn bị cho một nhiệm vụ chuyên biệt đòi hỏi sự hy sinh tột bậc từ những người được chọn bay.', 2022, '/yuY9mNG8EgYBwDZKH4RFJHRoAUp.jpg', 8.2, '2026-08-12 13:54:36'),
(133, 1061474, 'Superman', 'tmdb-1061474-superman', 'Superman cố gắng can thiệp vào một cuộc khủng hoảng toàn cầu do Lex Luthor gây ra, nhưng lại bị công chúng hiểu lầm. Mọi chuyện trở nên nghiêm trọng hơn khi Luthor tạo ra một bản sao đen tối của Superman – Ultraman. Với sự giúp đỡ của Lois Lane và chú chó siêu năng lực Krypto, Superman phải đối mặt với chính bản ngã của mình để giành lại niềm tin từ nhân loại.', 2025, '/f4hJ5yVSiOSnW9S6vtoGlNYvW5J.jpg', 7.3, '2026-08-12 13:54:36'),
(134, 1301421, 'Đội Thám Tử Cừu: Án Mạng Lúc Nửa Đêm', 'tmdb-1301421-di-th-am-t-cu-an-mng-l-uc-na-d-em', 'Trong bộ phim trinh thám hài hước, độc đáo này, George (Hugh Jackman) là một người chăn cừu, mỗi tối đều đọc tiểu thuyết trinh thám cho đàn cừu yêu quý nghe, nghĩ rằng chúng không thể hiểu được. Nhưng khi George bất ngờ qua đời trong một sự cố bí ẩn trên trang trại, đàn cừu quyết định tự mình trở thành thám tử. Lần theo manh mối và điều tra các nghi phạm là con người, chúng chứng minh rằng ngay cả cừu cũng có thể phá án xuất sắc.', 2026, '/fEpV3vWBQ1eZefIIcwaiTduXEEP.jpg', 7.9, '2026-08-12 13:54:36'),
(135, 952079, '초대받은 배달부 2', 'tmdb-952079-2', '', 2022, '/41Q9zWeeZXJguvrSmZGDgci1cbB.jpg', 7.0, '2026-08-12 13:54:36'),
(136, 414906, 'Người Dơi: Vạch Trần Sự Thật', 'tmdb-414906-ngi-di-vch-trn-s-tht', 'Tay giết người hàng loạt – The Ridder (Paul Dano) sẽ là kẻ thù nguy hiểm hàng đầu của Batman ở phần phim sắp tới. Tên xấu xa này bị cảnh sát James Gordon và đồng đội bắt giữ đã lâu. Thế nhưng, hóa ra việc nhốt gã sau song sắt chỉ khiến The Ridder phiền phức hơn với Đấng. Penguin (Colin Farrell) thể hiện là kẻ thủ ác thích trực tiếp tạo ra hỗn loạn, muốn đối đầu Batman hơn là chỉ đạo gián tiếp theo cách The Ridder thực hiện.', 2022, '/nMp4tu8XuVG3CSWdXTFiHLdngnc.jpg', 7.7, '2026-08-12 13:54:36'),
(137, 1479832, 'டிசி', 'tmdb-1479832-movie', '', 2026, '/cm1uBPBUDfSIZXhWxsp1zzlKnf.jpg', 8.5, '2026-08-12 13:54:36'),
(138, 672, 'Harry Potter và Căn Phòng Bí Mật', 'tmdb-672-harry-potter-v-a-can-ph-ong-b-i-mt', 'Harry trở lại năm thứ hai tại Hogwarts, nhưng phát hiện ra rằng những điều tồi tệ đang xảy ra bởi vì một trang web có tên là Phòng chứa bí mật đã được người thừa kế của Slytherin mở ra và sẽ khiến những đứa trẻ của Muggles, những kẻ không trong sạch, xuất hiện một cách bí ẩn bởi một con vật quái dị.', 2002, '/yujrz8XVQ0z5kcSwuYInE71xVsZ.jpg', 7.7, '2026-08-12 13:54:36'),
(139, 1297842, 'Tuyển Thủ Dê: \"Mùi\" Vị Chiến Thắng', 'tmdb-1297842-tuyn-th-d-e-m-ui-v-chin-thng', 'Will là một chú dê nhỏ với những ước mơ lớn, người có được cơ hội duy nhất trong đời để gia nhập các vận động viên chuyên nghiệp và thi đấu môn rugebol — một môn thể thao cường độ cao, pha trộn và đối kháng toàn diện, nơi các loài động vật nhanh nhất và hung dữ nhất thế giới thống trị. Những đồng đội mới của Will không mấy hào hứng khi có một chú dê nhỏ trong đội hình, nhưng Will quyết tâm tạo nên một cuộc cách mạng cho môn thể thao này và chứng minh một lần và mãi mãi rằng: “Nhỏ bé cũng biết chơi!”', 2026, '/wZRJ3Q2XRJHov1SS80sTXbfjkz9.jpg', 8.1, '2026-08-12 13:54:36'),
(140, 987573, 'ビリーバーズ', 'tmdb-987573-movie', '', 2022, '/o6gF3tCiMwGKM5M9DvgH8sEPXFu.jpg', 5.6, '2026-08-12 13:54:36'),
(141, 603, 'Ma Trận', 'tmdb-603-ma-trn', 'The Matrix (MaTrận) là bộ phim khoa học giả tưởng về tương lai. Trong tương lai đó, Thomas, biệt danh Neo, là một hacker luôn có cảm giác khác thường về thế giới thực. Cho tới khi người đàn ông tự xưng là Morpheus tìm đến anh. Người đàn ông này nói cho anh biết, thế giới mà mọi người coi là thực chỉ là một chương trình giả lập để máy móc cai trị con người. Chỉ có một người có thể phá được Ma trận. Những người thật sống sót còn lại cuối cùng và những nhân viên Ma trận đều cùng đi tìm người đó. Và người đó chính là anh – Neo…', 1999, '/fE7S6EwaBgRQeqKoDVFoImMmAF4.jpg', 8.3, '2026-08-12 13:54:36'),
(142, 687259, '镜花风月三之螺女挑情', 'tmdb-687259-movie', '', 1982, '/m4ALMhsuqOOUkkABvgQWfrgoL8y.jpg', 6.2, '2026-08-12 13:54:36'),
(143, 1050390, '監禁逃亡　美しき獲物たち', 'tmdb-1050390-movie', '', 1993, '/cHlmO3svm2WKwIOHU1Mq9gCMj8n.jpg', 7.0, '2026-08-12 13:54:36'),
(144, 976912, 'Graphic Desires', 'tmdb-976912-graphic-desires', '', 2023, '/3BjLdTWRiHc1ISIZMFvToOmghOM.jpg', 7.0, '2026-08-12 13:54:36'),
(145, 19995, 'Avatar', 'tmdb-19995-avatar', 'Avatar là câu chuyện về người anh hùng “bất đắc dĩ” Jake Sully – một cựu sĩ quan thủy quân lục chiến bị liệt nửa thân. Người anh em sinh đôi của anh được chọn để tham gia vào chương trình cấy gien với người ngoài hành tinh Na’vi nhằm tạo ra một giống loài mới có thể hít thở không khí tại hành tinh Pandora. Giống người mới này được gọi là Avatar. Sau khi anh của Jake bị giết, Jake được chọn để thay thế anh mình và đã trở thành một Avatar, Jake có nhiệm vụ đi tìm hiểu và nghiên cứu hành tinh Pandora. Những thông tin mà anh thu thập được rất có giá trị cho chiến dịch xâm chiếm hành tinh xanh thứ hai này của loài người.', 2009, '/bxp5IUY05jLGeZ5bW85W2NF6Rgi.jpg', 7.6, '2026-08-12 13:54:36'),
(146, 680, 'Chuyện Tào Lao', 'tmdb-680-chuyn-t-ao-lao', 'Những câu chuyện tưởng chừng tầm phào về 2 gã găng tơ trên đường thực hiện mệnh lệnh của ông chủ với 1 võ sĩ quyền anh giết chết người phải chạy trốn có vẻ không liên quan nhưng khi ghép lại người xem sẽ có 1 bức tranh tổng thể, đặc trưng cho phong cách của đạo diễn Quentin Tarantino: đậm chất bạo lực, máu me.', 1994, '/ihynkOAH6FLNgG1kqM5ep9GSHZS.jpg', 8.5, '2026-08-12 13:54:36'),
(147, 1265609, 'Cỗ máy chiến tranh', 'tmdb-1265609-c-m-ay-chin-tranh', 'Trong nhiệm vụ cuối cùng của khóa huấn luyện Biệt kích Lục quân, một kỹ sư chiến đấu phải dẫn dắt đơn vị chống lại một cỗ máy giết người khổng lồ đến từ thế giới khác.', 2026, '/n1IwU8lLbvPZXqjfO7PYKzsmNXe.jpg', 7.4, '2026-08-12 13:54:36'),
(148, 1242898, 'Quái Thú Vô Hình: Vùng Đất Chết Chóc', 'tmdb-1242898-qu-ai-th-u-v-o-h-inh-v-ung-dt-cht-ch-oc', 'Trong tương lai, tại một hành tinh hẻo lánh, một Predator non nớt - kẻ bị chính tộc của mình ruồng bỏ - tìm thấy một đồng minh không ngờ tới là Thia và bắt đầu hành trình sinh tử nhằm truy tìm kẻ thù tối thượng. Bộ phim do Dan Trachtenberg - đạo diễn của Prey chỉ đạo và nằm trong chuỗi thương hiệu Quái Thú Vô Hình Predator.', 2025, '/6aPy2tMgQLVz2IcifrL1Z2Q9u1t.jpg', 7.8, '2026-08-12 13:54:36'),
(149, 1010581, 'Tội Lỗi', 'tmdb-1010581-ti-li', 'Cô nàng Noah buộc phải bỏ lại thị trấn, bạn trai và bạn bè thân để chuyển đến dinh thự của người cha dượng giàu có. Ở đó, cô gặp người anh kế mới Nick và tính cách của họ xung đột ngay từ đầu. Tuy nhiên, sự hấp dẫn của họ đối với nhau dần dần biến thành một mối tình bị cấm đoán!', 2023, '/3Kjcu12lIy0dCQA1756e9zG2slc.jpg', 7.7, '2026-08-12 13:54:36'),
(150, 121, 'Chúa Tể Của Những Chiếc Nhẫn: Hai Tòa Tháp', 'tmdb-121-ch-ua-t-ca-nhng-chic-nhn-hai-t-oa-th-ap', 'Cuộc hành trình đi hủy diệt chiếc nhẫn tiếp tục với bao nguy hiểm chờ đợi Frodo ở phía trước. Lần này, anh và Sam có một bạn đồng hành mới là Gollum. Trong khi đó, Gandalf may mắn thoát chết, hơn nữa sức mạnh của ông còn vượt xa hơn rất nhiều. Ông cùng Aragon, Legolas và Gimli cùng những thần rừng tìm cách phá hủy âm mưu của Saruman. Tiếp nối thành công của phần 1 The Lord Of The Ring 2 kế thừa và đan xen giữa hai hệ thống nhân vật cũ và mới làm cho nội dung phim càng thêm lôi cuốn người xem. The Lord Of The Ring 2 cũng mang về 2 Giải Oscar cho hạng mục âm thanh và kĩ xảo.', 2002, '/jmwZrMZE6bEuG6JWeu8Udb8B69d.jpg', 8.4, '2026-08-12 13:54:36'),
(151, 1233413, 'Tội Đồ', 'tmdb-1233413-ti-d', 'Cố gắng bỏ lại cuộc sống đầy rắc rối của mình, hai anh em sinh đôi trở về quê hương để bắt đầu lại, chỉ để phát hiện ra rằng một cái ác thậm chí còn lớn hơn đang chờ đợi để chào đón họ trở lại.', 2025, '/aXFWi3ir9vHqAz0m3XIuD92vPsQ.jpg', 7.5, '2026-08-12 13:54:38'),
(152, 1308767, 'Young Washington', 'tmdb-1308767-young-washington', '', 2026, '/6CdoTKnRQHJkjRGxTefFGkPQplB.jpg', 7.9, '2026-08-12 13:54:38'),
(153, 862, 'Câu Chuyện Đồ Chơi', 'tmdb-862-c-au-chuyn-d-chi', 'Thế giới đồ chơi của cậu bé Andy bị xáo trộn khi có sự xuất hiện của cảnh sát vũ trụ Buzz Lightyear. Cảm thấy mình bị “thất sủng”, anh chàng cao bồi gỗ Woody xô xát với Buzz và cả hai bị rơi vào một cuộc phiêu lưu đầy mạo hiểm. Câu chuyện nói về thế giới đồ chơi của cậu bé...', 1995, '/2k5424igOcC1rjJoME8WNREEOgy.jpg', 8.0, '2026-08-12 13:54:38'),
(154, 597, 'Titanic', 'tmdb-597-titanic', 'Rose DeWitt Bukater, 101 tuổi, hồi nhớ về khoảng thời gian của bà trên tàu Titanic vào 84 năm trước . Khi bà còn là một cô gái trẻ lên tàu Titanic cùng mẹ và chồng sắp cưới. Định mệnh cho cô gặp Jack Dawson, một chàng họa sĩ trẻ tài năng. Rose kể toàn bộ câu chuyện của họ trên chuyến hành trình định mệnh đầu tiên và cuối cùng  của Titanic vào ngày 15 tháng 4 năm 1912.', 1997, '/yC2waNaokYeCRHSsYMB8DJK7rGS.jpg', 7.9, '2026-08-12 13:54:38'),
(155, 98, 'Võ Sĩ Giác Đấu', 'tmdb-98-v-o-s-i-gi-ac-du', 'Hoàng đế Marcus quyết định chọn vị tướng tin cẩn là Maximus làm người kế vị ngai vàng. Ðiều đó làm Commodus, con trai Marcus, nổi giận. Hắn đã giết cha để chiếm ngôi rồi hãm hại gia đình Maximus. Bản thân Maximus bị trở thành nô lệ, phải tham gia vào các cuộc thi giác đấu... Cuối cùng Maximus cũng về đến Rome và trả thù cho gia đình... Cuộc đời Maximus thay đổi từ ấy, từ một vị tướng oai dũng trở thành một kẻ nô lệ phải trải qua bao thử thách...', 2000, '/usBP3JEXW7iyDfpSfgYFCncg1NA.jpg', 8.2, '2026-08-12 13:54:38'),
(156, 1241982, 'Hành Trình Của Moana 2', 'tmdb-1241982-h-anh-tr-inh-ca-moana-2', '“Hành Trình của Moana 2” là màn tái hợp của Moana và Maui sau 3 năm, trở lại trong chuyến phiêu lưu cùng với những thành viên mới. Theo tiếng gọi của tổ tiên, Moana sẽ tham gia cuộc hành trình đến những vùng biển xa xôi của Châu Đại Dương và sẽ đi tới vùng biển nguy hiểm, đã mất tích từ lâu. Cùng chờ đón cuộc phiêu lưu của Moana đầy chông gai sắp tới nhé.', 2024, '/g8ikn2lfi4R04U7BtXvHmYvnUTV.jpg', 7.0, '2026-08-12 13:54:38'),
(157, 933260, 'Thần Dược', 'tmdb-933260-thn-dc', 'Một minh tinh hết thời quyết định sử dụng một liều thuốc mua từ chợ đen: Thứ thần dược sao chép tế bào của cô để tạo ra một phiên bản trẻ hơn, và hoàn hảo hơn của chính cô.', 2024, '/5C3J6QvtKi5qkexWuGkcMtEoUsg.jpg', 7.1, '2026-08-12 13:54:38'),
(158, 1679730, 'Nữ hiệp ruy băng', 'tmdb-1679730-n-hi-ep-ruy-bang', 'Khi quái vật Nergal tàn phá vương quốc của mình, Công chúa Sapphire thức tỉnh thành Nữ hiệp ruy băng và chiến đấu để bảo vệ quê hương mới khỏi số phận đen tối tương tự.', 2026, '/79APJkTug1OzTrTtTmSmy2TgSuU.jpg', 7.1, '2026-08-12 13:54:38'),
(159, 673, 'Harry Potter và Tù Nhân Azkaban', 'tmdb-673-harry-potter-v-a-t-u-nh-an-azkaban', 'Harry đang mong chờ đến cuối mùa hè để bắt đầu một khóa học mới tại Hogwarts, và rời khỏi ngôi nhà của người dì và người chú đáng khinh của mình, Dursley, càng sớm càng tốt. Điều Harry không biết là anh sẽ phải rời khỏi Privet Drive sớm và bất ngờ sau khi biến dì Marge của mình thành một quả bóng bay khổng lồ. Một chiếc xe buýt đêm, và tất nhiên là mê hoặc, sẽ đưa anh ta đến quán rượu Leaky Cauldron, nơi không ai khác ngoài Cornelius Fudge, Bộ trưởng Bộ Pháp thuật, đang chờ anh ta.', 2004, '/vUwrS4EeRbhs183aK3MCGUhjIOX.jpg', 8.0, '2026-08-12 13:54:38'),
(160, 1380291, 'Siêu Điệp Viên Jack Ryan: Bóng Ma Chiến Tranh', 'tmdb-1380291-si-eu-dip-vi-en-jack-ryan-b-ong-ma-chin-tranh', 'Khi một nhiệm vụ bí mật quốc tế làm sáng tỏ một âm mưu chết người, Ryan buộc phải quay trở lại thế giới gián điệp để đối đầu với một đơn vị hoạt động đen tối lừa đảo.', 2026, '/b5wOQyhRvOGS61x5heXCllbNh78.jpg', 7.0, '2026-08-12 13:54:38'),
(161, 438631, 'Hành Tinh Cát', 'tmdb-438631-h-anh-tinh-c-at', 'Là chuyến hành trình sử thi đầy cảm xúc của Paul Atreides – một chàng thanh niên trẻ tài ba xuất chúng được sinh ra với một sứ mệnh vĩ đại vượt ngoài tầm hiểu biết của chính bản thân anh. Paul đã phải du hành tới hành tinh nguy hiểm nhất trong Vũ trụ để đảm bảo được tương lai cho gia đình cũng như những người dân của anh ấy. Khi các thế lực tàn độc bắt đầu lao vào cuộc xung đột nhằm tranh giành độc quyền nguồn tài nguyên có giá trị nhất hành tinh – thứ nhiên liệu quý giá có khả năng kích hoạt những tiềm năng lớn nhất của nhân loại – chỉ những người chiến thắng được nỗi sợ hãi của mình mới có thể sống sót.', 2021, '/kZpP3t5wxOlHscZiDP3LuhuvkiI.jpg', 7.8, '2026-08-12 13:54:38'),
(162, 558, 'Người Nhện 2', 'tmdb-558-ngi-nhn-2', 'Đã hai năm kể từ khi Peter Parker im lặng rời bỏ Mary Jane Watson, tình yêu vĩ đại của anh và quyết định tiếp tục đảm nhận trách nhiệm của mình với tư cách là Người Nhện. Peter phải đối mặt với những thử thách mới khi anh chiến đấu với món quà và lời nguyền về sức mạnh của mình bằng cách cân bằng hai danh tính: Người nhện siêu anh hùng khó nắm bắt và sinh viên đại học. Mối quan hệ với những người mà anh ấy trân trọng nhất hiện đang có nguy cơ bị phơi bày với sự xuất hiện của một nhân vật phản diện nhiều xúc tu mạnh mẽ Octopus, \"Doc Ock. Sức hấp dẫn của cô đối với MJ ngày càng lớn khi cô chiến đấu với sự thôi thúc từ bỏ cuộc sống bí mật của mình và tuyên bố tình yêu của mình. Trong khi đó, MJ đã tiếp tục cuộc sống của mình. Cuộc sống của cô Mối quan hệ của Peter với người bạn thân nhất Harry Osborn đã bị phá vỡ bởi mối thù truyền kiếp của Harry chống lại Người Nhện, người mà anh ta chịu trách nhiệm cho cái chết của cha mình.', 2004, '/1ICx62fI9FtAgjG2x5zprn4qcdY.jpg', 7.3, '2026-08-12 13:54:38'),
(163, 1272837, '28 Năm Sau: Ngôi Đền Tử Thần', 'tmdb-1272837-28-nam-sau-ng-oi-dn-t-thn', 'Mở rộng thế giới do Danny Boyle và Alex Garland xây dựng trong loại phim 28 Năm Sau nhưng đồng thời đảo ngược hoàn toàn mọi trật tự vốn có trong thế giới ấy. Nia DaCosta đảm nhận vai trò đạo diễn bộ phim 28 Năm Sau: Thánh Địa Xương. Tiếp nối câu chuyện, bác sĩ Kelson (Ralph Fiennes) bất ngờ rơi vào một mối quan hệ mới đầy bất ngờ, có khả năng làm thay đổi cả thế giới mà ta từng biết. Trong khi đó, cuộc chạm trán của Spike (Alfie Williams) với Jimmy Crystal (Jack O\'Connell) lại biến thành một cơn ác mộng không lối thoát của cậu bé. Trong thế giới của Thánh Địa Xương, những kẻ bị nhiễm bệnh không còn là mối đe dọa sinh tồn lớn nhất mà chính sự vô nhân tính của những kẻ sống sót mới là thứ quái lạ và đáng sợ hơn.', 2026, '/dGTV0DVizaRh5fAsrtB95FnGSlf.jpg', 7.1, '2026-08-12 13:54:38'),
(164, 10138, 'Người Sắt 2', 'tmdb-10138-ngi-st-2', 'Tony Stark tự hé lộ thân phận Người sắt của mình cho công chúng và chìm trong hào quang danh vọng. Một kẻ lạ mặt xuất hiện tấn công anh trên đường đua Monte Carlo. Tony bị hiện tượng nhiễm trùng máu đe dọa mạng sống, còn tên sát thủ kia bắt tay với đối thủ của tập đoàn Stark hòng thôn tính Tony.  Phần 2 của Người sắt là lần đầu tiên trợ thủ Warmachine xuất hiện. Phim cũng tiết lộ những bí mật về cha của Tony, Howard Stark, trước khi dẫn dắt câu chuyện sang nhân vật Captain America, đồng đội tương lai của Người sắt tại tổ chức SHIELD.', 2010, '/q9L8fMYW4dBQOdDAfbbxte7gciJ.jpg', 6.9, '2026-08-12 13:54:38'),
(165, 8587, 'Vua Sư Tử', 'tmdb-8587-vua-s-t', 'Lấy bối cảnh là khu vực rừng hoang Phi Châu, bộ phim đã xây dựng nên cả một xã hội có tổ chức của thế giới loài vật. Trong xã hội ấy cũng có những mâu thuẫn, cũng có tranh chấp và có cả tình yêu như thế giới loài người. Nhân vật chính của Vua sư tử là chú sư tử con Simba, con trai của Mufasa vị vua đang thống trị thế giới hoang dã ở đây. Cuộc sống hạnh phúc yêu đời bên cạnh cha mẹ và cô bạn Nala của cậu sớm chấm dứt khi người chú ruột Scar có âm mưu cướp ngai vàng của cha cậu....', 1994, '/AsGpIREstvwExc3UqczmIPP4pay.jpg', 8.3, '2026-08-12 13:54:38'),
(166, 911430, 'Phim Điện Ảnh F1®', 'tmdb-911430-phim-din-nh-f1-r', 'Phim kể về Sonny Hayes (do Brad Pitt thủ vai), một cựu tay đua F1 lão làng, người đã rời xa đường đua sau một tai nạn kinh hoàng. Anh được thuyết phục quay trở lại thế giới tốc độ để cố vấn cho một tay đua trẻ tuổi, đầy triển vọng nhưng cũng rất liều lĩnh. Cùng nhau, họ phải đối mặt với những thách thức khốc liệt của giải đấu F1, cạnh tranh với những tay đua hàng đầu thế giới và khám phá lại niềm đam mê, đồng thời tìm cách vượt qua những giới hạn của bản thân. Phim hứa hẹn sẽ mang đến những cảnh quay chân thực và những pha đua xe mãn nhãn, được quay ngay trên các đường đua F1 thật sự.', 2025, '/14qIfiKSoN9AYvpT9pSU5rieSE7.jpg', 7.8, '2026-08-12 13:54:38'),
(167, 447365, 'Vệ Binh Dải Ngân Hà 3', 'tmdb-447365-v-binh-di-ng-an-h-a-3', 'Cho dù vũ trụ này có bao la đến đâu, các Vệ Binh của chúng ta cũng không thể trốn chạy mãi mãi.', 2023, '/Ak5hAxorxMpxKoVw5e3kGfxs7sY.jpg', 7.9, '2026-08-12 13:54:38'),
(168, 1723013, 'Hibla 2', 'tmdb-1723013-hibla-2', '', 2026, '/drDsk2ES8YvWFwgWaY9foKaE5xv.jpg', 3.0, '2026-08-12 13:54:38'),
(169, 674, 'Harry Potter và Chiếc Cốc Lửa', 'tmdb-674-harry-potter-v-a-chic-cc-la', 'Khi giải Quidditch Thế giới bị cắt ngang bởi những kẻ ủng hộ Chúa tể Voldemort và sự trở lại của Dấu hiệu hắc ám khủng khiếp, Harry ý thức được rõ ràng rằng, Chúa tể Voldemort đang ngày càng mạnh hơn. Và để trở lại thế giới phép thuật, Chúa tể hắc ám cần phải đánh bại kẻ duy nhất sống sót từ lời nguyền chết chóc của hắn - Harry Potter. Vì lẽ đó, khi Harry bị buộc phải bước vào giải đấu Tam Pháp thuật uy tín nhưng nguy hiểm, cậu nhận ra rằng trên cả chiến thắng, cậu phải giữ được mạng sống của mình.', 2005, '/yMyn4EAlOv96KCFScKKuowbC5AG.jpg', 7.8, '2026-08-12 13:54:38'),
(170, 1171145, 'Tội Phạm 101', 'tmdb-1171145-ti-phm-101', 'Lấy bối cảnh thành phố Los Angeles đầy nắng và bụi đường, Tội Phạm 101 kể về một tên trộm nữ trang bí ẩn (Chris Hemsworth) với hàng loạt phi vụ táo bạo khiến cảnh sát phải đau đầu. Trong lúc chuẩn bị cho phi vụ lớn nhất của mình, hắn gặp gỡ một nữ nhân viên bảo hiểm (Halle Berry), người cũng đang vật lộn với những lựa chọn trong đời mình. Trong khi đó, một thanh tra (Mark Ruffalo) đã tìm ra quy luật trong chuỗi các vụ án và đang ráo riết truy đuổi tên trộm, khiến cuộc chơi trở nên căng thẳng hơn bao giờ hết. Khi phi vụ định mệnh đến gần, ranh giới giữa kẻ săn đuổi và con mồi dần trở nên mờ nhạt và cả ba buộc phải đối mặt với những lựa chọn khó khăn và không còn cơ hội để quay đầu lại. Bộ phim được chuyển thể từ tiểu thuyết ngắn nổi tiếng cùng tên của Don Winslow, do Bart Layton (tác giả của American Animals, The Imposter) viết kịch bản và đạo diễn. Dàn diễn viên có sự tham gia của Barry Keoghan, Monica Barbaro, Corey Hawkins, Jennifer Jason Leigh và Nick Nolte.', 2026, '/2i7DfVMYX7DyjmQiX64Le8uK45K.jpg', 7.0, '2026-08-12 13:54:38'),
(171, 284053, 'Thần sấm III: Tận Thế Ragnarok', 'tmdb-284053-thn-sm-iii-tn-th-ragnarok', 'Ở bên kia vũ trụ, Thor (Chris Hemsworth) phải bước vào một cuộc chiến đầy khốc liệt với đối thủ mà anh sẽ gặp là một đồng đội cũ đến từ biệt đội Avenger – Hulk. Cuộc tìm kiếm sự sống còn của Thor khiến anh phải chạy đua với thời gian để ngăn chặn Hela (Cate Blanchett) tiêu diệt cả thế giới anh đang sống cùng nền văn minh Asgard.', 2017, '/3qkUzHe7MdNXfInMRtIogP8K82e.jpg', 7.6, '2026-08-12 13:54:40'),
(172, 1305781, 'Tiêu Nhân: Phong Khởi Đại Mạc', 'tmdb-1305781-ti-eu-nh-an-phong-khi-di-mc', 'Trên sa mạc mênh mông, tiêu sư, quan phủ cùng năm đại gia tộc Tây Vực đan xen lợi ích, âm thầm tranh đấu. Đao Mã – kẻ bị truy nã hạng hai thiên hạ – nhận một nhiệm vụ áp tiêu đặc biệt, cùng đồng đội hộ tống một người từ Tây Vực đến Trường An. Không ngờ, người họ bảo vệ lại chính là Tri Thế Lang – kẻ bị truy nã số một thiên hạ. Vì lợi ích riêng, các thế lực liên tiếp nhập cuộc, kéo theo những trận tranh đoạt tiêu hàng và chém giết không ngừng.', 2026, '/qt0pUOaIj6RRGP0v885q29sJWpl.jpg', 8.1, '2026-08-12 13:54:40'),
(173, 1724, 'Người Khổng Lồ Xanh Phi Thường', 'tmdb-1724-ngi-khng-l-xanh-phi-thng', 'Sau nhiều năm bị biến thành kẻ nửa người nửa quái vật The Hulk, nhà khoa học Bruce Banner vẫn phải lần trốn trong rừng rậm Nam Mỹ, tìm cách chữa trị cho chính bản thân mình. Cùng lúc đó anh vẫn bị sự truy lùng của quân đội Mỹ, dẫn dắt bởi tướng Ross và tên Emil Blonsky, kẻ muốn sử dụng sức mạnh của The Hulk. Chính tên này sau đó đã tự lặp lại tai nạn của Bruce Banner, với hy vọng biến mình thành siêu nhân. Nhưng Emil phát hiện ra rằng hắn bị biến thành một con quái vật - the Abomination- và không bao giờ trở lại thành dạng người như Bruce được nữa. Đổ lỗi cho Bruce vì sự đột biến của mình, hắn truy sát anh để trả thù.', 2008, '/gVA3GIcCcda2hYiF6oRWScGhxbc.jpg', 6.3, '2026-08-12 13:54:40'),
(174, 12444, 'Harry Potter và Bảo Bối Tử Thần: Phần 1', 'tmdb-12444-harry-potter-v-a-bo-bi-t-thn-phn-1', 'Chúa tể Voldemort cùng đám tay chân của hắn đang âm mưu tấn công Harry Potter khi cậu rời khỏi ngôi nhà của gia đình Dursley lần cuối cùng. Ngay trước khi phép bảo vệ cho Harry tại gia đình Dursley hết hiệu lực vào thời điểm Harry bước qua tuổi 17, người của Hội Phượng hoàng đến để hộ tống cậu tới một nơi ở mới an toàn. Mặc dù đã dùng sáu người nguỵ trang thành Harry, Harry thật vẫn bị Voldemort cùng các Tử thần Thực tử phát hiện ra trên đường đi và bị tấn công...', 2010, '/6Ia2asQn8uz0oBq3lZLuXQjkOWV.jpg', 7.7, '2026-08-12 13:54:40'),
(175, 14836, 'Cô Bé Coraline', 'tmdb-14836-c-o-b-e-coraline', 'Khi Coraline chuyển đến một ngôi nhà cũ, cô cảm thấy buồn chán và bị cha mẹ bỏ rơi. Cô tìm thấy một cánh cửa ẩn với một lối đi bằng gạch. Trong đêm, cô băng qua hành lang và tìm thấy một thế giới song song, nơi mọi người đều có nút thay vì mắt, với cha mẹ chăm sóc và tất cả ước mơ của cô đều trở thành sự thật. Khi Người Mẹ khác mời Coraline ở lại thế giới của mình mãi mãi, cô gái từ chối và thấy rằng thực tế thay thế nơi cô bị mắc kẹt chỉ là một thủ thuật để thu hút cô.', 2009, '/p8YSnUyQGZQkW1NSgVvn7ubWWCn.jpg', 7.9, '2026-08-12 13:54:40'),
(176, 1288341, 'Seven Snipers', 'tmdb-1288341-seven-snipers', '', 2026, '/pK6tGCG6UAgUT5FTq3ylGErHxQQ.jpg', 6.1, '2026-08-12 13:54:40'),
(177, 950396, 'Hẻm Núi - The Gorge', 'tmdb-950396-hm-n-ui-the-gorge', 'Hai đặc vụ được huấn luyện bài bản dần trở nên thân thiết từ xa sau khi được cử đến canh gác hai bên hẻm núi bí ẩn. Khi thế lực tà ác ở bên dưới xuất hiện, họ phải hợp tác để sống sót trước những gì ẩn chứa bên trong.', 2025, '/kQwCN38RRlJFer6GDB3hR3Ay1mk.jpg', 7.7, '2026-08-12 13:54:40'),
(178, 129, 'Vùng Đất Linh Hồn', 'tmdb-129-v-ung-dt-linh-hn', 'Câu chuyện kể về cô bé bướng bỉnh Chihiro. Gia đình của Chihiro chuyển từ thành phố về quê sinh sống, và Chihiro chẳng thích thú tí nào với sự thay đổi này.  Bố của Chihiro là một tay lái xe tệ hại và có một trí nhớ \"quá tồi\", ông đã lái xe lạc đường đến một thành phố bị bỏ hoang, không bóng người. Bị cuốn hút bởi mùi vị thơm ngon của thức ăn, bố mẹ của Chihiro bắt đầu \"thưởng thức\", nhưng kết quả họ bị biến thành những con heo mập. Còn thành phố không người kia, sau khi trời tối, tất cả sống dậy, những bóng ma bắt đầu xuất hiện và hoạt động. Cô bé bướng bỉnh phải làm gì để cứu bố mẹ mình và thoát khỏi đây?', 2001, '/pNHppsjxGBcRUCFlXQh0briymTN.jpg', 8.5, '2026-08-12 13:54:40'),
(179, 1218925, 'Chainsaw Man - The Movie: Chương Reze', 'tmdb-1218925-chainsaw-man-the-movie-chng-reze', 'Tiếp nối series anime chuyển thể đình đám, Chainsaw Man lần đầu tiên oanh tạc màn ảnh rộng trong một cuộc phiêu lưu hoành tráng, ngập tràn các phân cảnh hành động. Ở phần trước, ta đã biết Denji từng làm Thợ Săn Quỷ cho yakuza để trả món nợ của cha mẹ nhưng bị họ phản bội và trừ khử. Trong khoảnh khắc hấp hối, chú chó quỷ cưa máy Pochita (người bạn đồng hành trung thành của Denji) đã đưa ra một khế ước, cứu sống cậu và hợp thể cùng cậu. Từ đó, một Quỷ Cưa bất khả chiến bại ra đời. Giờ đây ở Chainsaw Man – The Movie: Chương Reze, trong cuộc chiến tàn khốc giữa quỷ dữ, thợ săn quỷ và những kẻ thù trong bóng tối, một cô gái bí ẩn tên Reze xuất hiện trong thế giới của Denji. Denji buộc phải đối mặt với trận chiến sinh tử khốc liệt nhất của mình, một trận chiến được tiếp sức bởi tình yêu trong một thế giới nơi mọi người phải sinh tồn mà không biết bất kỳ luật lệ nào.', 2025, '/kywH6s7qTa64i0drx3pNvpQufWR.jpg', 8.5, '2026-08-12 13:54:40'),
(180, 497, 'Dặm Xanh', 'tmdb-497-dm-xanh', 'Bộ phim là câu chuyện hồi tưởng của một viên coi ngục cai quản những tên tử tù bất trị đang chờ ngày ngồi lên ghế điện trả giá cho những tội ác mà chúng gây ra. Cuộc sống của ông thay đổi hoàn toàn kể từ khi một người tù da đen có khả năng kì lạ xuất hiện trong ngục của ông...', 1999, '/pTEuy2oti9ITTzzrTRZNeSAXzfC.jpg', 8.5, '2026-08-12 13:54:40'),
(181, 350, 'Yêu Nữ Thích Hàng Hiệu', 'tmdb-350-y-eu-n-th-ich-h-ang-hiu', 'Một sinh viên tốt nghiệp thông minh nhưng nhạy cảm mới làm nghề trợ lý cho Miranda Priestly, tổng biên tập tạp chí thời trang cao cấp. Liệu cô ấy có thể hoàn thành công việc cho Miranda khó tính không?', 2006, '/d4nV102c3QLA5T77tjfq9tcCvmi.jpg', 7.4, '2026-08-12 13:54:40'),
(182, 12445, 'Harry Potter và Bảo Bối Tử Thần: Phần 2', 'tmdb-12445-harry-potter-v-a-bo-bi-t-thn-phn-2', 'Kết thúc phần 1 là khi nhóm bạn Harry Potter, Ron và Hermione quay trở lại trường Hogwarts để tìm và tiêu diệt Trường Sinh Linh Giá cuối cùng của Voldemort. Nhưng Voldemort đã phát hiện ra nhiệm vụ của họ, và trận chiến pháp thuật lớn nhất trong lịch sử đã diễn ra ở đây, nơi mà biết bao người ngã xuống, nơi mà tất cả các pháp sư dũng cảm sẵn sàng đánh đổi cuộc sống của mình để tiêu diệt tận cùng thế lực hắc ám. Giáo sư Dumbledore mặc dù đã mất từ tập 6, nhưng ở phần cuối ông vẫn đóng vai trò quan trọng trong việc dẫn đường chỉ lối cho Harry chiến đấu với phù thủy hắc ám mạnh nhất mọi thời đại...', 2011, '/aHlLUx7VKzznUObPbFCUalZ1PVL.jpg', 8.1, '2026-08-12 13:54:40'),
(183, 1669051, 'Kesong Puti', 'tmdb-1669051-kesong-puti', '', 2026, '/8zYU8hlKR5111IToxXvv5575tZG.jpg', 3.8, '2026-08-12 13:54:40'),
(184, 1159559, 'Tiếng Thét 7', 'tmdb-1159559-ting-th-et-7', 'Sidney Evans (Neve Campbell), nạn nhân sống sót của một vụ thảm sát nhiều năm trước, giờ đang sống hạnh phúc cùng chồng và con gái ở một thị trấn khác thì tên sát nhân Ghostface mới lại xuất hiện. Những nỗi sợ hãi đen tối nhất của cô trở thành hiện thực khi con gái cô Tatum Evans (Isabel May) trở thành mục tiêu tiếp theo. Quyết tâm bảo vệ gia đình, Sidney buộc phải đối mặt với những kinh hoàng trong quá khứ để chấm dứt cuộc đổ máu một lần và mãi mãi.', 2026, '/nXXpliMy4Y0mwRa4OlhOb6GyOEE.jpg', 6.2, '2026-08-12 13:54:40'),
(185, 218, 'Kẻ Hủy Diệt', 'tmdb-218-k-hy-dit', 'Năm 2029, những kẻ cai trị Trái Đất quyết định gửi về quá khứ một robot sát thủ mang tên The Terminator - Kẻ Hủy Diệt để thay đổi quá khứ. Nhiệm vụ của tên robot này là giết chết Sarah Connor, người có vai trò quyết định trong cuộc kháng chiến của nhân loại sau này.', 1984, '/dFci3DJsm1hNZbhFJNJ5XvssE5v.jpg', 7.7, '2026-08-12 13:54:40'),
(186, 122917, 'Người Hobbit: Đại Chiến Năm Cánh Quân', 'tmdb-122917-ngi-hobbit-di-chin-nam-c-anh-qu-an', 'Tiếp nối ngay sau đoạn kết của phần hai, rồng Smaug bị thức tỉnh bởi nhóm phiêu lưu của Thorin và nổi giận bay tới tàn phá thị trấn bên hồ. Tuy nhiên, Smaug mau chóng bị cung thủ Bard tiêu diệt và Thorin nhờ đó giành lại được quê hương Erebor. Những tưởng mọi chuyện sẽ yên bình từ đây nhưng sự thất hứa của Thorin với người dân bên hồ và sự thù địch với tộc Tiên rừng mau chóng đẩy họ đến một trận chiến mới. Cùng lúc đó, liên minh Orc và sói ma Warg của tên Azog lầm lũi kéo đến ngọn Cô Sơn với toan tính chiếm lấy vị trí đắc địa và số vàng bên trong Erebor. Một trận giao tranh không khoan nhượng giữa năm đạo binh là điều không thể tránh khỏi.', 2014, '/nfMe2gv6jmUDoEL42TJvjwlvMPP.jpg', 7.3, '2026-08-12 13:54:40'),
(187, 105, 'Trở Về Tương Lai', 'tmdb-105-tr-v-tng-lai', 'Nhà phát minh lập dị Tiến sĩ Brown biến chiếc DeLorean thành cỗ máy thời gian. Cỗ máy này vô tình đưa người bạn trẻ của ông – Marty McFly – trở về quá khứ 30 năm trước.', 1985, '/d8O1txQtDobdenlyL7uArsRezdj.jpg', 8.3, '2026-08-12 13:54:40'),
(188, 385687, 'Quá Nhanh Quá Nguy Hiểm 10', 'tmdb-385687-qu-a-nhanh-qu-a-nguy-him-10', 'Dom Toretto và gia đình anh ta là mục tiêu của đứa con trai đầy thù hận của trùm ma túy Hernan Reyes.', 2023, '/brZzXXQ8GuzlAdu4TJxjhC8ebBL.jpg', 7.0, '2026-08-12 13:54:40'),
(189, 68718, 'Hành Trình Django', 'tmdb-68718-h-anh-tr-inh-django', 'Tài tử \'Titanic\' đóng vai một chủ nô quyến rũ nhưng tàn bạo trong tác phẩm cao bồi miền Tây, \'Django Unchained\' - bộ phim đánh dấu sự trở lại của đạo diễn lừng danh Quentin Tarantino.Tuy lấy bối cảnh là miền Nam nước Mỹ nhưng phong cách của Django Unchained lại là cao bồi miền Tây. Phim nói về hành trình của một người nô lệ da màu (Jamie Foxx đóng) giải cứu người vợ khỏi tay tên chủ điền Calvin Candie nổi tiếng bệnh hoạn và độc ác.', 2012, '/lPqzqx6CtmugocZ6H9M5pAPrbwY.jpg', 8.2, '2026-08-12 13:54:40'),
(190, 1168190, 'Biệt Đội Đập Phá', 'tmdb-1168190-bit-di-dp-ph-a', 'Hai anh em cùng cha khác mẹ Jonny và James đoàn tụ sau cái chết bí ẩn của cha họ. Khi họ tìm kiếm sự thật, những bí mật bị chôn giấu tiết lộ một âm mưu đe dọa chia cắt gia đình họ.', 2026, '/yQ8wtSr156Jli2so4rIA0mViT8m.jpg', 7.1, '2026-08-12 13:54:40'),
(191, 177572, 'Biệt Đội Big Hero 6', 'tmdb-177572-bit-di-big-hero-6', 'Câu chuyện diễn ra tại một thành phố hư cấu có tên là San Fransokyo (tên viết tắt của 2 thành phố San Francisco của Mỹ và Tokyo của Nhật Bản). Đó là nơi ở của cậu bé thần đồng Hiro Hamada cùng với một người bạn hết sức đặc biệt là Baymax. Baymax trông giống như một người tuyết màu trắng, đây là phát minh của Tadashi – anh trai Hiro. Baymax được tạo ra nhằm mục đích phục vụ cho sức khỏe của con người. Với sự thông minh của Hiro, cậu nhóc đã chế tạo ra các công cụ chiến đấu cho biệt đội siêu anh hùng với sự đồng hành của 5 thành viên còn lại là Baymax, Wasabi, Go Go, Fred và Honey Lemon. Họ cùng điều tra về kẻ giấu mặt “kabuki” đã đánh cắp phát minh “bọ siêu nhỏ” của Hiro và ngăn chặn 1 thảm họa đối với thành phố.', 2014, '/nqq1B0c5ylhJZ0m5CdkonHNE2zZ.jpg', 7.7, '2026-08-12 13:54:41'),
(192, 11, 'Chiến Tranh Giữa Các Vì Sao: Phần IV - Niềm Hy Vọng Mới', 'tmdb-11-chin-tranh-gia-c-ac-v-i-sao-phn-iv-nim-hy-vng-mi', 'Luke Skywalker sống trên một trang trại ở hành tinh Tatooine bụi bặm cùng với cô và chú của anh. Luke là một thanh niên gan dạ và rất nóng lòng được trở thành một chiến binh nổi lọan. Lúc này, tên Darth Vader tàn bạo đã thôn tính cả thiên hà và đang hoàn thành một vũ khí hủy diệt khủng khiếp, Death Star. Công chúa Leia, người dẫn đầu phong trào nổi lọan, biết được kế họach này và tìm cách báo cho Obi-Wan Kenobi, một nhà tu hành già nua sống ẩn dật có sức mạnh phi thường. Vô tình tìm thấy mẩu tin báo nguy của công chúa dấu trong người máy R2D2, Luke lên đường tìm kiếm Obi-Wan Kenobi để hợp sức cùng nhau cứu công chúa cũng như giải thóat cả thiên hà...', 1977, '/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', 8.2, '2026-08-12 13:54:41'),
(193, 76341, 'Max Điên: Con Đường Tử Thần', 'tmdb-76341-max-di-en-con-dng-t-thn', 'Mad Max: Fury Road đưa người xem đến với một thế giới hậu tận thế điêu tàn, chỉ còn lại sa mạc và những cuộc đụng độ giữa các phiến quân. Max đang trên đường chạy trốn quá khứ đau thương vì mất vợ và con. Tình cờ, anh gặp một cô gái trẻ Furiosa với mong muốn trở về nhà. Max quyết định giúp đỡ cô, đồng nghĩa với việc trở thành kẻ thù của một băng cướp khét tiếng. Mad Max thực chất là phần 4 của loạt phim được đánh giá cao vào những năm 80, cũng được đạo diễn bởi George Miller ...', 2015, '/uiNPl4ONkYC1a0hGzIFLZSGST3O.jpg', 7.6, '2026-08-12 13:54:41'),
(194, 713704, 'Ma Cây Trỗi Dậy', 'tmdb-713704-ma-c-ay-tri-dy', 'Cuộc đoàn tụ của một cô gái trẻ với người chị xa cách từ lâu biến thành một cuộc chiến sinh tồn đẫm máu khi trận động đất làm thức tỉnh một con ác quỷ cổ xưa có khả năng nhập xác.', 2023, '/2iwGRYzD1IlGfq2zX27uT8WBm6H.jpg', 7.0, '2026-08-12 13:54:41'),
(195, 13, 'Cuộc Đời Forrest Gump', 'tmdb-13-cuc-di-forrest-gump', 'Forrest Gump là một đứa trẻ bất hạnh khi sinh ra đã không có cha, hơn nữa Forrest còn bị thiểu năng. Forrest luôn bị bạn bè cùng trang lứa trêu trọc, bắt nạt. Người bạn duy nhất của Forrest là Jenny, chính Jenny đã phát hiện ra những khả năng đặc biệt của anh. Tốt nghiệp đại học Forrest nhập ngũ và tham chiến ở Việt Nam, Bubba trở thành bạn thân thứ 2 của anh. Forrest rời chiến trường với vết thương và khả năng chơi bóng bàn xuất sắc. Những biến cố nối tiếp nhau xuất hiện làm thay đổi hoàn toàn cuộc đời Forrest.', 1994, '/yvEDqdIQnYUahG6oY9bKHMubqp8.jpg', 8.5, '2026-08-12 13:54:41'),
(196, 767, 'Harry Potter và Hoàng Tử Lai', 'tmdb-767-harry-potter-v-a-ho-ang-t-lai', 'Đây là năm thứ 6 của Harry Potter tại trường Hogwarts. Trong lúc những thế lực hắc ám của Voldemort gieo rắc nỗi kinh hoàng và sợ hãi ở khắp nơi, mọi chuyện càng lúc càng trở nên rõ ràng hơn đối với Harry, cậu sẽ sớm phải đối diện với định mệnh của mình.  Draco Malfoy, kẻ thù không đội trời chung của Harry, có nhiều hành động khả nghi, luôn lén lút đi khắp trường. Vì thế, Harry cho rằng Draco là nội gián của Voldermort và quyết tâm tìm hiểu chính xác chuyện gì đang xảy ra...', 2009, '/6YLJLaqxT6HHQeBMIWvcKpxS1Et.jpg', 7.7, '2026-08-12 13:54:41'),
(197, 10193, 'Câu Chuyện Đồ Chơi 3', 'tmdb-10193-c-au-chuyn-d-chi-3', 'Cậu bé Andy ngày nào nay đã trở thành người lớn sắp sửa phải bước vào ngưỡng cửa đại học. Đống đồ chơi của cậu, bao gồm cả Woody và Buzz Lightyear, bị đưa vào nhà kho. Và trước khi chúng bị tống lên gác mái, bố mẹ cậu vô tình ném chúng đi. Kết quả là một người dọn rác đã đem những món đồ chơi đó đến Sunnyside, một trung tâm vui chơi dành cho trẻ em, và khi tiếng hô “Đồ chơi mới!” được cất lên là lũ trẻ xông vào tranh giành nhau Ken, Barbie, ông Đầu khoai tây và Buzz Lightyear… Vừa cố gắng tồn tại ở trường tiểu học đáng sợ đó, những nhân vật đồ chơi của chúng ta vừa tìm cách quay trở lại ngôi nhà thân thương nơi có cậu chủ Andy vẫn đang chờ đợi chúng. Trải qua rất nhiều chuyến phiêu lưu, cuối cùng họ cũng được trở về nhà, một đoạn kết thực sự cảm động khiến mọi người không cầm được nước mắt trước tình cảm gắn bó của Andy và những món đồ chơi…', 2010, '/1X96GIP5RAErgDXjH0ZP1anv0m1.jpg', 7.8, '2026-08-12 13:54:41'),
(198, 10681, 'Robot Biết Yêu', 'tmdb-10681-robot-bit-y-eu', 'Trong tương lai, trái đất bị bao phủ bởi rác thải, loài người buộc phải rời khỏi trái đất và thay thế vào đó là hàng triệu con rô-bốt nhỏ bé với nhiệm vụ thu dọn rác thải cho đến khi trái đất có thể ở được.  Nhưng chương trình đó thất bại chỉ trừ một chú robot nhỏ bé vẫn chăm chỉ làm công việc của mình, đó chính là WALL-E – robot duy nhất bị bỏ lại trên trái đất bắt đầu có một lỗi nhỏ trong hệ thống: phát triển tính cách của con người. WALL-E lãng mạn mơ ước rằng một ngày cậu sẽ kết giao được với ai đó, và cuộc đời này hẳn còn nhiều điều thú vị hơn công việc buồn tẻ mà cậu làm hàng ngày.  Thế rồi EVE xuất hiện. EVE là cô người máy thăm dò có kiểu dáng đẹp, nhanh nhẹn, có thể bay và được trang bị súng laser. EVE thuộc hạm đội người máy được Phi trưởng của tàu Axiom cử xuống trái đất để làm nhiệm vụ kiểm tra bí mật. Theo đuổi EVE, WALL-E không thể ngờ rằng cậu sẽ vượt qua dải ngân hà và bước vào một chuyến phiêu lưu kỳ thú vượt xa sự tưởng tượng của chính mình.', 2008, '/jNPu8FFumN2gTdUn4Np4kFVobtU.jpg', 8.1, '2026-08-12 13:54:41'),
(199, 675, 'Harry Potter và Mệnh Lệnh Phượng Hoàng', 'tmdb-675-harry-potter-v-a-mnh-lnh-phng-ho-ang', 'Harry tức giận vì bị bỏ rơi ở nhà Dursley trong dịp hè, cậu ngờ rằng Chúa tể hắc ám Voldemort đang tập hợp lực lượng, và vì cậu có nguy cơ bị tấn công, những người Harry luôn coi là bạn đang cố che giấu tung tích cậu. Cuối cùng, sau khi được giải cứu, Harry khám phá ra rằng giáo sư Dumbledore đang tập hợp lại Hội Phượng Hoàng – một đoàn quân bí mật đã được thành lập từ những năm trước nhằm chống lại Chúa tể Voldemort.  Tuy nhiên, Bộ Pháp thuật không ủng hộ Hội Phượng Hoàng, những lời bịa đặt nhanh chóng được đăng tải trên Nhật báo Tiên tri – một tờ báo của giới phù thủy, Harry lo ngại rằng rất có khả năng cậu sẽ phải gánh vác trách nhiệm chống lại cái ác một mình.', 2007, '/51WvjaatMgGZehizhtEGYD7p9kb.jpg', 7.7, '2026-08-12 13:54:41'),
(200, 497698, 'Black Widow: Góa Phụ Đen', 'tmdb-497698-black-widow-g-oa-ph-den', 'Phần phim riêng của Natasha Romanoff bất ngờ tung teaser chính thức với những cảnh hành động mãn nhãn, mang đậm chất điệp viên. Bên cạnh đó, phần phim này cũng sẽ hé lộ quá khứ đen tối và quá trình biến cô trở thành một Black Widow.', 2021, '/qdc2pzHRrSBBRuUsRaDxS6NGJVp.jpg', 7.2, '2026-08-12 13:54:41'),
(201, 1631506, 'La ahorcada', 'tmdb-1631506-la-ahorcada', '', 2026, '/nJG3aJsul9dgiN5j8BtCNU6I9QV.jpg', 5.6, '2026-08-12 13:54:41'),
(202, 1368314, 'Khách', 'tmdb-1368314-kh-ach', 'Vài tuần sau khi bắt đầu hành trình sống trên xe van, một cặp đôi trẻ chứng kiến một vụ tai nạn kinh hoàng khiến người tài xế thiệt mạng. Không lâu sau, họ bị một thực thể quỷ dị bám theo ráo riết — thứ không thể bị cắt đuôi và luôn lần ra họ dù họ chạy đến bất cứ đâu.', 2026, '/39z7di5bi8tW4696SqhN96jxK58.jpg', 7.3, '2026-08-12 13:54:41'),
(203, 240, 'Bố Già 2', 'tmdb-240-b-gi-a-2', 'The Godfather II là phần tiếp theo của tác phẩm nổi tiếng Bố già sản xuất năm 1972. Trong phần thứ hai này sẽ có hai câu chuyện, hai tuyến nhân vật, hai tuyến thời gian song hành nhau. Một là câu chuyện về gia đình mafia Corleone tiếp tục khi Michael lên làm ông trùm và âm mưu mở rộng địa bàn sang Las Vegas lẫn Cuba, xen lẫn với những hồi ức về Bố già khi mới đặt chân đến New York... Bố già phần II được đánh giá là phần tiếp theo thành công nhất trong lịch sử điện ảnh, nhiều người cho rằng bộ phim hay tương đương, thậm chí là hay hơn phần đầu. Cùng với phần đầu tiên, Bố già II được coi là một trong những bộ phim hay nhất mọi thời đại.', 1974, '/flUbm9ZaZ7itOwCzHtx6lnhLMQ4.jpg', 8.6, '2026-08-12 13:54:41'),
(204, 324786, 'Người Hùng Không Súng', 'tmdb-324786-ngi-h-ung-kh-ong-s-ung', 'Phim kể lại cuộc đời của nhân vật có thật Desmond T. Doss - người lính từ chối cầm súng vì lý do tôn giáo. Nhưng ông vẫn trở thành anh hùng khi là một quân y, cứu sống 75 đồng đội trong cuộc chiến đẫm máu tại xứ sở hoa anh đào trong thời kỳ Thế chiến thứ II - Một trong những anh hùng vĩ đại nhất trong lịch sử nước Mỹ chưa bao giờ bắn một viên đạn.', 2016, '/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', 8.2, '2026-08-12 13:54:41'),
(205, 496243, 'Ký Sinh Trùng', 'tmdb-496243-k-y-sinh-tr-ung', 'Bộ phim xoay quanh hai gia đình hoàn toàn trái ngược: một bên vô cùng giàu có, còn một bên luôn sống trong cảnh nghèo túng. Họ tình cờ gặp gỡ và quen biết nhau sau một biến cố không ngờ.', 2019, '/zZydO1LhMhqDAMM86JUi241wT7X.jpg', 8.5, '2026-08-12 13:54:41'),
(206, 502356, 'Anh Em Super Mario movie', 'tmdb-502356-anh-em-super-mario-movie', 'The Super Mario Bros. Movie xoay quanh cuộc phiêu lưu ở thế giới Vương quốc Nấm của anh em thợ sửa ống nước Mario và Luigi. Sau khi tình cờ bước tới vùng đất lạ từ một ống nước, Luigi đã bị chia tách với Mario và rơi vào tay quái vật rùa xấu xa Bowser, hắn đang âm mưu độc chiếm thế giới. Trong lúc cố gắng tìm kiếm người anh em của mình, Mario đã chạm mặt anh bạn nấm Toad và công chúa Peach. Từ đây họ sát cánh bên nhau trên hành trình ngăn chặn thế lực hắc ám.', 2023, '/gRlfFcpPdjREQ3lgeuAuB10gfbR.jpg', 7.6, '2026-08-12 13:54:41'),
(207, 1101412, 'Cú Rơi Tử Thần 2: Điểm Chết', 'tmdb-1101412-c-u-ri-t-thn-2-dim-cht', 'Sau cái chết của chị gái Hunter, Jax tìm thấy chút an ủi nơi Luce, người bạn gan dạ từng thân thiết với Hunter. Để đối diện nỗi mất mát, họ cùng thử thách cung đường ván treo khét tiếng trên núi Kwan ở Thái Lan, nhưng một vụ sạt lở bất ngờ khiến Jax mắc kẹt ở độ cao 3,000 feet, nơi chỉ một bước sai cũng có thể là dấu chấm hết.', 2026, '/p73G56bJGPa5y52cyqWscHR6NnN.jpg', 0.0, '2026-08-12 13:54:41'),
(208, 1198994, 'Cứu', 'tmdb-1198994-cu', 'Hai đồng nghiệp trở thành những người sống sót duy nhất sau một vụ rơi máy bay và bị mắc kẹt trên một hòn đảo hoang. Tại đây, họ buộc phải gạt bỏ những mâu thuẫn trong quá khứ để hợp tác sinh tồn. Nhưng càng kéo dài, cuộc chiến không chỉ còn là chống chọi với thiên nhiên khắc nghiệt — mà trở thành màn đấu trí và đấu ý chí, nơi chỉ những người đủ tỉnh táo và quyết liệt mới có cơ hội thoát ra sống sót.', 2026, '/hu5J1hJYToOxjceeqyXogq5nRwt.jpg', 7.0, '2026-08-12 13:54:41'),
(209, 1358280, 'Taboo: Family Secrets', 'tmdb-1358280-taboo-family-secrets', '', 2024, '/xatpxQfUVblKveWHXNOidaNg4ju.jpg', 5.0, '2026-08-12 13:54:41'),
(210, 447273, 'Nàng Bạch Tuyết', 'tmdb-447273-n-ang-bch-tuyt', 'Câu chuyện của Nàng Bạch Tuyết ban đầu cũng giống như cổ tích, khi nàng công chúa mới chào đời, mang niềm vui và sự ấm áp tới cả vương quốc xinh đẹp. Mẹ mất sớm, cha bao bọc nàng bằng tất cả tình yêu thương, dạy nàng phải sống không sợ hãi, công bằng, dũng cảm và chân thành. Bạch Tuyết càng lớn lên càng lay động lòng người, với vẻ đẹp thuần khiết như ánh nắng ban mai và một trái tim thiện lương, nhân hậu. Thế nhưng, những ngày tháng vui vẻ không kéo dài lâu khi cha cô cũng qua đời. Ngày hoàng hậu mới lên ngôi, bóng tối bao trùm cả vương quốc. Độc ác và đầy dã tâm, ả không có lòng khoan dung, sẵn sàng trừng phạt bất cứ ai dám làm trái lệnh. Sự ghen ghét, đố kỵ của mẹ kế đẩy Bạch Tuyết vào cảnh nguy hiểm. Nàng phải chạy trốn vào rừng sâu, nơi cuộc phiêu lưu của nàng bắt đầu với những người bạn tốt bụng mới.', 2025, '/24vmIaNTaXPXKdveylQ2C3hcWaD.jpg', 4.3, '2026-08-12 13:54:41'),
(211, 10195, 'Thần Sấm I', 'tmdb-10195-thn-sm-i', 'Phim Thor xoay quanh một chiến binh hùng mạnh nhưng do kiêu ngạo, bị tước hết quyền năng và bị đày xuống Trái Đất.', 2011, '/lBXpsvbXUxgim1m5cb56rxDWmAT.jpg', 6.8, '2026-08-12 13:54:42'),
(212, 424, 'Bản Danh Sách Của Schindler', 'tmdb-424-bn-danh-s-ach-ca-schindler', 'Bản danh sách của Schindler (Schindler`s List) là một bộ phim truyện sản xuất năm 1993 của Hoa Kỳ về Oskar Schindler, một nhà kinh doanh người Đức. Phim bắt đầu vào năm 1939 với sự tập trung người Ba Lan gốc Do Thái của chính quyền Đức Quốc Xã sau khi xâm lược Ba Lan, từ việc bao vây, giam lỏng trong vùng tới xây dựng những khu tập trung Kraków Ghetto không lâu sau khi Đệ nhị thế chiến bắt đầu. Trong lúc đó, Oskar Schindler (Liam Neeson), một doanh nhân thất bại, đến thành phố từ Sudetenland với những hy vọng làm giàu.', 1993, '/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', 8.6, '2026-08-12 13:54:42'),
(213, 950387, 'Một bộ phim Minecraft', 'tmdb-950387-mt-b-phim-minecraft', 'Chào mừng bạn đến với thế giới của Minecraft, nơi sự sáng tạo không chỉ giúp bạn chế tạo mà còn là yếu tố quan trọng để sống sót! Bốn kẻ lạc lõng - Garrett “The Garbage Man” Garrison (Momoa), Henry (Hansen), Natalie (Myers) và Dawn (Brooks) - bất ngờ gặp rắc rối khi họ bị kéo qua cánh cửa bí ẩn dẫn đến Overworld: một thế giới kỳ lạ được tạo bởi những khối lập phương và phát triển nhờ vào trí tưởng tượng. Để trở về nhà, họ cần phải làm chủ được thế giới này (và bảo vệ nó khỏi những thực thể tà ác như Piglins và Thây Ma) trong khi dấn thân vào chuyến phiêu lưu màu nhiệm với một thợ chế tạo chuyên nghiệp và khó lường - Steve (Black). Chuyến hành trình này sẽ thách thức sự can đảm của cả năm người, thúc đẩy họ tìm lại với những phẩm chất làm nên sự đặc biệt của riêng mình,… đồng thời là những kỹ năng cần thiết để trở lại với thế giới thật.', 2025, '/wRrGBv4uNofBVyShxfS0iugbcm8.jpg', 6.2, '2026-08-12 13:54:42'),
(214, 335984, 'Tội Phạm Nhân Bản 2049', 'tmdb-335984-ti-phm-nh-an-bn-2049', 'Một chàng trai trẻ khám phá ra bí mật khiến xã hội rơi vào cảnh hỗn mang. Anh lên đường đi tìm một người khác đã mất tích cách đây ba mươi năm, để rồi cả hai cùng bước vào hành trình cứu thế giới. 35 năm sau ngày phần đầu tiên ra mắt, Blade Runner trở lại với những gương mặt mới, câu chuyện mới, đầy hứa hẹn vẫn sẽ giữ được cái “chất” khiến thương hiệu này trở thành tác phẩm kinh điển trong lịch sử điện ảnh. Nhà sản xuất vừa tung ra trailer đầu tiên của phim do bộ đôi Ridley Scott - sản xuất và Denis Villeneuve - đạo diễn với vô số tình tiết bất ngờ có thể hứa hẹn đây là sẽ bom tấn đáng để chúng ta ra rạp thưởng thức. Phim được xem là tác phẩm kinh điển của thể loại khoa học viễn tưởng.', 2017, '/gK8fMij79A3k3JiryGKYYHq7hb8.jpg', 7.6, '2026-08-12 13:54:42'),
(215, 1185806, 'PAW Patrol: Phim Khủng Long', 'tmdb-1185806-paw-patrol-phim-khng-long', 'Khi con tàu của Paw Patrol bị cuốn vào một cơn bão bí ẩn, đội cún cứu hộ vô tình lưu lạc đến một hòn đảo nhiệt đới vô danh, nơi sinh sống của nhiều loài khủng long cổ xưa. Họ gặp Rex, một chuyên gia về khủng long, đã mắc kẹt trên hòn đảo này trong nhiều năm. Mọi chuyện trở nên tệ hơn khi Thị trưởng Humdinger, đối thủ không đội trời chung của PAW Patrol rắp tâm khai thác nguồn tài nguyên thiên nhiên tại đây, và vô tình gây ra trận phun trào của một ngọn núi lửa khổng lồ. Đứng trước nguy cơ hòn đảo bị xóa sổ, đội cún cứu hộ phải thực hiện những nhiệm vụ quy mô \"khủng\" hơn bao giờ hết để ngăn chặn Humdinger và cứu các loài khủng long khỏi nạn tuyệt chủng.', 2026, '/ucma9OplmkRE9AJr1rhFUr7NF59.jpg', 7.4, '2026-08-12 13:54:42'),
(216, 12, 'Đi Tìm Nemo', 'tmdb-12-di-t-im-nemo', 'Nemo, một chú cá hề trẻ thích phiêu lưu, bất ngờ được đưa từ nhà Great Barrier Reef của mình đến một bể cá văn phòng của nha sĩ. Cha Marlin lo lắng và một chú cá thân thiện nhưng hay quên Dory mang Nemo về nhà - gặp gỡ cá mập ăn chay, lướt rùa rùa, sứa thôi miên, hải âu đói, và nhiều thứ khác trên đường đi.', 2003, '/scAcBk4q6g8DWt8yryWlnc006ad.jpg', 7.8, '2026-08-12 13:54:42'),
(217, 798645, 'Trốn Chạy Tử Thần', 'tmdb-798645-trn-chy-t-thn', 'Trong bối cảnh xã hội tương lai gần, Trốn Chạy Tử Thần là chương trình truyền hình ăn khách nhất, một cuộc thi sinh tồn khốc liệt nơi các thí sinh, được gọi là “Runners”, phải trốn chạy suốt 30 ngày khỏi sự truy đuổi của các sát thủ chuyên nghiệp. Mọi bước đi của họ đều được phát sóng công khai cho khán giả theo dõi và phần thưởng tiền mặt sẽ tăng lên sau mỗi ngày sống sót. Vì cần tiền cứu chữa cho cô con gái bệnh nặng, Ben Richards, một người lao động nghèo, chấp nhận lời mời từ Dan Killian, nhà sản xuất chương trình bảnh bao nhưng tàn nhẫn, để tham gia cuộc chơi như một lựa chọn cuối cùng. Tuy nhiên, sự gan lì, nhạy bén và ý chí sinh tồn mãnh liệt của Ben lại khiến anh bất ngờ trở thành nhân vật được khán giả yêu thích nhất và là mối đe dọa với cả hệ thống. Khi lượng người xem tăng vọt, hiểm nguy cũng ngày càng bủa vây. Giờ đây, Ben không chỉ phải đối mặt với toán sát thủ mà còn cả một đất nước đang nghiện cảm giác chứng kiến anh gục ngã.', 2025, '/lSUUBWX1vp4WkjTUkd2mbRUuwt8.jpg', 6.7, '2026-08-12 13:54:42'),
(218, 539972, 'Kraven: Thợ Săn Thủ Lĩnh', 'tmdb-539972-kraven-th-san-th-l-inh', 'Sergei Kravinoff (Aaron Taylor-Johnson thủ vai) cùng bố của anh đi săn ở Châu Phi. Bố của Sergei Kravinoff là một tay săn lão luyện. Khi Sergei bị một con sư tử tấn công, bố của anh cho rằng anh chỉ là một kẻ yếu đuối. Mặc dù bị sư tử cắn và bị chính bố mình bỏ mặc, nhưng Sergei đã không chết mà thay vào đó, vết cắn lại cho Sergei một sức mạnh phi thường. Cũng từ đây, gã nhập cư Sergei Kravinoff đang thực hiện nhiệm vụ chứng minh rằng anh ta là thợ săn vĩ đại nhất thế giới.', 2024, '/1BMqOORP7cnYyrfR2nectAQLw1I.jpg', 6.4, '2026-08-12 13:54:42');
INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `slug`, `description`, `release_year`, `poster_path`, `rating`, `created_at`) VALUES
(219, 210577, 'Cô Gái Mất Tích', 'tmdb-210577-c-o-g-ai-mt-t-ich', 'Sau sự mất tích kỳ lạ của người vợ trẻ vào dịp kỷ niệm 5 năm ngày cưới của cô, người chồng trở thành tâm điểm của báo giới cùng hàng loạt những nghi ngờ và giả thuyết được tô vẽ xung quanh vụ án. Những bí ẩn dần được hé lộ đằng sau bức tranh gia đình hạnh phúc của cả hai. Cảnh sát sẽ phát hiện ra điều gì? Người vợ còn sống hay đã chết? Hung thủ thật sự có phải là người chồng gắn bó với cô?', 2014, '/aiNGDTuyaBUjuP7jJw7N3WpOGDX.jpg', 7.9, '2026-08-12 13:54:42'),
(220, 284054, 'Chiến Binh Báo Đen', 'tmdb-284054-chin-binh-b-ao-den', 'Vương quốc Wakanda, quê hương của Black Panther/ T\'Challa hiện ra qua lời kể của một nhân chứng sống sót trở về. Đây là quốc gia khá khép kín và sở hữu lượng Vibranium lớn nhất trên thế giới. Black Panther - người cầm quyền của Wakanda sở hữu bộ áo giáp chống đạn và móng vuốt sắc nhọn, anh được miêu tả là “người tốt với trái tim nhân hậu”.  Nhưng cũng chính vì những đức tính tốt này mà Black Panther gặp khó khăn khi kế thừa ngai vàng sau khi vua cha băng hà. Đối mặt với sự phản bội và hiểm nguy, vị vua trẻ phải tập hợp các đồng minh và phát huy toàn bộ sức mạnh của Black Panther để đánh bại kẻ thù, đem lại an bình cho nhân dân của mình.', 2018, '/9ZXDxPBesqJeQPbaA7xj0dZtClV.jpg', 7.4, '2026-08-12 13:54:42'),
(221, 558449, 'Võ Sĩ Giác Đấu II', 'tmdb-558449-v-o-s-i-gi-ac-du-ii', '20 năm trước, một anh hùng đã được sinh ra và nhanh chóng thống trị mọi mặt trận phòng vé toàn cầu đầy kiêu hãnh. Tên gã là \"Maximus Decimus Meridius, chỉ huy quân đội phương Bắc, tướng quân của Felix Legions, người trung thành với hoàng đế chân chính Marcus Aurelius, cha của một đứa con đã bị giết, chồng của một người vợ đã bị giết. Và tôi sẽ trả thù, trong kiếp này hoặc kiếp sau\". Và 20 năm sau, Võ Sĩ Giác Đấu II tiếp nối với câu chuyện được thúc đẩy bởi nỗi căm thù của cậu bé Lucius, lúc này đã là một chàng võ sĩ giác đấu cường tráng bị ép buộc phải bước vào Đấu Trường La Mã khi cả vương quốc của mình rơi vào tay những gã Hoàng Đế bạo chúa.', 2024, '/xLIOLFWm4PgkXKVmHcmnjuxktSg.jpg', 6.6, '2026-08-12 13:54:42'),
(222, 68721, 'Người Sắt 3', 'tmdb-68721-ngi-st-3', 'Từ sau những sự kiện và những trận chiến đầy ám ảnh trong The Avengers, Tony Stark quay về ở ẩn trong căn biệt thự sang trọng của mình, tạm thời chờ đợi trong tư cách một tỷ phú giàu có được yêu mến và gác danh phận siêu anh hùng sang một bên.  Tuy nhiên, những hiểm họa mới lại tiếp tục xuất hiện dưới bóng ma bao trùm của một quái nhân, đồng thời cũng là một thiên tài về công nghệ - The Mandarin. Người bạn thân trong lực lượng quân đội Hoa Kỳ của Tony - James Rhodes cần tới sự giúp đỡ của anh và những bộ giáp siêu việt.  Mọi chuyện không hề dễ dàng như Tony và James tưởng tượng: dưới sức mạnh thần bí của mười chiếc nhẫn vũ trụ, The Mandarin đã đánh bại \"Người Sắt\", đồng thời khiến siêu anh hùng - tỷ phú trở thành kẻ mất trí nhớ...', 2013, '/o0dmWIrF63lBPQVFdvqaWUxQ7xz.jpg', 6.9, '2026-08-12 13:54:42'),
(223, 138843, 'Ám Ảnh Kinh Hoàng', 'tmdb-138843-am-nh-kinh-ho-ang', 'Ed và Lorraine Warren, là những nhà điều tra các hiện tượng siêu nhiên xảy ra trên nước Mỹ. Những báo cáo của họ còn truyền cảm hứng cho cuốn tiểu thuyết Amityville Horror. Trong phim hai vợ chồng Warren là những người điều tra các hiện tượng siêu nhiên, họ đến để hỗ trợ gia đình Perron đang trải qua các sự kiện ngày càng đáng lo ngại trong trang trại của họ ở Harrisville, Rhode Island vào năm 1971.', 2013, '/qic7Xa1fnwLyEsjvjapDTEMYXsR.jpg', 7.5, '2026-08-12 13:54:42'),
(224, 49026, 'Kỵ Sĩ Bóng Đêm Trỗi Dậy', 'tmdb-49026-k-s-i-b-ong-d-em-tri-dy', 'Sau 8 năm kể từ ngày người dơi nhận trách nhiệm giết người thay cho Dent, Bane - một kẻ cầm đầu khủng bố mới xuất hiện và đàn áp Gotham. Và một lần nữa Hiệp sĩ bóng đêm đã trở lại để bảo vệ thành phố từng săn lùng anh như kẻ thù.', 2012, '/5WFuvfiHRghbepz3I6zc1KeHIly.jpg', 7.8, '2026-08-12 13:54:42'),
(225, 1306368, 'Ranh giới tội ác', 'tmdb-1306368-ranh-gii-ti-ac', 'Lòng tin rạn nứt khi đội cảnh sát Miami phát hiện thấy hàng triệu đô la tiền mặt bên trong một nhà chứa đồ đổ nát, khiến mọi người – và mọi thứ – bị đặt vào vòng nghi vấn.', 2026, '/6xL4Ei29kVIR8BXYyTAVMsggs87.jpg', 7.1, '2026-08-12 13:54:42'),
(226, 552524, 'Lilo và Stitch', 'tmdb-552524-lilo-v-a-stitch', 'Cuộc sống của hai chị em bị xáo trộn khi Lilo nhận nuôi một \"con chó\" kỳ lạ từ trại cứu hộ động vật. Con vật đó thực chất là Thí nghiệm 626, hay còn gọi là Stitch (lồng tiếng bởi Chris Sanders, người lồng tiếng cho Stitch trong bản hoạt hình gốc), một sinh vật ngoài hành tinh được tạo ra bởi nhà khoa học điên rồ Dr. Jumba Jookiba (Zach Galifianakis) với mục đích gây hỗn loạn. Stitch là một \"quả bóng hủy diệt\" không thể kiểm soát, nhưng Lilo lại coi cậu bé là người bạn thân nhất mà cô hằng mong ước.', 2025, '/aOfmWQHIdunw4Xnc4ZL7DUDDgNl.jpg', 7.2, '2026-08-12 13:54:42'),
(227, 508947, 'Gấu Đỏ Biến Hình', 'tmdb-508947-gu-d-bin-h-inh', 'Với \"Gấu Đỏ Biến Hình\", Disney và Pixar mang đến cô bé 13 tuổi Mei Lee (Rosalie Chiang lồng tiếng) đầy tự tin, hơi ngố, đang bị giằng xé giữa hình ảnh con ngoan và sự nổi loạn của tuổi mới lớn. Sự bảo vệ và đeo bám hơi thái quá của mẹ Ming (Sandra Oh lồng tiếng) cũng là một rắc rối mà cô bé phải đối mặt. Không chỉ bối rối vì các thay đổi về sở thích, tình cảm và cơ thể, cô bé còn có một vấn đề nan giải khác. Bất cứ khi nào quá phấn khích (một việc THƯỜNG XUYÊN xảy ra), cô bé sẽ \"biến hình\" thành một con gấu trúc đỏ khổng lồ! Sản phẩm của đạo diễn Domee Shi (đoạt giải Oscar với hoạt hình Pixar ngắn \"Bao\") và nhà sản xuất Lindsey Collins. Một số phân đoạn có họa tiết hoặc hiệu ứng chớp sáng có thể gây ảnh hưởng lên các khán giả nhạy cảm. Một số phân đoạn có họa tiết hoặc hiệu ứng chớp sáng có thể gây ảnh hưởng lên các khán giả nhạy cảm.', 2022, '/fnoJLyLttGjLzJEM0B0RnyJN20y.jpg', 7.3, '2026-08-12 13:54:42'),
(228, 1022789, 'Những Mảnh Ghép Cảm Xúc 2', 'tmdb-1022789-nhng-mnh-gh-ep-cm-x-uc-2', 'Những Mảnh Ghép Cảm Xúc 2 sẽ quay trở lại phần tâm trí mới của cô bé thiếu niên Riley. Một ngày, trụ sở chính đột ngột bị phá hủy để nhường chỗ cho một thứ hoàn toàn mới: Một cảm xúc mới! Vui Vẻ, Buồn Bã, Giận Dữ, Sợ Hãi và Chán Ghét phải \'chào đón\' sự xuất hiện của một loại cảm xúc mới là Lo Âu. Và có vẻ như cô ấy không chỉ xuất hiện một mình.', 2024, '/wAIFnJ5OeFU7tTnCWHiROsszS29.jpg', 7.5, '2026-08-12 13:54:42'),
(229, 1305672, '抓特务', 'tmdb-1305672-movie', '', 2026, '/xuLUtumvstPx00t3PBsLI7GTENA.jpg', 6.3, '2026-08-12 13:54:43'),
(230, 354912, 'Coco: Hội Ngộ Diệu Kỳ', 'tmdb-354912-coco-hi-ng-diu-k-y', 'Coco sẽ kể về hành trình của Miguel, một cậu bé say mê những giai điệu nhưng lại sinh trưởng trong một gia đình cấm đoán sự xuất hiện của âm nhạc. Miguel luôn nung nấu giấc mơ trở thành một nhạc sĩ nổi tiếng giống như thần tượng Ernesto de la Cruz. Tuy nhiên, truyền thống ngang trái của gia đình đã khiến cậu không thể chứng minh tài năng của mình.  Rũ bỏ thực tế phũ phàng, Miguel tìm thấy chính mình ở Vùng Đất Linh Hồn (Land of the Dead) tuyệt đẹp và đầy sắc màu sau một chuỗi sự kiện huyền bí. Trong hành trình khám phá vùng đất mới, Miguel gặp gỡ “chuyên gia xảo quyệt” Hector. Cả hai cùng tạo nên chuyến phiêu lưu kỳ diệu để lật mở những bí mật chưa được tiết lộ về lịch sử của gia đình Miguel.', 2017, '/tKd5zI6gLBwrqqyicHyRD3IyosW.jpg', 8.2, '2026-08-12 13:54:43'),
(231, 807, 'Thất Đại Tội', 'tmdb-807-tht-di-ti', 'Hai viên cảnh sát William Somerset và David Mills phối hợp điều tra một vụ án phức tạp liên quan đến 7 điều cấm trong Kinh thánh. Hung thủ được dự đoán là do trước kia hắn lớn lên trong môi trường đạo nghiêm khắc nên tâm lí bất ổn và rồi lần lượt giết người dựa trên 7 tội lỗi trong Kinh thánh mà hắn gán cho mỗi người.  7 tội lỗi đó là: kiêu hãnh (Pride), ghen tị (Envy), ham ăn (Gluttony), sắc dục (Lust), tức giận (Wrath), tham lam (Greed) và lười biếng (Sloth). Án mạng đầu tiên là một tên béo phì với dòng chữ Gluttony viết bằng máu trên tường. Greed là án mạng xảy ra sau đó ở nơi làm của 1 tên luật sư. Một tên buôn ma túy tên Victor bị giết với tội lười biếng - Sloth. Lust là tội gán cho một cô gái điếm. Cuối cùng, Pride là 1 cô nàng quá mải mê chăm chút bề ngoài của mình.', 1995, '/vor5v1DDqPVwOQCVKciPqrXmV3S.jpg', 8.4, '2026-08-12 13:54:44'),
(232, 76338, 'Thần Sấm II: Thế Giới Bóng Tối', 'tmdb-76338-thn-sm-ii-th-gii-b-ong-ti', 'Thor: Thần Sấm phải chiến đấu để cứu trái đất và tất cả Cửu Giới từ một kẻ thù trong bóng tối. Trong khi Thor chiến đấu để lập lại trật tự trên vũ trụ thì một chủng tộc cổ xưa Malekith vì lợi nhuận đã làm mọi cách để kéo vũ trụ trở lại vào bóng tối. Phải đối mặt với một kẻ thù mà ngay cả Odin và Asgard không thể chịu được, Thor phải bắt tay vào hành trình nguy hiểm nhất. Đặc biệt, Thor lại cơ hội tái hợp lại với Jane Foster nhưng anh buộc phải hy sinh mọi thứ để cứu tất cả chúng ta. Liệu Thor sẽ chọn Jane Foster hay chấp nhận đánh đổi vì sứ mạng của mình? Là rồi Thần Sấm có giải cứu được trái đất?', 2013, '/zwFRrj1CF3YbfCzjhxPvzrQojor.jpg', 6.5, '2026-08-12 13:54:44'),
(233, 585, 'Công Ty Quái Vật', 'tmdb-585-c-ong-ty-qu-ai-vt', 'Bộ phim nói về một ngôi làng chỉ toàn là Monsters sinh sống. Và trong ngôi làng đó có một xưởng sản xuất mang tên gọi là Monster, Inc. là một xưởng sản xuất điện cho cả thành phố. Còn điện thì đến từ... \"tiếng thét\" của các em bé bị các Monsters nhát ma. Và trong số những anh chàng Monsters thuộc hàng sao của hãng , chuyên thu thập nhiều điện nhất là Sulley và anh chàng một mắt bé xíu, một trợ lý đắc lực Mike... Thành phố này có cuộc sống bình thường cho đến một ngày... hai chàng gặp đối thủ của mình.... Và từ những tranh chấp đó, một cô bé con đã tình cờ lạc vào xứ sở Monster, gây nên nỗi kinh hoàng cho tất cả mọi người. Nhưng điều lý thú là cô bé này lại lạc vào tay anh chàng Monster nổi tiếng dữ dằn nhất...', 2001, '/6GR1pSdLBa2ktKizMogoW73n3US.jpg', 7.9, '2026-08-12 13:54:44'),
(234, 1087192, 'Bí Kíp Luyện Rồng', 'tmdb-1087192-b-i-k-ip-luyn-rng', 'Phiên bản Live Action (người đóng) của studio DreamWorks rất được mong chờ đã ra mắt. Câu chuyện về một chàng trai trẻ với ước mơ trở thành thợ săn rồng, nhưng định mệnh lại đưa đẩy anh đến tình bạn bất ngờ với một chú rồng.', 2025, '/cLq0IEiC7vvb013UbsCLhS5puX.jpg', 7.9, '2026-08-12 13:54:44'),
(235, 505642, 'Chiến Binh Báo Đen: Wakanda Bất Diệt', 'tmdb-505642-chin-binh-b-ao-den-wakanda-bt-dit', 'Nữ hoàng Ramonda, Shuri, M’Baku, Okoye và Dora Milaje chiến đấu để bảo vệ quốc gia của họ khỏi sự can thiệp của các thế lực thế giới sau cái chết của Vua T’Challa. Khi người Wakanda cố gắng nắm bắt chương tiếp theo của họ, các anh hùng phải hợp tác với nhau với sự giúp đỡ của War Dog Nakia và Everett Ross và tạo ra một con đường mới cho vương quốc Wakanda.', 2022, '/aHQCq7dRaDdMVT2ojKnpjpBp55Y.jpg', 7.0, '2026-08-12 13:54:44'),
(236, 1054867, 'Trận Chiến Sau Trận Chiến', 'tmdb-1054867-trn-chin-sau-trn-chin', 'Mười sáu năm sau ngày kẻ thù tàn bạo bị xóa sổ, nhóm cựu chiến sĩ cách mạng buộc phải tái hợp để giải cứu con gái của một đồng đội thân thiết trong nhóm, đối mặt với hiểm nguy mới để bảo vệ di sản tình nghĩa và lý tưởng của họ.', 2025, '/wQ0IDT8rXOvCt6LflxcMEOUNBUS.jpg', 7.3, '2026-08-12 13:54:44'),
(237, 1266127, 'Trò Chơi Của Quỷ 2', 'tmdb-1266127-tr-o-chi-ca-qu-2', 'Chỉ ít phút sau khi sống sót khỏi cuộc tấn công toàn diện của gia tộc Le Domas, Grace nhận ra mình đã bước sang cấp độ tiếp theo của trò chơi ác mộng — lần này, với người chị em xa cách Faith đứng bên cạnh. Grace chỉ có một cơ hội để sống sót, bảo vệ em gái, và giành lấy Ngai Cao của Hội Đồng — thế lực đang kiểm soát cả thế giới. Bốn gia tộc đối địch đang truy lùng cô để đoạt lấy ngai vàng, và kẻ chiến thắng sẽ thống trị tất cả.', 2026, '/9eWzfMfdd9JHDhPqKdNB9Y08T6B.jpg', 7.6, '2026-08-12 13:54:44'),
(238, 150540, 'Những Mảnh Ghép Cảm Xúc', 'tmdb-150540-nhng-mnh-gh-ep-cm-x-uc', 'Phim Inside Out là bộ phim dài thứ 15 của Disney và Pixar kể về cô bé tuổi teen bình thường Riley. Như bao bạn bè đồng trang lứa khác, bước vào tuổi dậy thì là một quá trình gian nan với Riley, và cô bé còn bị thử thách bởi một biến cố bất ngờ khi buộc phải chia tay bạn bè, và cuộc sống hiện tại để cùng bố mẹ đến sống tại một thành phố hoàn toàn xa lạ.  Cũng như tất cả chúng ta, Riley chịu sự điều khiển của cảm xúc bên trong tâm trí mình, và với Inside Out, những cảm xúc đó đã được nhân cách hóa thành những nhân vật trên màn ảnh, đó là: Joy (Vui vẻ), Fear (Sợ sệt), Anger (Giận dữ), Sadness (Buồn bã) và Disgust (Chán ghét).', 2015, '/iSPYSsRnDVyLyWhoGOQA5V4vux4.jpg', 7.9, '2026-08-12 13:54:44'),
(239, 1390300, 'Chỉ khi nào ngươi chết đi', 'tmdb-1390300-ch-khi-n-ao-ngi-cht-di', 'Một cặp vợ chồng rối loạn chức năng đi đến căn nhà gỗ hẻo lánh để \"kết nối lại\", nhưng mỗi người đều có ý định bí mật giết người kia.', 2026, '/kZCauMzAt9eMAhLMopCqnFw1Q5k.jpg', 6.4, '2026-08-12 13:54:44'),
(240, 283995, 'Vệ Binh Dải Ngân Hà 2', 'tmdb-283995-v-binh-di-ng-an-h-a-2', 'Guardians Of The Galaxy - Vệ binh dải ngân hà Phần 2 tiếp tục câu chuyện về bộ tứ huyền thoại của thiên hà. Lần này, cả nhóm sẽ bắt đầu cuộc phiêu lưu mới nhằm tìm ra bí ẩn thân thế của Star Lord – Peter Quill và viên Power Infinity Gem sở hữu sức mạnh vô song. Nhân vật anti-hero Yondu sẽ có vai trò quan trọng hơn nữa trong phần này, bên cạnh đó cô em gái Nebula của Gamora cũng sẽ trở lại.', 2017, '/bqemb9J8lAfYWdNXOPoK1JkHt3x.jpg', 7.6, '2026-08-12 13:54:44'),
(241, 293660, 'Deadpool', 'tmdb-293660-deadpool', 'Lấy cảm hứng từ nhân vật \"phản anh hùng\" tiếng tăm bậc nhất trong tuyển tập truyện tranh Marvel, Deadpool xoay quanh câu chuyện về Wade Wilson - kẻ ban đầu nằm trong Lực Lượng Đặc Biệt sau đó trở thành một lính đánh thuê. Sau khi trải qua một cuộc thử nghiệm tàn khốc, anh có được năng lực tự phục hồi phi thường, từ đó lấy biệt danh Deadpool. Mang trong mình khả năng mới và khiếu hài hước dị thường, Deadpool quyết săn lùng người đàn ông đã hủy hoại cả cuộc đời mình.', 2016, '/cFi3j0Njdoe4Ty8xiqw3BKMnzRv.jpg', 7.6, '2026-08-12 13:54:44'),
(242, 475557, 'Joker: Gã Hề', 'tmdb-475557-joker-g-a-h', 'Joker từ lâu đã là siêu ác nhân huyền thoại của điện ảnh thế giới. Nhưng có bao giờ bạn tự hỏi, Joker đến từ đâu và điều gì đã biến Joker trở thành biểu tượng tội lỗi của thành phố Gotham? JOKER sẽ là cái nhìn độc đáo về tên ác nhân khét tiếng của Vũ trụ DC – một câu chuyện gốc thấm nhuần, nhưng tách biệt rõ ràng với những truyền thuyết quen thuộc xoay quanh nhân vật mang đầy tính biểu tượng này. Bộ phim đã xuất sắc giành giải thưởng Sư Tử Vàng- Phim Hay Nhất tại LHP Venice lần thứ 76, cùng tràng pháo tay dài 8 phút, và lời khen ngợi dành cho diễn xuất của tài tử Joaquin Phoenix. Một bộ phim không thể bỏ lỡ của tháng 10 năm nay.', 2019, '/7DIrtrRgZWWO8jXklLXkkivqpBG.jpg', 8.1, '2026-08-12 13:54:44'),
(243, 1408170, 'లెనిన్', 'tmdb-1408170-movie', '', 2026, '/rAHQviBq8Fxi20hNtHPGLnr4L0f.jpg', 6.4, '2026-08-12 13:54:44'),
(244, 1086268, 'Тrоје', 'tmdb-1086268-r', '', 2023, '/5mKQPfSpfR0BleflXfV5tyfsh3c.jpg', 6.5, '2026-08-12 13:54:44'),
(245, 18785, 'Ba Chàng Ngự Lâm', 'tmdb-18785-ba-ch-ang-ng-l-am', 'The Hangover là bộ phim hài hước xoay quanh cuộc phiêu lưu của ba anh chàng độc thân. Doug Billings sắp kết hôn, ba chàng bạn thân Phil Wenneck, Stu Price, và cậu em rể Alan Garner quyết phải cùng Doug trải qua một buổi tiệc độc thân nhớ đời, theo đúng cách của các chàng trai Mỹ vẫn làm. Nhưng mọi việc bất ngờ trở nên tồi tệ sau một đêm quậy tưng bừng, anh bạn Doug đã mất tích, trong phòng tắm có một con hổ, chàng nha sĩ Stu mất một chiếc răng, còn trong tủ áo thì đột nhiên xuất hiện thêm một đứa bé. Không thể liên lạc được với Doug, cũng như không nhớ nổi chuyện gì đã xảy ra vào tối hôm trước, cả ba bắt đầu lần tìm từ những manh mối còn sót lại trong phòng. Nguy cơ chú rể mất tích trong lễ cưới và hôn lễ phải hủy bỏ càng khiến cả ba càng lo lắng. Trên đường truy tìm tông tích Doug, bao chuyện bi hài tréo ngoe đã diễn ra với bộ ba....', 2009, '/ylPditP3F3Hy8ZhvVvhOPqbiklL.jpg', 7.3, '2026-08-12 13:54:44'),
(246, 284052, 'Phù Thuỷ Tối Thượng', 'tmdb-284052-ph-u-thu-ti-thng', 'DOCTOR STRANGE là câu chuyện về bác sĩ Giải Phẫu Thần Kinh tên Stephen Vincent Strange. Cuộc đời anh thay đổi từ sau một tai nạn xe hơi khủng khiếp. Sau tai nạn đó, Stephen nhận ra mình có những năng lực bí ẩn cũng như biết thêm về thế giới ma thuật huyền bí. Từ một vị bác sĩ bình thường, Stephen Strange dần nhận được nhiều siêu năng lực để cứu trái đất khỏi những tai họa.', 2016, '/rkklqyyUzYrJoo3iDYiTjGbhbaw.jpg', 7.4, '2026-08-12 13:54:44'),
(247, 76600, 'Avatar:  Dòng Chảy Của Nước', 'tmdb-76600-avatar-d-ong-chy-ca-nc', 'Câu chuyện của “Avatar: Dòng Chảy Của Nước” lấy bối cảnh 10 năm sau những sự kiện xảy ra ở phần đầu tiên. Phim kể câu chuyện về gia đình mới của Jake Sully (Sam Worthington thủ vai) cùng những rắc rối theo sau và bi kịch họ phải chịu đựng khi phe loài người xâm lược hành tinh Pandora.', 2022, '/luCqqHf10eQuGAYFO3U7JEqT4XC.jpg', 7.6, '2026-08-12 13:54:44'),
(248, 244786, 'Khát Vọng Nhịp Điệu', 'tmdb-244786-kh-at-vng-nhp-diu', 'Trong “Whiplash”, Miles Teller vào vai Andrew Neyman, một tay trống nhạc jazz trẻ khá tham vọng và quyết tâm theo đuổi đỉnh cao trong sự nghiệp âm nhạc bên bờ biển miền Đông nước Mỹ. Ám ảnh bởi sự nghiệp viết nhạc thất bại của người cha, Andrew ngày đêm nung nấu trở thành một nhạc công vĩ đại. Nhân vật thứ hai, Terence Fletcher (Simmons) là một huấn luyện viên nổi danh nhờ tài năng giảng dạy nhưng cũng khét tiếng bởi các phương pháp khắc nghiệt của ông, chuyên dẫn dắt các tài năng nhạc jazz hàng đầu trong trường nhạc. Fletcher phát hiện ra Andrew và mang tay trống về ban nhạc riêng của mình, thay đổi mãi mãi cuộc đời của chàng trai trẻ. Đam mê vươn tới sự hoàn hảo khiến Andrew rơi vào vòng xoáy của sự ám ảnh, bởi ông thầy tàn nhẫn ...', 2014, '/7fn624j5lj3xTme2SgiLCeuedmO.jpg', 8.4, '2026-08-12 13:54:44'),
(249, 2062, 'Chú Chuột Đầu Bếp', 'tmdb-2062-ch-u-chut-du-bp', 'Remy là một chú chuột có lòng yêu thích ẩm thực và mong muốn được đến Paris để thực hiện ước mơ trở thành đầu bếp nổi tiếng. Tuy bị gia đình ngăn cản nhưng cuối cùng Remy cũng đặt chân được đến kinh đô ánh sáng và bắt đầu cuộc phiêu lưu của mình.  Tại đây, Remy quen Linguini - cậu con trai của thần tượng đồng thời là bếp trưởng nổi tiếng của nhà hàng Gusteau. Remy và Linguini trở thành cặp bài trùng trong việc chế biến các món ăn mới lạ, đồng thời chứng mình quan niệm của Gusteau: \"Ai cũng có thể nấu ăn ngon\".', 2007, '/rkrU5jFUJ02NAxoU2GVdWsd1Hh6.jpg', 7.8, '2026-08-12 13:54:44'),
(250, 11324, 'Đảo Kinh Hoàng', 'tmdb-11324-do-kinh-ho-ang', 'Vào năm 1954, hai cảnh sát tư pháp Teddy Daniels và Chuck Aule được cử đến viện tâm thần Ashecliffe, trên Đảo Kinh Hoàng, cảng Boston, để điều tra vụ mất tích của Rachel Solando, một nữ bệnh nhân từng dìm chết 3 đứa con của mình.', 2010, '/ft9D2sRgDItfN5Lh9M4Wpwc3jVw.jpg', 8.2, '2026-08-12 13:54:44'),
(251, 863, 'Câu Chuyện Đồ Chơi 2', 'tmdb-863-c-au-chuyn-d-chi-2', 'Câu Chuyện Đồ Chơi 2 là cuộc phiêu lưu của Woody (Tom Hanks lồng tiếng) và Buzz Lightyear (Tim Allen) lại tiếp tục khi chủ nhân của chúng Andy (John Morris) đi tham dự trại hè và để mặc chúng ở nhà tự lo liệu. Woody không may bị một tay buôn bán đồ chơi đánh cắp. Buzz cùng các bạn đồ chơi bèn tìm cách giải cứu Woody. Mọi chuyện tưởng chừng thuận lợi nhưng trong khi bị giam giữ, Woody quen được Jessy - một tay \"cowgirl\". Thế là cả nhóm quyết định đưa luôn Jessy trở về nhà... sau khi trải qua bao khó khăn.', 1999, '/9bd3PHt2hZ3DDMRjn28Pmd6ZHqt.jpg', 7.6, '2026-08-12 13:54:45'),
(252, 549509, 'Giấc Mơ Mỹ', 'tmdb-549509-gic-m-m', 'Phim ghi lại 30 năm cuộc đời của László Tóth (Adrien Brody), một kiến trúc sư người Do Thái gốc Hungary sống sót sau thảm họa diệt chủng Holocaust. Sau khi Thế chiến thứ hai kết thúc, ông di cư sang Hoa Kỳ cùng với vợ mình, Erzsébet (Felicity Jones) để trải nghiệm “giấc mơ Mỹ”. László ban đầu phải chịu đựng nghèo đói và sự sỉ nhục, nhưng anh sớm đạt được hợp đồng với một khách hàng bí ẩn và giàu có, Harrison Lee Van Buren, điều đó sẽ thay đổi cuộc đời anh.', 2024, '/uyKDzg3ehpei3kKLZJU7DqSly5y.jpg', 6.9, '2026-08-12 13:54:45'),
(253, 575265, 'Nhiệm Vụ: Bất Khả Thi - Nghiệp Báo Cuối Cùng', 'tmdb-575265-nhim-v-bt-kh-thi-nghip-b-ao-cui-c-ung', 'Sau khi thoát khỏi vụ tai nạn tàu hỏa thảm khốc, Ethan nhận ra The Entity đang được giấu trên một chiếc tàu ngầm cũ của Nga, nhưng một kẻ thù trong quá khứ của anh tên là Gabriel cũng đang truy đuổi.', 2025, '/wxnbCpRKs8FV1SLZYA0mj1x26f9.jpg', 7.2, '2026-08-12 13:54:45'),
(254, 489, 'Chàng Will Tốt Bụng', 'tmdb-489-ch-ang-will-tt-bng', 'Cậu bé Will Hunting bất hạnh lớn lên trong những xó xỉnh của Boston tham gia vào vô số những trò vô bổ: uống rượu, đánh nhau… Nhưng cậu lại là người thông minh và rất yêu khoa học. Cuộc đời Will đã rẽ sang ngả khác khi anh được nhận vào làm bảo vệ cho Học viện Công nghệ Massachusetts. Một lần vì tò mò Will nhìn trộm buổi học của lớp toán ứng dụng. Cậu đặc biệt thích thú với bài toán hóc búa của giáo sư Gerald Lambeau, Will đã giải nó ngay trong đêm.... Good Will Hunting là minh chứng hùng hồn cho quan điểm nhân tài có ở mọi nơi không kể xuất thân, địa vị, hoàn cảnh chỉ cần có cơ hội họ sẽ thể hiện được năng lực của mình. Qua câu chuyện của Will lại một lần nữa vai trò giáo dục của gia đình được nhấn mạnh nếu Will ...', 1997, '/iRrgGkGg9q9pV6Hgg8fYU0nELJv.jpg', 8.2, '2026-08-12 13:54:45'),
(255, 106646, 'Sói Già Phố Wall', 'tmdb-106646-s-oi-gi-a-ph-wall', 'Tác phẩm về ông trùm chứng khoán Jordan Belfort vẽ nên một xã hội Mỹ tràn ngập tình dục, ma túy và đạo đức suy đồi vào cuối thập niên 1980, đầu thập niên 1990.  Phim được phóng tác dựa trên kịch bản chuyển thể từ cuốn hồi ký nổi tiếng ăn khách của Jordan Belfort, một tay môi giới cổ phiếu giá trị thấp từ Long Island đã trở nên cực kỳ nổi tiếng khi xuất bản cuốn hồi ký sau thời gian thụ án 20 tháng tù do từ chối hợp tác với cảnh sát điều tra trong vụ bê bối chứng khoán giả mạo đã suýt nữa làm sụp đổ cả phố Wall vào thập niên 90, dính líu đến giới ngân hàng và cả các băng đảng mafia. The Wolf Of Wall Street đã phản ánh sự thăng trầm của thế giới tài chính Wall Street cùng với những cuộc tiệc tùng chơi bời ngập trong ma túy và rượu chè, cuối cùng đã làm đảo lộn cuộc sống của những con người đắm chìm trong nó...', 2013, '/91Yf0MsBZtf4Nf8BJGlJ3cHShiK.jpg', 8.0, '2026-08-12 13:54:45'),
(256, 574475, 'Lưỡi hái tử thần: Huyết thống', 'tmdb-574475-li-h-ai-t-thn-huyt-thng', 'Bộ phim sẽ là xoay quanh một sinh viên đại học liên tục gặp các ác mộng về sự sụp đổ của gia đình cô, buộc cô phải trở về ngôi nhà của mình và tìm kiếm người có thể ngăn chặn điều đó xảy ra.', 2025, '/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', 7.0, '2026-08-12 13:54:45'),
(257, 1235877, 'ஜன நாயகன்', 'tmdb-1235877-movie', '', 2026, '/jt8pfSIdi47YpFMMWVRr8w5u2S0.jpg', 5.5, '2026-08-12 13:54:45'),
(258, 329505, 'Il peccato di Lola', 'tmdb-329505-il-peccato-di-lola', '', 1984, '/iQt9Kydd8yn9xfBvYeKec56glyv.jpg', 7.0, '2026-08-12 13:54:45'),
(259, 1156594, 'Lỗi Của Chúng Ta', 'tmdb-1156594-li-ca-ch-ung-ta', 'Đám cưới của Jenna và Lion vô tình trở thành chất xúc tác cho cuộc hội ngộ định mệnh giữa Noah và Nick – hai người từng yêu nhau say đắm nhưng chia tay trong tổn thương. Nick, người thừa kế một đế chế kinh doanh lừng lẫy, vẫn chưa thể tha thứ cho quá khứ. Còn Noah, cô gái đang chập chững trên con đường sự nghiệp, cố gắng chôn giấu cảm xúc chưa từng nguôi. Khi ánh mắt họ chạm nhau lần nữa, quá khứ và hiện tại hòa vào nhau – liệu tình yêu có đủ sức xóa nhòa những vết thương cũ, hay hận thù sẽ lại chia cách họ một lần nữa?', 2025, '/6kmi6vmp6iOn4KzI7WfnVtAeJhU.jpg', 7.4, '2026-08-12 13:54:45'),
(260, 12153, 'Những Cô Nàng Da Trắng', 'tmdb-12153-nhng-c-o-n-ang-da-trng', 'Được giao nhiệm vụ trông giữ cặp chị em nhà giàu não tàn, hai đặc vụ FBI da đen đóng giả làm những cô nàng gái da trắng ăn chơi để buộc những kẻ âm mưu bắt cóc lộ diện.', 2004, '/9OpiszlgXaj4PTxuMtIpACGjquX.jpg', 7.0, '2026-08-12 13:54:45'),
(261, 1716513, 'Extreme Makeover: Homer Edition', 'tmdb-1716513-extreme-makeover-homer-edition', '', 2026, '/vim76mMXig00YRxN2iGYJASoGkP.jpg', 7.2, '2026-08-12 13:54:45'),
(262, 39254, 'Tay Đấm Thép', 'tmdb-39254-tay-dm-th-ep', 'Phim đặt trong tương lai không xa, loài người tạo nên những robot siêu đẳng, khi mà quyền Anh robot trở thành môn thể thao phổ biến và có thể thay thế con người trổ tài trên sàn đấm bốc. Nhưng đó cũng là nơi Charlie - một võ sĩ quyền anh nổi tiếng với những cú đấm “thần sầu” - cảm thấy không thể hòa hợp. Đúng lúc ấy, anh tình cờ tìm được 1 chú robot ở bãi phế thải và tin rằng nó sẽ giúp anh vô địch. Trong khi Charlie theo đuổi hy vọng leo lên vị trí dẫn đầu thì một điều bất ngờ khác cũng đến với anh. Đứa con trai lưu lạc bấy lâu đột nhiên xuất hiện và muốn biết nhiều hơn về bố mình…', 2011, '/zDSsdnF2Hov7nSLFTTDKinNqAZP.jpg', 7.1, '2026-08-12 13:54:45'),
(263, 301528, 'Câu Chuyện Đồ Chơi 4', 'tmdb-301528-c-au-chuyn-d-chi-4', 'Woody luôn tự tin vào vị trí của bản thân mình, và luôn cho rằng sứ mệnh của anh ấy là chăm sóc cho những đứa trẻ, cho dù đó là Andy hay Bonnie. Vậy nên khi đồ chơi mới của Bonnie, Forky khẳng định bản thân là đồ bỏ đi, Woody đã cố gắng cho Forky thấy rằng cậu ấy sinh ra để thuộc về thế giới đồ chơi. Nhưng khi những món đồ chơi tham gia chuyến đi dã ngoại của Bonnie và gia đình cô, Woody đã vô tình có cuộc gặp mặt với người bạn lâu năm mất tích Bo Peep. Sau nhiều năm sống một mình, Bo Peep tin rằng mình có thể có một cuộc sống phiêu lưu thú vị hơn là làm một món đồ chơi bằng sứ. Khi Woody và Bo Peep nhận ra họ là những món đồ chơi thuộc về hai thế giới khác nhau, họ đã sớm cảm nhận được những mối lo lắng của mình.', 2019, '/ezIOA7SqfxoMSOUsnLtArWd6JPv.jpg', 7.5, '2026-08-12 13:54:45'),
(264, 1567187, 'Memoria de una madre', 'tmdb-1567187-memoria-de-una-madre', '', 2025, '/vhfrAIIe9jHiuD9qjOhLwnEgLdb.jpg', 5.3, '2026-08-12 13:54:45'),
(265, 89657, 'Country Hooker', 'tmdb-89657-country-hooker', '', 1974, '/v1idmJb9QWzhRllXlveKxYtsAHG.jpg', 4.2, '2026-08-12 13:54:45'),
(266, 372058, 'Tên Cậu Là Gì?', 'tmdb-372058-t-en-cu-l-a-g-i', 'Bộ phim là câu chuyện hoán đổi cơ thể của 2 cô cậu Mitsuha - nữ sinh trung học sống ở một thị trấn nhỏ của vùng Itomori và Taki – nam sinh tại thủ đô Tokyo đầy sôi động. Mitsuha luôn chán chường với cuộc sống tẻ nhạt của mình và mơ ước được làm anh chàng đẹp trai sống tại thủ đô. Trong khi đó, Taki hằng đêm lại nhìn thấy mình trong hình hài cô gái vùng miền quê. Ước mơ của cả 2 đã thành sự thật khi sao chổi nghìn năm xuất hiện trên trái đất và rồi cứ cách ngày lại được hoán đổi cơ thể cho nhau.', 2016, '/yV8ARrvpWaWd509QM4LwMScNDvZ.jpg', 8.5, '2026-08-12 13:54:45'),
(267, 945961, 'Quái Vật Không Gian: Romulus', 'tmdb-945961-qu-ai-vt-kh-ong-gian-romulus', 'Trong khi tìm kiếm những nơi sâu nhất của một trạm vũ trụ bị bỏ hoang, một nhóm những kẻ xâm chiếm không gian trẻ tuổi phải đối mặt với dạng sống đáng sợ nhất trong vũ trụ.', 2024, '/fTKWAzKGgeEoAb5gv0LWjQmhDao.jpg', 7.2, '2026-08-12 13:54:45'),
(268, 1430077, 'Ba Trợn', 'tmdb-1430077-ba-trn', 'Một nhà văn chuyên viết tiểu thuyết kinh dị đến một quán trọ hẻo lánh ở Ireland để rải tro cốt của cha mẹ mình. Không hay biết rằng nơi đây bị đồn đại là bị ám bởi một mụ phù thủy, anh dần nhận ra chuyến đi tưởng như riêng tư và yên lặng này đang kéo anh vào một nỗi kinh hoàng cổ xưa.', 2026, '/z4Kt0ZCgxSjRSvKmiSXw7y46AE.jpg', 6.9, '2026-08-12 13:54:45'),
(269, 1124, 'Ảo Thuật Gia Đấu Trí', 'tmdb-1124-o-thut-gia-du-tr-i', 'The Prestige xoay quanh hai ảo thuật gia đại tài là Robert Angier (Hugh Jackman) và Alfred Borden (Christian Bale). Ban đầu họ là những người bạn, thế nhưng bởi giấc mơ tạo ra tiết mục hấp dẫn nhất quá lớn, khiến họ đã bị cuốn vào một cuộc cạnh tranh một mất một còn với kết cục bi thảm.  Cũng mang đậm dấu ấn như bao phim khác của Christopher Nolan, The Prestige có kết cấu tương đối phức tạp. Cách kể chuyện không theo trình tự thời gian dẫn đến có đôi chỗ người xem sẽ cảm thấy mơ hồ, khó nắm bắt.', 2006, '/fAT5JUet2JDcsukQI1fNZXJ20KK.jpg', 8.2, '2026-08-12 13:54:45'),
(270, 572802, 'Aquaman và Vương Quốc Thất Lạc', 'tmdb-572802-aquaman-v-a-vng-quc-tht-lc', 'Giờ đây, Arthur Curry ngày nào đã trở thành ông bố bỉm sữa ngày ngày chăm con kiêm cai quản cả vùng Atlantis rộng lớn. Thế nhưng, kẻ thù cũ đời nào để cho nhà vua biển cả yên ổn. Nhờ sự trợ giúp của công nghệ, Black Manta lần nữa trỗi dậy với sức mạnh kinh khủng hơn xưa. Không thể chiến đấu một mình, Arthur đành phải nhờ sự trợ giúp của một kẻ thù khác - đứa em cùng mẹ khác cha Orm. Cùng chống lại kẻ thù chung, liệu cặp anh em chẳng đội chung trời này có thể hàn gắn tình cảm?', 2023, '/sjLLA6PGxoN0kmCuwxgb8CR0F29.jpg', 6.5, '2026-08-12 13:54:45'),
(271, 1078605, 'Giờ Mất Tích', 'tmdb-1078605-gi-mt-t-ich', 'Khi tất cả học sinh trong cùng một lớp bất ngờ biến mất trong cùng một đêm, vào đúng một thời điểm — chỉ trừ lại một em nhỏ duy nhất — cả cộng đồng rơi vào hoang mang tột độ, tự hỏi: ai… hoặc điều gì đứng sau sự biến mất bí ẩn ấy?', 2025, '/lVY3xYt7ai6ahduq3D7F2z5wwin.jpg', 7.3, '2026-08-12 13:54:47'),
(272, 38365, 'Những Đứa Trẻ To Xác', 'tmdb-38365-nhng-da-tr-to-x-ac', 'Phim miêu tả về năm người bạn thân lâu năm từ đội bóng rổ trung học và gia đình họ đoàn tụ nhân ngày nghỉ lễ Quốc khánh sau khi biết rằng thầy của họ đột ngột qua đời.', 2010, '/lZqpy6PI383QYZ2h2fVxbPrvcCq.jpg', 6.4, '2026-08-12 13:54:47'),
(273, 272, 'Người Dơi Bắt Đầu', 'tmdb-272-ngi-di-bt-du', 'Bruce Wayne thuở nhỏ là một cậu bé mắc chứng sợ dơi và có bố mẹ bị giết bởi tên cướp tên Joe Chill. Lớn lên, nung nấu ý định trả thù, Bruce Wayne rời khỏi thành phố và gặp được Henri Ducard, người truyền dạy cho anh những bí kíp võ thuật. Từ đây, với bản chất lương thiện, Bruce Wayne trở thành người hùng trừ gian diệt ác của thành phố… Với sự tham gia của dàn diễn viên nổi tiếng Christian Bale, Katie Holmes, Gary Oldman và được dàn dựng bởi đạo diễn tài ba Christopher Nolan, chỉ vài tháng sau khi ra mắt, Batman Begins đã được độc giả của tạp chí Empire bầu chọn đứng thứ 36 trong các phim hay nhất mọi thời đại, trở thành một trong những huyền thoại của dòng phim siêu anh hùng.', 2005, '/ziFjqY3ABYTJZ2kHMzjr3eeyMQZ.jpg', 7.7, '2026-08-12 13:54:47'),
(274, 216919, 'Deseo', 'tmdb-216919-deseo', '', 2013, '/df6rkcD37S1RN34vHuA3dSs0uJp.jpg', 6.5, '2026-08-12 13:54:47'),
(275, 22, 'Cướp Biển Vùng Caribbean: Lời Nguyền Tàu Ngọc Trai Đen', 'tmdb-22-cp-bin-v-ung-caribbean-li-nguyn-t-au-ngc-trai-den', 'Khi chiếc thuyền của gia đình cô bé Elizabeth đi qua vùng biển Caribe nhiều cướp biển họ đã cứu được cậu bé Will Turner. Cả gia đình Elizabeth không hề biết rằng Will là William Turner, con trai của một tên trùm cướp biển khét tiếng.  Nhiều năm sau, mọi chuyện dần dần được hé lộ khi Elizabeth bị ngã xuống biển do một tai nạn và được thuyền trưởng Jack Sparrow cứu thoát.', 2003, '/hQjENbYuhkjcr8c8O8tpQxw0XOD.jpg', 7.8, '2026-08-12 13:54:47'),
(276, 436270, 'Black Adam', 'tmdb-436270-black-adam', 'Dwayne Johnson sẽ góp mặt trong tác phẩm hành động - phiêu lưu mới của New Line Cinema, mang tên BLACK ADAM. Đây là bộ phim đầu tiên trên màn ảnh rộng khai thác câu chuyện của siêu anh hùng DC này, dưới sự sáng tạo của đạo diễn Jaume Collet-Serra (đạo diễn của Jungle Cruise). Gần 5.000 năm sau khi bị cầm tù với quyền năng tối thượng từ những vị thần cổ đại, Black Adam (Dwayne Johnson) sẽ được giải phóng khỏi nấm mồ chết chóc của mình, mang tới thế giới hiện đại một kiểu nhận thức về công lý hoàn toàn mới.', 2022, '/oAT0oFl0GWeIjpo1WnF601GFpwm.jpg', 6.8, '2026-08-12 13:54:47'),
(277, 567609, 'Trò Chơi Của Quỷ', 'tmdb-567609-tr-o-chi-ca-qu', 'Phim theo chân Grace, một cô dâu trẻ theo chân người chồng mới của mình tham gia vào một truyền thống của gia đình chồng giàu có và đầy lập dị. Không may nó biến thành một trò chơi đầy chết chóc và tất cả đều phải chiến đấu để bảo vệ mạng sống của mình.', 2019, '/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', 7.1, '2026-08-12 13:54:47'),
(278, 198663, 'Giải Mã Mê Cung', 'tmdb-198663-gii-m-a-m-e-cung', 'The Maze Runner là bộ phim được chuyển thể từ bộ truyện cùng tên có nội dung giả tưởng về nhóm bạn trẻ bị giam giữ trong \'Trảng\' với một trí nhớ không rõ ràng, và cuộc vật lộn tìm lối thoát. Làm thế nào họ sống sót được giữa một mê cung khổng lồ đầy những sinh vật nguy hiểm và thay đổi lời giải hằng đêm? Ai sẽ là người sống sót cuối cùng sau những bí mật chết người kia?', 2014, '/xSPITZs1i89L2DzHjOxp311Mxr9.jpg', 7.2, '2026-08-12 13:54:47'),
(279, 228150, 'Cuồng Nộ', 'tmdb-228150-cung-n', 'Fury được đặt bối cảnh vào năm 1945, khi Thế Chiến đệ nhị đang đi vào giai đoạn cuối và lực lượng Đồng Minh đang dồn tổng lực tấn công phe Phát xít Đức. Tại chiến trường Tây Đức, một tiểu đội do trung sĩ Don với biệt danh “Wardaddy” chỉ huy có nhiệm vụ điều khiển chiếc xe tăng “Fury” cùng những chiếc xe tăng khác thọc sâu vào phòng tuyến của quân Đức để hỗ trợ lực lượng bộ binh. Khi chuẩn bị thực hiện một chiến dịch mới thì họ mất đi đồng đội, người thay thế lại là một tân binh chưa hề nếm mùi chiến trường, Norman (Lorgan Lerman).Anh chàng được đào tạo để làm người truyền tin, vốn chỉ quen đánh máy và chưa bao giờ bước vào bên trong một chiếc xe tăng giờ đây được đưa vào giữa lòng địch, bên cạnh ...', 2014, '/zWlPqmSRxIHXH6lfYCx4xjj14sa.jpg', 7.5, '2026-08-12 13:54:47'),
(280, 912649, 'Venom: Kèo Cuối', 'tmdb-912649-venom-k-eo-cui', 'Đây là phần phim cuối cùng và hoành tráng nhất về cặp đôi Venom và Eddie Brock (Tom Hardy). Sau khi dịch chuyển từ Vũ trụ Marvel trong ‘Spider-man: No way home’ (2021) trở về thực tại, Eddie Brock giờ đây cùng Venom sẽ phải đối mặt với ác thần Knull hùng mạnh - kẻ tạo ra cả chủng tộc Symbiote và những thế lực đang rình rập khác. Cặp đôi Eddie và Venom sẽ phải đưa ra lựa quyết định khốc liệt để hạ màn kèo cuối này.', 2024, '/64hJDbJlLFJSRg4sG3njMCijIyF.jpg', 6.7, '2026-08-12 13:54:47'),
(281, 564, 'Xác Ướp 1', 'tmdb-564-x-ac-p-1', 'Một nhóm nhà khảo cổ dẫn đầu là O’Connell tiến hành cuộc hành trình tới xứ sở của kim tự tháp. Họ có tham vọng khám phá bí mật của xác ướp thầy tu Imhotep, nhưng vô tình đem lại cơ hội hồi sinh cho hắn, khiến cuộc chiến sinh tồn nổ ra.  Bộ ba Rick – Evelyn – Jonathan rời Cairo xuôi theo dòng dông Nile, ngang qua sa mạc Sahara và họ bắt đầu nhận ra sự khắc nghiệt của thiên nhiên không là gì so với những thế lượng đen tối họ phải đối đầu. Đó là những kẻ tham lam vô độ không ngại gì sự huyền bí của Ai Cập tới kiếm tìm châu báu và sự tấn công của xác ướp hồi sinh Imhotep cùng nhân tình của hắn Anck-su-namun vì để hồi sinh cho người tình, Imhotep cần máu và cơ thể của Evelyn.  Mối nguy hiểm không chỉ đến với những kẻ săn kho báu và đoàn khảo cổ của Rick mà nó đã trở thành sự đe dọa cho toàn thế giới khi Imhotep âm mưu gây dựng lại đế chế độc tài Ai Cập cổ xưa bằng phép thuật của một thầy tu quyền năng.', 1999, '/rzbRuZDEER9UpRzL946PiHtq1tY.jpg', 7.0, '2026-08-12 13:54:47'),
(282, 1422, 'Điệp Vụ Boston', 'tmdb-1422-dip-v-boston', 'The Departed (Điệp Vụ Boston) là bộ phim được dựng lại từ siêu phẩm Vô Gian Đạo (Infernal Affairs) của Hồng Kông. Nội dung phim xoay quanh hai con người có hai lai lịch hoàn toàn khác nhau nhưng lại đi chung một con đường: làm nội gián. Billy Costigan, một cảnh sát chìm được cài vào băng nhóm tội phạm do Frank Costello cầm đầu. Cùng lúc này, nhân viên cảnh sát Colin Sullivan lại là một tay tội phạm được đưa vào nội bộ cảnh sát nhằm cung cấp tin tức cho Frank. Cả hai bước vào cuộc rượt đuổi với nhiệm vụ khai thác thông tin mật của mỗi bên, đồng thời phải che giấu thân phận thật sự của mình...', 2006, '/cpYKWyjc4Tdtcmdqbt6MUTNpx44.jpg', 8.2, '2026-08-12 13:54:47'),
(283, 299537, 'Đại Úy Marvel', 'tmdb-299537-di-uy-marvel', 'Từ xa xưa, hai tộc Kree và Skrulls đã xảy ra cuộc chiến tranh kéo dài rất lâu, gọi là Chiến tranh Kree–Skrull. Với trình độ kĩ thuật phát triển, người Kree dần áp đảo trong cuộc chiến và khiến cho số lượng người Skrulls bị giảm đi đáng kể.  Năm 1995, Vers thức giấc tại Hala, quê hương của Đế chế Kree. Cô luôn bị ác mộng về một vụ rơi máy bay, và về một người phụ nữ bị sát hại trước mặt mình. Trí nhớ của cô dừng lại tại thời điểm cô đạt được sức mạnh của mình. Cô được Yon-Rogg, thủ lĩnh của Starforce huấn luyện để trở thành thành viên của đội. Mặc dù Yon-Rogg tin rằng cô đã sẵn sàng nhưng Supreme Intelligence, một trí tuệ nhân tạo có vai trò điều hành Đế chế Kree lại không cho cô gia nhập đội, nơi mà có Minn-Erva - một xạ thủ bắn tỉa và các cộng sự Korath, Bron-Char và Att-Lass.', 2019, '/cYq1wkJK2y44SeX79VXzRZP46iX.jpg', 6.8, '2026-08-12 13:54:47'),
(284, 808, 'Shrek', 'tmdb-808-shrek', 'Vương quốc Xa thật xa là nơi các nhân vật cổ tích sinh sống. Shrek, gã chằn xanh đang sống yên bình tại đầm lầy của mình. Bỗng nhiên, khu đầm trở thành nơi \"tị nạn\" của các nhân vật cổ tích đang bị lãnh chúa Farquaad săn đuổi. Để khỏi phải \"chung đụng\" với đám dân ở nhờ ồn ào, Shrek ký giao kèo cùng Farquaad. Gã sẽ đi cứu công chúa Fiona, đang bị giam giữ trong tòa tháp cao vợi, và được rồng canh giữ. Farquaad có được cô dâu trong mộng thì Farquaad phải để các nhân vật cổ tích kia được yên.', 2001, '/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', 7.8, '2026-08-12 13:54:47'),
(285, 11036, 'Nhật Ký Tình Yêu', 'tmdb-11036-nht-k-y-t-inh-y-eu', 'Dựa trên cuốn tiểu thuyết của nhà văn Nicholas Sparks xuất bản năm 1996, bộ phim là câu chuyện tình giữa Noah và Allie kể từ lần đầu họ gặp nhau tại North Carolina vào thập niên 40. Như mọi mối tình ngang trái khác, tình cảm giữa Noah và Allie gặp phải rào cản, xa cách trong nhiều năm liền trước khi đoàn tụ mãi mãi về sau.', 2004, '/jSM8ufnkCpdf5sVHu9ESFQDowRF.jpg', 7.9, '2026-08-12 13:54:47'),
(286, 20352, 'Kẻ Trộm Mặt Trăng', 'tmdb-20352-k-trm-mt-trang', 'Nhân vật tâm điểm của bộ phim là Gru, một tên tội phạm khét tiếng. Gru và đám tay chân robot tí hon chuyên đi đánh cắp những biểu tượng nổi tiếng của thế giới. Thế nhưng tiếng xấu của Gru bị suy giảm khi tên tội phạm trẻ tuổi Vector đã ăn cắp kim tự tháp của Ai Cập. Gru quyết định làm phi vụ có một không hai cho thế giới phải bái phục: ăn cắp mặt trăng. Trước tiên, Gru phải đánh cắp khẩu súng có khả năng thu nhỏ mọi vật từ quân đội. Nhưng Vector đã nẫng tay trên khẩu súng thần kỳ từ Gru. Mọi kế hoạch giành lại cây súng của Gru đều bị Vector đánh bại. Cuối cùng, Gru nghĩ ra cách dùng ba đứa trẻ của viện mồ côi xâm nhập sào huyệt của Vector. Thế nhưng ba đứa trẻ Margo, Edith, Agnes đã cảm hóa Gru bằng sự ngây thơ, hướng thiện của mình.', 2010, '/txfb1LyIEGJ69wTPJUiyufZVN4A.jpg', 7.3, '2026-08-12 13:54:47'),
(287, 246655, 'X-Men 6: Cuộc Chiến Chống Apocalypse', 'tmdb-246655-x-men-6-cuc-chin-chng-apocalypse', 'Apocalypse là dị nhân đầu tiên và hùng mạnh nhất của vũ trụ X-Men, đã tích lũy được rất nhiều quyền năng đột biến khác nhau, trở thành kẻ bất tử và bất khả chiến bại. Sau khi tỉnh dậy từ giấc ngủ hàng ngàn năm, hắn cảm thấy thất vọng với thế giới này và năng lực đáng sợ nhất của hắn là khống chế những người khác và biến họ thành kỵ sĩ của mình, nhằm tẩy sạch nhân loại và tạo ra một trật tự thế giới mới và qua đó, hắn sẽ trị vì nó. Số phận của Trái Đất phải đối mặt với tình huống ngàn cân treo sợi tóc, Raven cùng với sự giúp đỡ của Giáo Sư X buộc phải dẫn dắt một đội X-Men trẻ tuổi nhằm chống lại kẻ thù lớn nhất từ trước đến nay và cứu rỗi nhân loại khỏi sự diệt chủng.', 2016, '/7O2B3OZkmsGWUXi0QBV2oPxzgoa.jpg', 6.5, '2026-08-12 13:54:47'),
(288, 939243, 'Nhím Sonic 3', 'tmdb-939243-nh-im-sonic-3', 'Sonic, Knuckles và Tails phải đối mặt với một kẻ thù mới cực kỳ mạnh mẽ là Shadow - một nhân vật phản diện bí ẩn với sức mạnh không giống bất kỳ đối thủ nào họ từng đối mặt trước đây. Bị áp đảo về năng lực, Sonic phải lên đường thành lập một liên minh to lớn hơn.', 2024, '/bf0M9MxiaoM5JZA3trIxsGftGRI.jpg', 7.6, '2026-08-12 13:54:47'),
(289, 102899, 'Ant-Man: Người Kiến', 'tmdb-102899-ant-man-ngi-kin', 'Câu chuyện bắt đầu từ giáo sư Hank Pym (Michael Douglas thủ vai), Người Kiến đầu tiên với phát minh vĩ đại là bộ giáp biến đổi kích cỡ con người. Không chỉ thu nhỏ cơ thể để chiến đấu linh hoạt, bộ giáp siêu hạng còn đem lại những năng lực đặc biệt như trò chuyện với kiến, di chuyển với tốc độ nhanh. Nhưng thật không may, công nghệ tạo ra bộ giáp đã bị Darren Cross (Yellowjacket) chiếm đoạt và đưa vào sản xuất hàng loạt. Tất nhiên, “nếu trao quyền năng của Thượng đế cho tất cả mọi người thì thế giới này sẽ trở nên hỗn loạn”. Để ngăn chặn mối nguy hại đến từ Yellowjacket, giáo sư Hank Pym cùng trợ thủ Hope van Dyne (Evangeline Lilly thủ vai) đã tìm đến Scott Lang – một tên trộm vặt lừng danh từng vào tù ra tội, để nhờ anh lấy lại công nghệ đặc biệt và ngăn chặn Yellowjacket. Scott đã trở thành Người Kiến tiếp theo, bắt đầu làm quen với việc điều khiển bộ giáp và sử dụng các siêu năng lực đặc biệt.', 2015, '/oVZIVwOXZuZ28xLhsGlY0LlfP41.jpg', 7.1, '2026-08-12 13:54:47'),
(290, 286217, 'Người Về Từ Sao Hỏa', 'tmdb-286217-ngi-v-t-sao-ha', 'The Martian xoay quanh hành trình trở về đầy phi thường của phi hành gia Mark Watney. Trong quá trình thực hiện nhiệm vụ trên sao Hỏa, Mark Watney (Matt Damon) được cho rằng đã tử nạn sau một trận bão lớn và bị mọi người bỏ lại phía sau.  Tuy nhiên, Watney may mắn sống sót và bị mắc kẹt một mình trên hành tinh cằn cỗi. Anh sẽ phải sử dụng tất cả kinh nghiệm và kiến thức của mình để tiếp tục tồn tại trên một hành tinh không có sự sống và hi vọng một ngày sẽ được cứu thoát. Quan trọng hơn cả, Watney luôn giữ cho mình một nghị lực kiên cường và tinh thần thật lạc quan. Mặc dù cách xa đến hàng triệu dặm, NASA và các nhà khoa học quốc tế vẫn làm việc không mệt mỏi để có thể đưa Watney trở về an toàn.', 2015, '/73WiP7qwfrBWEcFsarDSe6S692q.jpg', 7.7, '2026-08-12 13:54:47'),
(291, 616037, 'Thor: Tình Yêu và Sấm Sét', 'tmdb-616037-thor-t-inh-y-eu-v-a-sm-s-et', 'Vốn từng là một chiến binh hùng mạnh của Asgard, trải qua vô số trận chiến lớn nhỏ nhưng sau sự kiện trong Avengers: Endgame (2019) cùng vô số mất mát, Thần Sấm không còn muốn theo đuổi con đường siêu anh hùng. Từ đây, anh lên đường tìm ra ý nghĩa của cuộc sống và nhìn nhận lại bản thân mình.', 2022, '/xeg0UhMmzSalvyK7kvhTHcKXIf8.jpg', 6.4, '2026-08-12 13:54:48'),
(292, 389, '12 Người Đàn Ông Giận Dữ', 'tmdb-389-12-ngi-d-an-ong-gin-d', 'Một thanh niên bị tình nghi giết cha ruột của mình. 12 người của bồi thẩm đoàn bắt đầu phiên làm việc của mình và tất cả hội thẩm viên đều muốn kết thúc nhanh chóng vụ án vì các chứng cứ đã quá rõ ràng. Trừ một người duy nhất. Ông không muốn sinh mạng của một con người lại có thể được quyết định chỉ trong vòng chưa đầy 10 phút.  Ông có một sự nghi ngờ riêng đối với vụ án kỳ lạ này. Và ông quyết định: tìm cách thuyết phục mọi người. Nhưng ông sẽ làm gì để giúp cậu bé kia và thuyết phục những người trong bồi thẩm đoàn đây?', 1957, '/aa4s7J0ld2UHUooc1H8o1sNuZ2m.jpg', 8.6, '2026-08-12 13:54:48'),
(293, 44980, 'Zero WOMAN ＩＩ　警視庁０課の女', 'tmdb-44980-zero-woman-ii-0', '', 1995, '/z9XSICETB0XWQRyMWpN2s3bAUlz.jpg', 5.0, '2026-08-12 13:54:48'),
(294, 614945, 'Thư thoại cho Isabelle', 'tmdb-614945-th-thoi-cho-isabelle', 'Những tin nhắn thoại hài hước và đầy tâm sự mà một cô gái trẻ gửi cho người chị quá cố vô tình được chuyển đến một người lạ – và anh dần phải lòng cô từ phương xa.', 2026, '/canZTWSxACSnAluir3dCtMxKpA1.jpg', 8.4, '2026-08-12 13:54:48'),
(295, 1613798, 'Venganza', 'tmdb-1613798-venganza', '', 2026, '/ggJGx8fwwy21gEIXYusIlHcUn8z.jpg', 7.5, '2026-08-12 13:54:48'),
(296, 1062722, 'Frankenstein', 'tmdb-1062722-frankenstein', 'Guillermo del Toro mang đến phiên bản mới đầy viễn kiến cho câu chuyện gothic của Mary Shelley về một nhà khoa học lỗi lạc mà kiêu ngạo bị chính tạo vật bi thảm của mình hủy hoại.', 2025, '/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', 7.6, '2026-08-12 13:54:48'),
(297, 1417285, 'Ma Nữ Oán Tình', 'tmdb-1417285-ma-n-o-an-t-inh', 'Mang theo những ám ảnh từ quá khứ, Malee - do Engfa thủ vai, trở về khu căn hộ gắn liền với tuổi thơ và tìm thấy tình yêu bên Pran – một nhà thực vật học đam mê nghệ thuật pha trà. Thế nhưng, sự xuất hiện của những mối quan hệ xung quanh Pran cùng những bí mật tưởng đã bị chôn vùi từ lâu dần làm xáo trộn mọi thứ. Khi một cái chết bất ngờ xảy ra, những sự thật đen tối dần dần được phơi bày.', 2026, '/gOxyxF7Vj0Zv9lDRUoHv8BYdqWb.jpg', 4.0, '2026-08-12 13:54:48'),
(298, 533533, 'Trò Chơi Ảo Giác: Ares', 'tmdb-533533-tr-o-chi-o-gi-ac-ares', 'Một chương trình trí tuệ nhân tạo siêu việt mang tên Ares được gửi từ thế giới số vào thế giới thực trong một nhiệm vụ đầy nguy hiểm — đánh dấu lần đầu tiên nhân loại tiếp xúc trực tiếp với một thực thể A.I. sống động.', 2025, '/lj7imLGAzI3zKvbJtPH01aYW9lU.jpg', 6.5, '2026-08-12 13:54:48'),
(299, 4935, 'Lâu Đài Bay Của Pháp Sư Howl', 'tmdb-4935-l-au-d-ai-bay-ca-ph-ap-s-howl', 'Sophie vốn dĩ làm việc tại cửa hàng mũ do người cha quá cố để lại. Cuộc sống nơi thị trấn buồn tẻ cứ thế trôi qua trong lặng lẽ... cho đến ngày cô bỗng biến thành bà lão.', 2004, '/jEa7VIZvKYr3iACvcfNqGWDUIun.jpg', 8.4, '2026-08-12 13:54:48'),
(300, 346698, 'Barbie', 'tmdb-346698-barbie', 'Barbie sẽ được nhào nặn và chắp bút bởi nữ đạo diễn kiêm biên kịch từng nhận nhiều Đề cử Tượng vàng Oscar – Greta Grewig. Hai nhân vật chính Barbie và Ken sẽ được hóa thân bởi nữ diên viên Margot Robbie và nam thần Ryan Gosling, hứa hẹn sẽ tạo nên “chemistry” đáng yêu giữa hai nhân vật búp bê nổi tiếng thế giới.', 2023, '/sO3V9AgFsdo9jzf8th4HQiOjGJA.jpg', 6.9, '2026-08-12 13:54:48'),
(301, 1598766, 'Phim Shin – Cậu Bé Bút Chì: Kỳ Kỳ Quái Quái! Kỳ Nghỉ Yêu Quái Của Tớ', 'tmdb-1598766-phim-shin-cu-b-e-b-ut-ch-i-k-y-k-y-qu-ai-qu-ai-k-y-ngh-y-eu-qu-ai-ca-t', 'Lấy bối cảnh mùa hè tại Akita, bộ phim theo chân Shin và gia đình Nohara trong chuyến về quê đầy háo hức. Tuy nhiên, một sự kiện kỳ lạ đã đưa cả gia đình lạc vào Xứ sở Yêu quái bí ẩn – nơi con người không được phép đặt chân tới. Tại đây, Shin và gia đình phải đối mặt với những thử thách chưa từng có, đồng thời gặp gỡ hàng loạt yêu quái độc đáo, hài hước và đáng yêu. Với sự kết hợp giữa yếu tố phiêu lưu, kỳ ảo, hài hước đặc trưng của Shin-chan cùng những thông điệp gia đình ấm áp, bộ phim hứa hẹn mang đến một hành trình giải trí hấp dẫn cho khán giả ở mọi lứa tuổi trong mùa hè này.', 2026, '/i8IHfU0GmbVex65c3WaEXsOBk8x.jpg', 0.0, '2026-08-12 13:54:48'),
(302, 226674, 'L\'Adolescente', 'tmdb-226674-l-adolescente', '', 1979, '/v7yCEzF9BCF82lbp42X5ZLjIieo.jpg', 4.7, '2026-08-12 13:54:48'),
(303, 1391021, '欢迎来龙餐馆', 'tmdb-1391021-movie', '', 2026, '/blpRVNJ9iHtobHOi6rIkQzSWlWv.jpg', 9.0, '2026-08-12 13:54:48'),
(304, 1491920, 'Đội Bóng Nữ Túc', 'tmdb-1491920-di-b-ong-n-t-uc', '', 2026, '/7H9Gkdr9V5KMM6STtCRdTuRD2Zd.jpg', 6.0, '2026-08-12 13:54:48'),
(305, 448772, 'Un grande amore', 'tmdb-448772-un-grande-amore', '', 1995, '/jZolzsQj3zPINjmGuNuIA6iZPZG.jpg', 5.0, '2026-08-12 13:54:48'),
(306, 857, 'Giải Cứu Binh Nhì Ryan', 'tmdb-857-gii-cu-binh-nh-i-ryan', 'Bắt đầu với cuộc xâm lược của quân Đồng minh Normandy vào ngày 6 tháng 6 năm 1944, các thành viên của tiểu đoàn tấn công thứ hai, dưới quyền Đại úy Miller, chiến đấu để giành quyền kiểm soát bãi biển. Trong trận chiến, hai anh em bị giết. Một chút trước đó, ở New Guinea, một người anh em thứ ba cũng bị giết. Mẹ của ông, bà Ryan, sẽ nhận được ba bức điện tử trong cùng một ngày. Người đứng đầu quân đội Mỹ, George C. Marshall, nhìn thấy cơ hội làm giảm bớt nỗi đau khổ của cô khi anh biết được một người anh em thứ tư, Private James Ryan, và quyết định cử tám người (Thuyền trưởng Miller và một nhóm được chọn từ tiểu đoàn của anh ta) đi tìm Anh ta và đưa anh ta trở về nhà của mẹ mình.', 1998, '/wz11UlVEmJjmNnRnrWH8MqItj5A.jpg', 8.2, '2026-08-12 13:54:48'),
(307, 967941, 'Wicked: Phần 2', 'tmdb-967941-wicked-phn-2', 'Bộ phim chuyển thể từ sân khấu Broadway thành công nhất mọi thời đại, hiện tượng điện ảnh toàn cầu năm 2024 nay chính thức đi đến hồi kết hoành tráng, kịch tính và đầy cảm xúc trong Wicked: Phần 2. Chương cuối của câu chuyện bắt đầu khi Elphaba và Glinda đã xa cách, mỗi người đang sống với hậu quả từ những lựa chọn của riêng mình. Elphaba giờ đây bị cả xứ Oz xem như Phù thủy độc ác phương Tây, trong khi đó Glinda đã trở thành biểu tượng quyến rũ của Lòng tốt đối với toàn bộ xứ Oz. Và mọi thứ thay đổi khi một cô gái đến từ Kansas bất ngờ xuất hiện, khiến cuộc sống của xứ Oz bị đảo lộn. Glinda và Elphaba buộc phải cùng nhau đối mặt lần cuối, họ phải thật sự thấu hiểu nhau, bằng sự trung thực và đồng cảm, nếu muốn thay đổi chính mình và cả vận mệnh của xứ Oz. Liệu Elphaba và Glinda có thể vượt qua số phận đã được định sẵn để viết lại tương lai cho xứ sở phép màu này?', 2025, '/oQSPp51Uv74civ9gv3wqJmqlJVX.jpg', 6.6, '2026-08-12 13:54:48'),
(308, 194117, 'La donna della luna', 'tmdb-194117-la-donna-della-luna', '', 1988, '/6uiz2xx61qhGv3ZcZg0n5tgahY3.jpg', 5.6, '2026-08-12 13:54:48'),
(309, 1292415, 'Quái Vật Võ Đài', 'tmdb-1292415-qu-ai-vt-v-o-d-ai', '', 2026, '/7NrvUI3vnW8H3rD7ExKcTL7KRcQ.jpg', 6.4, '2026-08-12 13:54:48'),
(310, 1202033, 'Enola Holmes 3', 'tmdb-1202033-enola-holmes-3', 'Cuộc phiêu lưu đưa nữ thám tử Enola Holmes đến Malta, nơi kế hoạch kết hôn của cô đảo lộn khi sự biến mất của Sherlock kéo cô vào một vụ án nguy hiểm.', 2026, '/7kRYHH9H9PjBFwz1FprbHB2AAjI.jpg', 6.8, '2026-08-12 13:54:48');
